enum class MenuSound : size_t {
    PrimaryActivation,
    Primary = PrimaryActivation,
    Back,
    Focus,
    HoverIn,
    EnumSelection,
    SliderClickDown,
    TurnOn,
    TurnOff,
    ActionFailed,
    SecondaryActivation,
    Mute,
    Unmute,
    Count,
};
static constexpr size_t kMenuSoundCount =
    static_cast<size_t>(MenuSound::Count);
struct InstalledMenuSounds {
    std::array<bf6::ui_runtime::InstalledSoundWave, kMenuSoundCount> waves;
    std::array<bool, kMenuSoundCount> ready{};
};
static std::mutex g_menuSoundLock;
static InstalledMenuSounds g_menuSounds;
// Constructed and used on the render thread. The worker publishes only copied
// PCM; it never creates an XAudio2 voice and the render thread never reads
// libbf6 for sound playback.
static bf6::ui_runtime::PcmOneShotPlayer g_menuSoundPlayer;

static bool PlayMenuSound(MenuSound sound)
{
    std::lock_guard<std::mutex> lock(g_menuSoundLock);
    const size_t index = static_cast<size_t>(sound);
    if (index >= kMenuSoundCount || !g_menuSounds.ready[index]) return false;
    const bf6::ui_runtime::InstalledSoundWave& wave =
        g_menuSounds.waves[index];
    std::string error;
    if (g_menuSoundPlayer.Play(wave, 1.0f, error)) return true;
    static bool reported = false;
    if (!reported) {
        reported = true;
        std::fprintf(stderr, "menu XAudio2 playback failed: %s\n", error.c_str());
    }
    return false;
}

struct Vtx { float p[3]; float n[3]; float tangent[4]; float t[2]; float t1[2]; };

struct GpuSection {
    ID3D11Buffer* vb = nullptr;
    ID3D11Buffer* ib = nullptr;
    UINT          index_count = 0;
    std::vector<Vtx> bind_verts;
    std::vector<Vtx> animated_verts;
    std::vector<uint16_t> skin_bones;
    std::vector<float> skin_weights;
    int skin_influences = 0;
    ID3D11ShaderResourceView* srv[9] = {}; // generic 0..3; eye iris/sclera/normals/mask 4..8
    XMFLOAT4 base_color = XMFLOAT4(1, 1, 1, 1);
    XMFLOAT4 material = XMFLOAT4(0.5f, 0.f, 0.f, 0.f); // rough, metal, NSM, has albedo
    XMFLOAT4 emissive = XMFLOAT4(0.f, 0.f, 0.f, 0.f);
    XMFLOAT4 render_flags = XMFLOAT4(0.f, 0.f, 0.f, 0.f); // alpha test, from albedo, has mask, translucent
    XMFLOAT4 shader_flags = XMFLOAT4(0.f, 0.f, 0.f, 0.f); // x = exact eye shader record
};

struct GpuMesh {
    std::vector<GpuSection> sections;
    std::vector<bf6_bone_xform> animation_skin_frames;
    int animation_frame_count = 0;
    int animation_bone_count = 0;
    int animation_rig_bone_count = 0;
    float animation_fps = 0.f;
    bool animation_rigid = false;
    bool animation_post_transform_active = false;
    float animation_post_transform[12] = {
        1.f, 0.f, 0.f, 0.f, 1.f, 0.f, 0.f, 0.f, 1.f, 0.f, 0.f, 0.f };
    // Frostbite LinearTransform: three basis vectors followed by the origin.
    // Soldier presentation actors are rotated as well as translated; keeping
    // only the origin compressed the shipped four-class lineup and discarded
    // each actor's authored facing.
    float presentation_transform[12] = {
        1.f, 0.f, 0.f, 0.f, 1.f, 0.f, 0.f, 0.f, 1.f, 0.f, 0.f, 0.f };
    float presentation_ground_offset = 0.f;
    XMFLOAT3 lo{}, hi{};
    std::string name;
    long long verts = 0, tris = 0;
    void release()
    {
        for (GpuSection& s : sections)
        {
            if (s.vb) s.vb->Release();
            if (s.ib) s.ib->Release();
            // SRVs are owned by g_texCache, never by the section.
            for (ID3D11ShaderResourceView*& v : s.srv) v = nullptr;
        }
        sections.clear();
        animation_skin_frames.clear();
        animation_frame_count = animation_bone_count = 0;
        animation_rig_bone_count = 0;
        animation_fps = 0.f;
        animation_rigid = false;
        animation_post_transform_active = false;
        presentation_ground_offset = 0.f;
        verts = tris = 0;
    }
};

// ----------------------------------------------------------------- shaders
//
// The armory uses its own authored studio prefab and fixed-exposure
// VisualEnvironment. Both are read from the running install at startup and
// copied into this cbuffer; there are no viewer-authored light directions.
static const char* kHlsl = R"(
#define MAX_ARMORY_LIGHTS 32
cbuffer CB : register(b0)
{
    float4x4 mvp;
    float4x4 model;
    float4x4 normalModel;
    float4   camPos;
    float4   opts;      // x = has normal map, y = has _wo, z = uv set, w = unlit
    float4   baseColor;
    float4   material;  // x = roughness, y = metallic, z = normal is NSM, w = has albedo
    float4   emissiveColor;
    float4   renderFlags; // alpha test, coverage from albedo, has mask, translucent
    float4   shaderFlags; // x = eye material inputs, y = model determinant sign
    float4   scene;     // x = light count, y = fixed EV, z = exposure compensation
    float4   gradeBrightness;
    float4   gradeContrast;
    float4   gradeSaturation;
    float4   giSkyBounce;       // rgb = SkyBoxSkyColor, a = BounceScale
    float4   giGround;          // rgb = SkyBoxGroundColor
    float4   postCamera;         // near, far, focus distance (m), aperture
    float4   postLens;           // focal length (m), sensor height (m), width, height
    float4   lightPosType[MAX_ARMORY_LIGHTS];
    float4   lightDirOuter[MAX_ARMORY_LIGHTS];
    float4   lightColorFlux[MAX_ARMORY_LIGHTS];
    float4   lightParams[MAX_ARMORY_LIGHTS]; // innerCos, range, offset, contribution flags
    float4   lightExtra[MAX_ARMORY_LIGHTS];  // BaseLightInfo additive distance term, reserved
};

struct VSIn  { float3 p : POSITION; float3 n : NORMAL; float4 tangent : TANGENT;
               float2 t : TEXCOORD0; float2 t1 : TEXCOORD1; };
struct VSOut { float4 pos : SV_POSITION; float3 wn : NORMAL; float2 uv : TEXCOORD0;
               float2 uv1 : TEXCOORD1; float3 wp : TEXCOORD2; float4 wt : TANGENT; };

VSOut VS(VSIn i)
{
    VSOut o;
    o.pos = mul(float4(i.p, 1.0), mvp);
    // Placement transforms are not guaranteed rigid. Normals use the inverse
    // transpose while tangents follow the model's linear transform and are
    // orthogonalized in PS. Mirrored placements reverse tangent handedness.
    o.wn  = normalize(mul(float4(i.n, 0.0), normalModel).xyz);
    o.wt  = float4(normalize(mul(float4(i.tangent.xyz, 0.0), model).xyz),
                   i.tangent.w * shaderFlags.y);
    o.uv  = i.t;
    o.uv1 = i.t1;
    o.wp  = mul(float4(i.p, 1.0), model).xyz;
    return o;
}

Texture2D    texAlbedo : register(t0);
Texture2D    texNormal : register(t1);
Texture2D    texWo     : register(t2);
Texture2D    texMask   : register(t3);
Texture2D    texEyeIrisColor   : register(t4);
Texture2D    texEyeScleraColor : register(t5);
Texture2D    texEyeIrisNormal  : register(t6);
Texture2D    texEyeScleraNormal: register(t7);
Texture2D    texEyeMask        : register(t8);
TextureCube  texReflection     : register(t9);
SamplerState samp      : register(s0);

float4 PS(VSOut i) : SV_TARGET
{
    float2 uv = opts.z > 0.5 ? i.uv1 : i.uv;
    // A null SRV samples (0,0,0,0) in D3D11. That made exact constant-only
    // materials (and the optic lens sections whose shader has no colour sheet)
    // render black. Only sample when the decoded material actually binds a
    // colour texture; otherwise preserve its material constant.
    float4 colourTexel = material.w > 0.5
        ? texAlbedo.Sample(samp, uv) : float4(1.0, 1.0, 1.0, 1.0);
    if (shaderFlags.x > 0.5)
    {
        // Installed eye ShaderBlockDepot layout, identified by authoritative
        // name32 fields rather than the mesh name: t_eye_a supplies the iris
        // coverage joining the separately-authored sclera and iris sheets.
        // t_eye_a is centred at 0.5 outside the iris and falls toward zero
        // over the iris disc (live sheet: 84.5% of texels quantise to 128,
        // centre=1/255).  It is a signed-distance-style coverage input, not a
        // conventional white-on-black mask.
        float irisCoverage = saturate(1.0 - 2.0 * texEyeMask.Sample(samp, uv).r);
        float4 sclera = texEyeScleraColor.Sample(samp, uv);
        float4 iris = texEyeIrisColor.Sample(samp, uv);
        colourTexel = lerp(sclera, iris, irisCoverage);
    }
    float4 alb = colourTexel * baseColor;
    if (renderFlags.x > 0.5)
    {
        // The material record distinguishes vegetation coverage in the base
        // colour from ordinary cutout coverage in its dedicated `_a` sheet.
        // The installed masks are binary-shaped; half coverage is the neutral
        // sample boundary when no shader-specific threshold is exposed.
        float coverage = renderFlags.y > 0.5
            ? colourTexel.a
            : (renderFlags.z > 0.5 ? texMask.Sample(samp, uv).r : 1.0);
        clip(coverage - 0.5);
    }
    float3 N = normalize(i.wn);
    if (opts.x > 0.5)
    {
        // BC5-style two-channel tangent normal: Z is reconstructed, never
        // stored. Reading .b here would sample whatever the codec left there.
        float2 nxy = texNormal.Sample(samp, uv).rg * 2.0 - 1.0;
        float  nz  = sqrt(saturate(1.0 - dot(nxy, nxy)));
        float3 T = normalize(i.wt.xyz - N * dot(N, i.wt.xyz));
        float3 B = normalize(cross(N, T)) * i.wt.w;
        N = normalize(T * nxy.x + B * nxy.y + N * nz);
    }
    if (shaderFlags.x > 0.5)
    {
        float irisCoverage = saturate(1.0 - 2.0 * texEyeMask.Sample(samp, uv).r);
        float2 scleraXY = texEyeScleraNormal.Sample(samp, uv).rg * 2.0 - 1.0;
        float2 irisXY = texEyeIrisNormal.Sample(samp, uv).rg * 2.0 - 1.0;
        float2 nxy = lerp(scleraXY, irisXY, irisCoverage);
        float nz = sqrt(saturate(1.0 - dot(nxy, nxy)));
        float3 baseN = normalize(i.wn);
        float3 T = normalize(i.wt.xyz - baseN * dot(baseN, i.wt.xyz));
        float3 B = normalize(cross(baseN, T)) * i.wt.w;
        N = normalize(T * nxy.x + B * nxy.y + baseN * nz);
    }

    // BF6 `_cs` is colour + SMOOTHNESS.  `_wo` is a separate wear/paint mask,
    // not M/R/O; treating it as MRO suppresses nearly all light on the gun.
    // Keep the raw `_wo` binding resident for the decoded hardware composite,
    // but do not invent meanings for its still-unidentified G/B channels.
    // `_cs`.a is smoothness only when `_cs` exists. Constant-only materials
    // use their authored roughness constant instead of interpreting the
    // fallback alpha=1 as a perfect mirror.
    float rough = material.w > 0.5
        ? 1.0 - saturate(alb.a) : saturate(material.x);
    float ao = 1.0, metal = saturate(material.y);
    if (material.z > 0.5 && opts.x > 0.5)
        rough = 1.0 - texNormal.Sample(samp, uv).a;

    if (opts.w > 0.5) return float4(alb.rgb, 1.0);

    float3 V = normalize(camPos.xyz - i.wp);
    float NoV = max(dot(N, V), 1e-4);
    float3 F0 = lerp(float3(0.04, 0.04, 0.04), alb.rgb, metal);
    float3 lit = 0.0;
    const float pi = 3.14159265359;
    [loop] for (int k = 0; k < min((int)scene.x, MAX_ARMORY_LIGHTS); k++)
    {
        float3 toLight = lightPosType[k].xyz - i.wp;
        float dist2 = dot(toLight, toLight);
        float dist = max(sqrt(dist2), 1e-3);
        float3 L = toLight / dist;
        float range = max(lightParams[k].y, 1e-3);
        // Recovered from the shipped deferred composite's BaseLightInfo path:
        //   invDistance = 1 / max(1e-4, distanceSquared + BaseLightInfo[28])
        //   edge = saturate(1 - (distanceSquared / radiusSquared)^2)^2
        // The shipped shader consumes the additive record value directly. No
        // evidence supports squaring the EBX field during upload, so preserve
        // that authored value instead of introducing an unverified transform.
        float radius2 = range * range;
        float radial = saturate(1.0 - pow(dist2 / radius2, 2.0));
        float attenuation = radial * radial /
                            max(dist2 + lightExtra[k].x, 1e-4);
        if (lightPosType[k].w > 0.5)
        {
            float cone = dot(lightDirOuter[k].xyz, -L);
            // BaseLightInfo carries the affine inner/outer cosine remap and
            // the shader squares its saturated result; it is not smoothstep.
            float coneRamp = saturate((cone - lightDirOuter[k].w) /
                                      max(lightParams[k].x - lightDirOuter[k].w, 1e-5));
            attenuation *= coneRamp * coneRamp;
        }
        // LightRenderDB::convertToLightInfo in this build: punctual sphere and
        // spot use P/(4*pi); a disc spot stores the emitted radiance
        // P/(pi^2*r^2). The previous P/pi shortcut discarded r and made the
        // armory's 1.0--1.5 m softboxes 3--7x too bright. The runtime-only spot
        // normalisation flag is not authored in EBX, so the documented clear
        // branch is retained for punctual spots rather than guessed per cone.
        const float discRadius = lightParams[k].z;
        float rendererEnergy = lightColorFlux[k].w / (4.0 * pi);
        if (lightPosType[k].w > 0.5 && discRadius > 0.0)
            rendererEnergy = lightColorFlux[k].w /
                             (pi * pi * discRadius * discRadius);
        float3 radiance = lightColorFlux[k].rgb * rendererEnergy * attenuation;

        float3 H = normalize(L + V);
        float NoL = saturate(dot(N, L));
        float NoH = saturate(dot(N, H));
        float VoH = saturate(dot(V, H));
        float a = max(rough * rough, 0.02);
        float a2 = a * a;
        float d = NoH * NoH * (a2 - 1.0) + 1.0;
        float D = a2 / max(pi * d * d, 1e-5);
        float gv = NoL * sqrt(max(NoV * NoV * (1.0 - a2) + a2, 1e-5));
        float gl = NoV * sqrt(max(NoL * NoL * (1.0 - a2) + a2, 1e-5));
        float Vis = 0.5 / max(gv + gl, 1e-5);
        float3 F = F0 + (1.0 - F0) * pow(1.0 - VoH, 5.0);
        float flags = lightParams[k].w;
        float diffuseOn = fmod(flags, 2.0) >= 0.5 ? 1.0 : 0.0;
        float specularOn = fmod(floor(flags / 2.0), 2.0) >= 0.5 ? 1.0 : 0.0;
        float3 diffuse = alb.rgb * (1.0 - metal) / pi;
        lit += (diffuse * diffuseOn + D * Vis * F * specularOn) * radiance * NoL;
    }
    // The customization VE is an override, not a complete environment.  The
    // base hangar's GI component remains active underneath it. Frostbite's
    // authored sky/ground hemispheres provide diffuse irradiance while the
    // authored light prefab supplies the direct and specular studio lighting.
    // AO's authored AffectLocalLight is true, so it belongs on that direct
    // term; the base GI term is added afterwards.
    lit *= ao;
    float hemi = saturate(N.y * 0.5 + 0.5);
    float3 giIrradiance = lerp(giGround.rgb, giSkyBounce.rgb, hemi);
    lit += alb.rgb * (1.0 - metal) * giIrradiance * giSkyBounce.a / pi;
    if (shaderFlags.z > 0.5)
    {
        // content_hangar_reflectionvolumes is authored as an ordinary D3D
        // six-face RGBA16F cube. The resource stores mip 0; upload builds the
        // ordinary box-filter mip pyramid so diffuse does not reproduce sharp
        // scene detail and rough materials do not sample an unfiltered probe.
        // Frostbite's recovered GGX/cosine compute convolution remains the
        // final replacement once its native sample schedule is identified.
        const float reflectionMaxLod = 8.0;
        float3 envDiffuse =
            texReflection.SampleLevel(samp, N, reflectionMaxLod).rgb;
        float3 R = reflect(-V, N);
        float3 envSpecular = texReflection.SampleLevel(
            samp, R, rough * reflectionMaxLod).rgb;
        float3 envFresnel = F0 + (1.0 - F0) * pow(1.0 - NoV, 5.0);
        lit += alb.rgb * (1.0 - metal) * envDiffuse *
               giSkyBounce.a / (4.0 * pi);
        // The native split-sum integration scale is not serialized with the
        // cube. Keep the compatibility path bounded rather than allowing raw
        // mip-0 HDR radiance to bleach the presentation materials.
        lit += envSpecular * envFresnel *
               saturate(1.0 - rough * rough) * 0.05;
    }
    lit += emissiveColor.rgb;
    // Keep the scene in linear HDR. Exposure, grading and the display
    // transform are full-frame operations in Frostbite; applying them here
    // made the clear/background bypass the transform and transformed every
    // material before the scene was composited.
    // Hardware glass is classified from its authored destruction-volume or
    // tint-palette binding.  BF6 sends that family through a deferred glass
    // path rather than exposing a scalar opacity.  The D3D11 viewer preserves
    // the material identity and uses the dielectric Fresnel term as its
    // compatibility coverage: nearly transmissive face-on, reflective at a
    // grazing angle.  This deliberately does not reinterpret `_cs`.a
    // (smoothness) or any unrelated material constant as opacity.
    float3 viewFresnel = F0 + (1.0 - F0) * pow(1.0 - NoV, 5.0);
    float outputAlpha = renderFlags.w > 0.5
        ? max(max(viewFresnel.r, viewFresnel.g), viewFresnel.b) : 1.0;
    return float4(lit, saturate(outputAlpha));
}

struct PostOut { float4 pos : SV_POSITION; float2 uv : TEXCOORD0; };
PostOut PostVS(uint vertexId : SV_VertexID)
{
    PostOut o;
    o.uv = float2((vertexId << 1) & 2, vertexId & 2);
    o.pos = float4(o.uv * float2(2.0, -2.0) + float2(-1.0, 1.0), 0.0, 1.0);
    return o;
}

Texture2D sceneHdr : register(t4);
Texture2D sceneDepth : register(t5);
Texture3D gradingLut : register(t6);
float4 PostPS(PostOut i) : SV_TARGET
{
    // BF6 writes HangarEnableLensDOF=true for every armory camera. Its 35 mm
    // physical lens, per-mode f-number and autofocus target are all authored.
    // Compute the physical circle of confusion from those records. The game
    // uses the CircularDof family; this bounded disc gather is its D3D11
    // compatibility path and, critically, rejects nearer samples while
    // blurring a far pixel so the focused weapon cannot bleed into the hangar.
    const float nearZ = postCamera.x;
    const float farZ = postCamera.y;
    const float depth = sceneDepth.SampleLevel(samp, i.uv, 0).r;
    const float viewZ = nearZ * farZ / max(farZ - depth * (farZ - nearZ), 1e-6);
    const float focal = postLens.x;
    const float sensorH = postLens.y;
    const float focusZ = max(postCamera.z, focal + 1e-4);
    const float fNumber = max(postCamera.w, 0.05);
    const float cocSensor = abs((focal * focal * (viewZ - focusZ)) /
                                max(fNumber * viewZ * (focusZ - focal), 1e-6));
    const float cocPx = min(cocSensor * postLens.w / (2.0 * sensorH), 32.0);

    float3 lit = sceneHdr.SampleLevel(samp, i.uv, 0).rgb;
    // The front-end keeps the inspected weapon legible and applies the heavy
    // circular gather behind its autofocus plane.  Blurring the near side of
    // the weapon with the same full-radius gather produced the repeated,
    // smeared optic seen in the regression control.  Preserve near geometry;
    // the authored far hangar still receives the physical CoC.
    // scene.w: 0 armory, 1 presentation with an installed physical lens,
    // 2 presentation without one. Only the latter must bypass the gather.
    if (scene.w < 1.5 && cocPx > 0.35 && viewZ > focusZ)
    {
        float3 sum = lit;
        float weight = 1.0;
        const float2 invSize = 1.0 / postLens.zw;
        [unroll] for (int tap = 0; tap < 24; ++tap)
        {
            const float unitRadius = sqrt((tap + 0.5) / 24.0);
            const float angle = (tap + 0.5) * 2.39996323;
            const float2 suv = i.uv + float2(cos(angle), sin(angle)) *
                                      (unitRadius * cocPx) * invSize;
            const float sampleDepth = sceneDepth.SampleLevel(samp, suv, 0).r;
            const float sampleZ = nearZ * farZ /
                max(farZ - sampleDepth * (farZ - nearZ), 1e-6);
            // For a far/background centre, exclude a substantially nearer
            // contributor. This is the foreground-coverage rule the removed
            // mip approximation lacked and keeps the M4 silhouette intact.
            const float accept = sampleZ + max(0.01, viewZ * 0.01) >= viewZ ? 1.0 : 0.0;
            sum += sceneHdr.SampleLevel(samp, suv, 0).rgb * accept;
            weight += accept;
        }
        lit = sum / max(weight, 1.0);
    }
    // Diagnostic control: PS already returned the raw base-colour sheet when
    // opts.w is set.  Applying the scene's EV=12.5 afterwards made that control
    // black and therefore unable to distinguish a bright texture from an
    // over-bright lighting model.  Display the sampled sRGB texture value
    // directly for --screenshot-unlit.
    if (opts.w > 0.5)
        return float4(pow(saturate(lit), 1.0 / 2.2), 1.0);
    // The customization preset explicitly authors AutomaticExposure=false,
    // EV=12.5. ExposureCompensation is a stop offset and therefore belongs in
    // the exponent. This is evaluated once after the complete HDR scene.
    lit *= exp2(-scene.y + scene.z) / 1.2;
    lit *= gradeBrightness.rgb;
    lit = (lit - 0.18) * gradeContrast.rgb + 0.18;
    float luma = dot(lit, float3(0.2126, 0.7152, 0.0722));
    lit = luma.xxx + (lit - luma.xxx) * gradeSaturation.rgb;
    // ACES fitted display transform followed by the exact 33^3 grading volume
    // selected by the active VisualEnvironment. The LUT is stored as native
    // RGB10A2 texels and sampled as a true Texture3D, not flattened into a
    // strip or approximated with hand-authored colour multipliers.
    lit = saturate((lit * (2.51 * lit + 0.03)) /
                   (lit * (2.43 * lit + 0.59) + 0.14));
    if (gradeBrightness.w > 0.5)
        lit = gradingLut.SampleLevel(samp, saturate(lit), 0).rgb;
    return float4(pow(lit, 1.0 / 2.2), 1.0);
}
)";

static ID3D11VertexShader* g_vs = nullptr;
static ID3D11PixelShader*  g_ps = nullptr;
static ID3D11VertexShader* g_postVs = nullptr;
static ID3D11PixelShader*  g_postPs = nullptr;
static ID3D11InputLayout*  g_il = nullptr;
static ID3D11Buffer*       g_cb = nullptr;
static ID3D11SamplerState* g_samp = nullptr;
static ID3D11SamplerState* g_postSamp = nullptr;
static ID3D11SamplerState* g_rimeImageSamplers[6][6]{};
static ID3D11RasterizerState*   g_rs = nullptr;
static ID3D11RasterizerState*   g_rsHangar = nullptr;
static ID3D11RasterizerState*   g_rsHangarMirrored = nullptr;
static ID3D11ShaderResourceView* g_hangarReflectionSrv = nullptr;
static ID3D11ShaderResourceView* g_gradingLutSrv = nullptr;
static ID3D11DepthStencilState* g_ds = nullptr;
static ID3D11DepthStencilState* g_dsReadOnly = nullptr;
static ID3D11BlendState*        g_blendAlpha = nullptr;

static void SetRimeImageSampler(const ImDrawList*, const ImDrawCmd* command)
{
    if (!g_ctx || !command || !command->UserCallbackData) return;
    ID3D11SamplerState* sampler = static_cast<ID3D11SamplerState*>(
        command->UserCallbackData);
    g_ctx->PSSetSamplers(0, 1, &sampler);
}

static bool RimeAddressMode(int value, D3D11_TEXTURE_ADDRESS_MODE& mode)
{
    switch (value)
    {
    case 0: mode = D3D11_TEXTURE_ADDRESS_WRAP; return true;
    case 1: mode = D3D11_TEXTURE_ADDRESS_MIRROR; return true;
    case 2: mode = D3D11_TEXTURE_ADDRESS_CLAMP; return true;
    case 4: mode = D3D11_TEXTURE_ADDRESS_BORDER; return true;
    case 5: mode = D3D11_TEXTURE_ADDRESS_MIRROR_ONCE; return true;
    default: return false;
    }
}

static ID3D11SamplerState* RimeImageSampler(int addressU, int addressV)
{
    if (addressU < 0 || addressU >= 6 || addressV < 0 || addressV >= 6)
        return nullptr;
    return g_rimeImageSamplers[addressU][addressV];
}

struct CB {
    XMFLOAT4X4 mvp, model, normalModel;
    XMFLOAT4   camPos, opts, baseColor, material, emissiveColor, renderFlags, shaderFlags, scene;
    XMFLOAT4   gradeBrightness, gradeContrast, gradeSaturation;
    XMFLOAT4   giSkyBounce, giGround;
    XMFLOAT4   postCamera, postLens;
    XMFLOAT4   lightPosType[32], lightDirOuter[32], lightColorFlux[32], lightParams[32];
    XMFLOAT4   lightExtra[32];
};

// --------------------------------------------------------------- d3d setup
static void CreateRT()
{
    ID3D11Texture2D* bb = nullptr;
    g_swap->GetBuffer(0, IID_PPV_ARGS(&bb));
    if (!bb) return;
    g_backBuffer = bb;
    g_dev->CreateRenderTargetView(bb, nullptr, &g_rtv);
    D3D11_TEXTURE2D_DESC bd{};
    bb->GetDesc(&bd);

    D3D11_TEXTURE2D_DESC backdrop = bd;
    backdrop.MipLevels = 0;
    backdrop.ArraySize = 1;
    backdrop.SampleDesc.Count = 1;
    backdrop.SampleDesc.Quality = 0;
    backdrop.Usage = D3D11_USAGE_DEFAULT;
    backdrop.BindFlags = D3D11_BIND_RENDER_TARGET |
                         D3D11_BIND_SHADER_RESOURCE;
    backdrop.CPUAccessFlags = 0;
    backdrop.MiscFlags = D3D11_RESOURCE_MISC_GENERATE_MIPS;
    if (SUCCEEDED(g_dev->CreateTexture2D(
            &backdrop, nullptr, &g_uiBackdropTexture)) &&
        g_uiBackdropTexture)
    {
        g_dev->CreateShaderResourceView(g_uiBackdropTexture, nullptr,
                                        &g_uiBackdropSrv);
        // The exact Frostbite sampling kernel is still an explicit research
        // boundary.  A restricted generated-mip view is the fail-visible
        // D3D11 compatibility path: it consumes the live framebuffer and the
        // authored RimeBlur box, while avoiding the old (and much worse)
        // behavior of silently dropping the card surface altogether.
        D3D11_SHADER_RESOURCE_VIEW_DESC blurView{};
        blurView.Format = backdrop.Format;
        blurView.ViewDimension = D3D11_SRV_DIMENSION_TEXTURE2D;
        blurView.Texture2D.MostDetailedMip = 4;
        blurView.Texture2D.MipLevels = 1;
        g_dev->CreateShaderResourceView(g_uiBackdropTexture, &blurView,
                                        &g_uiBackdropBlurSrv);
    }

    D3D11_TEXTURE2D_DESC sd{};
    sd.Width = bd.Width; sd.Height = bd.Height;
    sd.MipLevels = 0; sd.ArraySize = 1;
    sd.Format = DXGI_FORMAT_R16G16B16A16_FLOAT;
    sd.SampleDesc.Count = 1;
    sd.Usage = D3D11_USAGE_DEFAULT;
    sd.BindFlags = D3D11_BIND_RENDER_TARGET | D3D11_BIND_SHADER_RESOURCE;
    sd.MiscFlags = D3D11_RESOURCE_MISC_GENERATE_MIPS;
    if (SUCCEEDED(g_dev->CreateTexture2D(&sd, nullptr, &g_sceneTexture)) && g_sceneTexture)
    {
        g_dev->CreateRenderTargetView(g_sceneTexture, nullptr, &g_sceneRtv);
        g_dev->CreateShaderResourceView(g_sceneTexture, nullptr, &g_sceneSrv);
    }

    D3D11_TEXTURE2D_DESC dd{};
    dd.Width = bd.Width; dd.Height = bd.Height;
    dd.MipLevels = 1; dd.ArraySize = 1;
    dd.Format = DXGI_FORMAT_R32_TYPELESS;
    dd.SampleDesc.Count = 1;
    dd.Usage = D3D11_USAGE_DEFAULT;
    dd.BindFlags = D3D11_BIND_DEPTH_STENCIL | D3D11_BIND_SHADER_RESOURCE;
    g_dev->CreateTexture2D(&dd, nullptr, &g_depth);
    if (g_depth)
    {
        D3D11_DEPTH_STENCIL_VIEW_DESC dsvd{};
        dsvd.Format = DXGI_FORMAT_D32_FLOAT;
        dsvd.ViewDimension = D3D11_DSV_DIMENSION_TEXTURE2D;
        g_dev->CreateDepthStencilView(g_depth, &dsvd, &g_dsv);
        D3D11_SHADER_RESOURCE_VIEW_DESC dsrv{};
        dsrv.Format = DXGI_FORMAT_R32_FLOAT;
        dsrv.ViewDimension = D3D11_SRV_DIMENSION_TEXTURE2D;
        dsrv.Texture2D.MipLevels = 1;
        g_dev->CreateShaderResourceView(g_depth, &dsrv, &g_depthSrv);
    }
}

static void ReleaseRT()
{
    if (g_uiBackdropBlurSrv) {
        g_uiBackdropBlurSrv->Release(); g_uiBackdropBlurSrv = nullptr;
    }
    if (g_uiBackdropSrv) {
        g_uiBackdropSrv->Release(); g_uiBackdropSrv = nullptr;
    }
    if (g_uiBackdropTexture) {
        g_uiBackdropTexture->Release(); g_uiBackdropTexture = nullptr;
    }
    if (g_sceneSrv) { g_sceneSrv->Release(); g_sceneSrv = nullptr; }
    if (g_sceneRtv) { g_sceneRtv->Release(); g_sceneRtv = nullptr; }
    if (g_sceneTexture) { g_sceneTexture->Release(); g_sceneTexture = nullptr; }
    if (g_depthSrv) { g_depthSrv->Release(); g_depthSrv = nullptr; }
    if (g_rtv)   { g_rtv->Release();   g_rtv = nullptr; }
    if (g_dsv)   { g_dsv->Release();   g_dsv = nullptr; }
    if (g_depth) { g_depth->Release(); g_depth = nullptr; }
    if (g_backBuffer) { g_backBuffer->Release(); g_backBuffer = nullptr; }
}

static bool InitD3D(HWND hwnd)
{
    DXGI_SWAP_CHAIN_DESC sd{};
    sd.BufferCount = 2;
    sd.BufferDesc.Format = DXGI_FORMAT_R8G8B8A8_UNORM;
    sd.BufferDesc.RefreshRate.Numerator = 60;
    sd.BufferDesc.RefreshRate.Denominator = 1;
    sd.BufferUsage = DXGI_USAGE_RENDER_TARGET_OUTPUT;
    sd.OutputWindow = hwnd;
    sd.SampleDesc.Count = 1;
    sd.Windowed = TRUE;
    sd.SwapEffect = DXGI_SWAP_EFFECT_FLIP_DISCARD;

    const D3D_FEATURE_LEVEL want[] = { D3D_FEATURE_LEVEL_11_0 };
    D3D_FEATURE_LEVEL got{};
    if (FAILED(D3D11CreateDeviceAndSwapChain(
            nullptr, D3D_DRIVER_TYPE_HARDWARE, nullptr, 0, want, 1,
            D3D11_SDK_VERSION, &sd, &g_swap, &g_dev, &got, &g_ctx)))
        return false;
    CreateRT();

    ID3DBlob* vsb = nullptr; ID3DBlob* psb = nullptr;
    ID3DBlob* postVsb = nullptr; ID3DBlob* postPsb = nullptr; ID3DBlob* err = nullptr;
    if (FAILED(D3DCompile(kHlsl, strlen(kHlsl), nullptr, nullptr, nullptr, "VS", "vs_5_0", 0, 0, &vsb, &err)))
    {
        MessageBoxA(hwnd, err ? (char*)err->GetBufferPointer() : "VS failed", "shader", MB_OK);
        return false;
    }
    if (FAILED(D3DCompile(kHlsl, strlen(kHlsl), nullptr, nullptr, nullptr, "PS", "ps_5_0", 0, 0, &psb, &err)))
    {
        MessageBoxA(hwnd, err ? (char*)err->GetBufferPointer() : "PS failed", "shader", MB_OK);
        return false;
    }
    if (FAILED(D3DCompile(kHlsl, strlen(kHlsl), nullptr, nullptr, nullptr, "PostVS", "vs_5_0", 0, 0, &postVsb, &err)) ||
        FAILED(D3DCompile(kHlsl, strlen(kHlsl), nullptr, nullptr, nullptr, "PostPS", "ps_5_0", 0, 0, &postPsb, &err)))
    {
        MessageBoxA(hwnd, err ? (char*)err->GetBufferPointer() : "post shader failed", "shader", MB_OK);
        return false;
    }
    g_dev->CreateVertexShader(vsb->GetBufferPointer(), vsb->GetBufferSize(), nullptr, &g_vs);
    g_dev->CreatePixelShader(psb->GetBufferPointer(), psb->GetBufferSize(), nullptr, &g_ps);
    g_dev->CreateVertexShader(postVsb->GetBufferPointer(), postVsb->GetBufferSize(), nullptr, &g_postVs);
    g_dev->CreatePixelShader(postPsb->GetBufferPointer(), postPsb->GetBufferSize(), nullptr, &g_postPs);
    const D3D11_INPUT_ELEMENT_DESC il[] = {
        { "POSITION", 0, DXGI_FORMAT_R32G32B32_FLOAT, 0, 0,  D3D11_INPUT_PER_VERTEX_DATA, 0 },
        { "NORMAL",   0, DXGI_FORMAT_R32G32B32_FLOAT, 0, 12, D3D11_INPUT_PER_VERTEX_DATA, 0 },
        { "TANGENT",  0, DXGI_FORMAT_R32G32B32A32_FLOAT, 0, 24, D3D11_INPUT_PER_VERTEX_DATA, 0 },
        { "TEXCOORD", 0, DXGI_FORMAT_R32G32_FLOAT,    0, 40, D3D11_INPUT_PER_VERTEX_DATA, 0 },
        { "TEXCOORD", 1, DXGI_FORMAT_R32G32_FLOAT,    0, 48, D3D11_INPUT_PER_VERTEX_DATA, 0 },
    };
    g_dev->CreateInputLayout(il, 5, vsb->GetBufferPointer(), vsb->GetBufferSize(), &g_il);
    vsb->Release(); psb->Release(); postVsb->Release(); postPsb->Release();

    D3D11_BUFFER_DESC cbd{};
    cbd.ByteWidth = sizeof(CB);
    cbd.Usage = D3D11_USAGE_DYNAMIC;
    cbd.BindFlags = D3D11_BIND_CONSTANT_BUFFER;
    cbd.CPUAccessFlags = D3D11_CPU_ACCESS_WRITE;
    g_dev->CreateBuffer(&cbd, nullptr, &g_cb);

    D3D11_SAMPLER_DESC sm{};
    sm.Filter = D3D11_FILTER_ANISOTROPIC;
    sm.MaxAnisotropy = 8;
    sm.AddressU = sm.AddressV = sm.AddressW = D3D11_TEXTURE_ADDRESS_WRAP;
    sm.MaxLOD = D3D11_FLOAT32_MAX;
    g_dev->CreateSamplerState(&sm, &g_samp);

    D3D11_SAMPLER_DESC postSm{};
    postSm.Filter = D3D11_FILTER_MIN_MAG_MIP_LINEAR;
    postSm.AddressU = postSm.AddressV = postSm.AddressW = D3D11_TEXTURE_ADDRESS_CLAMP;
    postSm.MaxLOD = D3D11_FLOAT32_MAX;
    g_dev->CreateSamplerState(&postSm, &g_postSamp);

    // Rime stores addressing independently for each image axis. Keep the
    // decoded enum numeric values as the lookup keys (3 is deliberately not a
    // member) so Wrap/Mirror/Clamp/Border/MirrorOnce are not flattened to the
    // ImGui backend's clamp sampler. BorderColor is not serialized on the
    // observed image elements; D3D's transparent-black default is retained.
    const int rimeAddressValues[] = {0, 1, 2, 4, 5};
    for (const int u : rimeAddressValues)
    for (const int v : rimeAddressValues)
    {
        D3D11_TEXTURE_ADDRESS_MODE addressU{}, addressV{};
        if (!RimeAddressMode(u, addressU) || !RimeAddressMode(v, addressV))
            continue;
        D3D11_SAMPLER_DESC imageSm{};
        imageSm.Filter = D3D11_FILTER_MIN_MAG_MIP_LINEAR;
        imageSm.AddressU = addressU;
        imageSm.AddressV = addressV;
        imageSm.AddressW = D3D11_TEXTURE_ADDRESS_CLAMP;
        imageSm.MaxLOD = D3D11_FLOAT32_MAX;
        g_dev->CreateSamplerState(&imageSm, &g_rimeImageSamplers[u][v]);
    }

    D3D11_RASTERIZER_DESC rd{};
    rd.FillMode = D3D11_FILL_SOLID;
    rd.CullMode = D3D11_CULL_NONE;      // weapon parts are authored both ways
    rd.DepthClipEnable = TRUE;
    g_dev->CreateRasterizerState(&rd, &g_rs);

    // The environment shell is ordinary outward-facing static geometry.  It
    // must not inherit the weapon's deliberately two-sided raster state: doing
    // so exposes the back of partition walls that Frostbite culls and can put
    // a solid wall between the authored camera and the weapon studio.
    rd.CullMode = D3D11_CULL_BACK;
    // Frostbite's mesh conversion reverses projected winding relative to the
    // D3D default used by the old viewer state.  The previous state therefore
    // retained the outside/back faces of the hangar shell and discarded the
    // authored interior faces (most visibly the locker wall).  Use the
    // converted front-face convention for ordinary placements and invert it
    // only for negative-determinant instances below.
    rd.FrontCounterClockwise = TRUE;
    g_dev->CreateRasterizerState(&rd, &g_rsHangar);
    // A small number of authored placements carry a negative determinant.
    // Their projected winding is reversed, so preserve Frostbite's front-face
    // choice by reversing the rasterizer convention for those instances only.
    rd.FrontCounterClockwise = FALSE;
    g_dev->CreateRasterizerState(&rd, &g_rsHangarMirrored);

    D3D11_DEPTH_STENCIL_DESC dsd{};
    dsd.DepthEnable = TRUE;
    dsd.DepthWriteMask = D3D11_DEPTH_WRITE_MASK_ALL;
    dsd.DepthFunc = D3D11_COMPARISON_LESS;
    g_dev->CreateDepthStencilState(&dsd, &g_ds);

    // Glass is drawn only after the opaque actor. It tests against the depth
    // established by armor/interior geometry but must not occlude a later
    // glass face by writing its own depth.
    dsd.DepthWriteMask = D3D11_DEPTH_WRITE_MASK_ZERO;
    g_dev->CreateDepthStencilState(&dsd, &g_dsReadOnly);

    D3D11_BLEND_DESC blend{};
    D3D11_RENDER_TARGET_BLEND_DESC& target = blend.RenderTarget[0];
    target.BlendEnable = TRUE;
    target.SrcBlend = D3D11_BLEND_SRC_ALPHA;
    target.DestBlend = D3D11_BLEND_INV_SRC_ALPHA;
    target.BlendOp = D3D11_BLEND_OP_ADD;
    target.SrcBlendAlpha = D3D11_BLEND_ONE;
    target.DestBlendAlpha = D3D11_BLEND_INV_SRC_ALPHA;
    target.BlendOpAlpha = D3D11_BLEND_OP_ADD;
    target.RenderTargetWriteMask = D3D11_COLOR_WRITE_ENABLE_ALL;
    g_dev->CreateBlendState(&blend, &g_blendAlpha);
    return true;
}

// ------------------------------------------------------------- bf6 -> gpu
//
// The whole argument for a native tool is in this function: the bytes libbf6
// returns are already a GPU resource. No transcode, no intermediate file.
static DXGI_FORMAT ToDxgi(bf6_fmt f, int srgb)
{
    switch (f)
    {
    case BF6_FMT_RGBA8:   return srgb ? DXGI_FORMAT_R8G8B8A8_UNORM_SRGB : DXGI_FORMAT_R8G8B8A8_UNORM;
    case BF6_FMT_BC1:     return srgb ? DXGI_FORMAT_BC1_UNORM_SRGB : DXGI_FORMAT_BC1_UNORM;
    case BF6_FMT_BC3:     return srgb ? DXGI_FORMAT_BC3_UNORM_SRGB : DXGI_FORMAT_BC3_UNORM;
    case BF6_FMT_BC4:     return DXGI_FORMAT_BC4_UNORM;
    case BF6_FMT_BC5:     return DXGI_FORMAT_BC5_UNORM;
    case BF6_FMT_BC7:     return srgb ? DXGI_FORMAT_BC7_UNORM_SRGB : DXGI_FORMAT_BC7_UNORM;
    case BF6_FMT_BC6H_U:  return DXGI_FORMAT_BC6H_UF16;
    case BF6_FMT_BC6H_S:  return DXGI_FORMAT_BC6H_SF16;
    case BF6_FMT_R8:      return DXGI_FORMAT_R8_UNORM;
    case BF6_FMT_RGBA16F: return DXGI_FORMAT_R16G16B16A16_FLOAT;
    default:              return DXGI_FORMAT_UNKNOWN;
    }
}

static int BlockBytes(bf6_fmt f)
{
    switch (f)
    {
    case BF6_FMT_BC1: case BF6_FMT_BC4: return 8;
    case BF6_FMT_BC3: case BF6_FMT_BC5: case BF6_FMT_BC7:
    case BF6_FMT_BC6H_U: case BF6_FMT_BC6H_S: return 16;
    default: return 0;                  // uncompressed
    }
}

// ONE UPLOAD PER TEXTURE, NOT PER PART.
//
// A weapon's parts share a texture set: m4a1, p90 and mp7a2 each report the
// same 37.75 MB (4096 albedo + 4096 normal + 2048 mro). Uploading that per
// part turned "assemble a weapon" into a gigabyte of duplicated VRAM and a
// multi-second stall in the middle of a UI callback. Keyed by the texture id
// libbf6 hands out, which is stable for the life of the context.
static std::map<int, ID3D11ShaderResourceView*> g_texCache;
static std::map<int, std::pair<int, int>> g_texSizeCache;

static void ClearTexCache()
{
    for (auto& kv : g_texCache) if (kv.second) kv.second->Release();
    g_texCache.clear();
    g_texSizeCache.clear();
}

static bool TextureDimensions(int textureId, ID3D11ShaderResourceView* view,
                              int& width, int& height)
{
    width = height = 0;
    const auto cached = g_texSizeCache.find(textureId);
    if (cached != g_texSizeCache.end())
    {
        width = cached->second.first;
        height = cached->second.second;
        return width > 0 && height > 0;
    }
    if (!view) return false;
    ID3D11Resource* resource = nullptr;
    view->GetResource(&resource);
    if (!resource) return false;
    ID3D11Texture2D* texture = nullptr;
    const HRESULT queried = resource->QueryInterface(IID_PPV_ARGS(&texture));
    resource->Release();
    if (FAILED(queried) || !texture) return false;
    D3D11_TEXTURE2D_DESC description{};
    texture->GetDesc(&description);
    texture->Release();
    width = static_cast<int>(description.Width);
    height = static_cast<int>(description.Height);
    g_texSizeCache[textureId] = {width, height};
    return width > 0 && height > 0;
}

static ID3D11ShaderResourceView* UploadTextureUncached(const bf6_texture* t)
{
    if (!t || !t->data || t->data_len <= 0) return nullptr;
    const DXGI_FORMAT fmt = ToDxgi(t->format, t->srgb);
    if (fmt == DXGI_FORMAT_UNKNOWN) return nullptr;

    const int bb = BlockBytes(t->format);
    const int mips = t->mip_count > 0 ? t->mip_count : 1;

    // Walk the mip chain: the payload is every mip tightly packed, so each
    // level's row pitch has to be computed rather than assumed.
    std::vector<D3D11_SUBRESOURCE_DATA> sub((size_t)mips);
    const uint8_t* p = t->data;
    int w = t->width, h = t->height;
    int used = 0, real_mips = 0;
    for (int m = 0; m < mips; m++)
    {
        int pitch, bytes;
        if (bb)
        {
            const int bw = (w + 3) / 4, bh = (h + 3) / 4;
            pitch = bw * bb; bytes = pitch * bh;
        }
        else
        {
            const int bpp = (t->format == BF6_FMT_R8) ? 1 : (t->format == BF6_FMT_RGBA16F ? 8 : 4);
            pitch = w * bpp; bytes = pitch * h;
        }
        if (used + bytes > t->data_len) break;     // short payload: stop, do not read past
        sub[(size_t)m].pSysMem = p + used;
        sub[(size_t)m].SysMemPitch = (UINT)pitch;
        used += bytes; real_mips++;
        w = w > 1 ? w / 2 : 1;
        h = h > 1 ? h / 2 : 1;
    }
    if (real_mips == 0) return nullptr;

    D3D11_TEXTURE2D_DESC d{};
    d.Width = (UINT)t->width; d.Height = (UINT)t->height;
    d.MipLevels = (UINT)real_mips; d.ArraySize = 1;
    d.Format = fmt;
    d.SampleDesc.Count = 1;
    d.Usage = D3D11_USAGE_IMMUTABLE;
    d.BindFlags = D3D11_BIND_SHADER_RESOURCE;

    ID3D11Texture2D* tex = nullptr;
    if (FAILED(g_dev->CreateTexture2D(&d, sub.data(), &tex)) || !tex) return nullptr;
    ID3D11ShaderResourceView* srv = nullptr;
    g_dev->CreateShaderResourceView(tex, nullptr, &srv);
    tex->Release();
    return srv;
}

static void ReleaseBootMovieGpu()
{
    if (g_bootMovieSrv) { g_bootMovieSrv->Release(); g_bootMovieSrv = nullptr; }
    if (g_bootMovieTexture) { g_bootMovieTexture->Release(); g_bootMovieTexture = nullptr; }
    g_bootMovieWidth = g_bootMovieHeight = 0;
}

static bool UploadBootMovieFrame(const bf6::ui_runtime::DecodedMovieFrame& frame)
{
    if (!g_dev || !g_ctx || !frame.width || !frame.height || frame.stride <= 0 ||
        frame.bgra.size() < static_cast<size_t>(frame.stride) * frame.height)
        return false;
    if (!g_bootMovieTexture || frame.width != g_bootMovieWidth ||
        frame.height != g_bootMovieHeight)
    {
        ReleaseBootMovieGpu();
        D3D11_TEXTURE2D_DESC desc{};
        desc.Width = frame.width;
        desc.Height = frame.height;
        desc.MipLevels = 1;
        desc.ArraySize = 1;
        desc.Format = DXGI_FORMAT_B8G8R8A8_UNORM;
        desc.SampleDesc.Count = 1;
        desc.Usage = D3D11_USAGE_DEFAULT;
        desc.BindFlags = D3D11_BIND_SHADER_RESOURCE;
        D3D11_SUBRESOURCE_DATA initial{};
        initial.pSysMem = frame.bgra.data();
        initial.SysMemPitch = static_cast<UINT>(frame.stride);
        if (FAILED(g_dev->CreateTexture2D(&desc, &initial, &g_bootMovieTexture)) ||
            !g_bootMovieTexture ||
            FAILED(g_dev->CreateShaderResourceView(g_bootMovieTexture, nullptr,
                                                   &g_bootMovieSrv)))
        {
            ReleaseBootMovieGpu();
            return false;
        }
        g_bootMovieWidth = frame.width;
        g_bootMovieHeight = frame.height;
        return true;
    }
    g_ctx->UpdateSubresource(g_bootMovieTexture, 0, nullptr, frame.bgra.data(),
                             static_cast<UINT>(frame.stride), 0);
    return true;
}

static void PublishBootMovieEos()
{
    bool expected = false;
    if (g_bootCompletionLatched.compare_exchange_strong(
            expected, true, std::memory_order_acq_rel))
    {
        g_bootCompletionCause.store(
            static_cast<int>(BootCompletionCause::MovieEos),
            std::memory_order_release);
        g_bootMovieComplete.store(true, std::memory_order_release);
    }
}

static bool PrimeBootMovieDecoder()
{
    std::string error;
    g_bootMovieAudioPlayer.Stop();
    g_bootMovieAudioActive = false;
    g_bootMovieAudioStreamEos = false;
    g_bootMoviePairDecodedEos = false;
    g_bootMovieAudioStartTimestamp = 0;
    g_bootMovieAudioSampleRate = 0;
    g_bootMovieDecoder =
        bf6::ui_runtime::CreateMediaFoundationMovieDecoder(error);
    if (!g_bootMovieDecoder || !g_bootMovieDecoder->Open(g_bootMovie, error))
    {
        std::fprintf(stderr, "Boot movie decoder unavailable: %s\n", error.c_str());
        g_bootMovieDecoder.reset();
        g_bootMovieHasNextFrame = false;
        return false;
    }
    g_bootMovieComplete.store(false, std::memory_order_release);
    g_bootCompletionLatched.store(false, std::memory_order_release);
    g_bootCompletionCause.store(
        static_cast<int>(BootCompletionCause::None),
        std::memory_order_release);
    g_bootMovieDecoder->SetCompletionCallback(
        [](const bf6::ui_runtime::MovieCompletionEvent& event)
        {
            if (event.restarted) return;
            g_bootMoviePairDecodedEos = true;
            // Decoding has reached both stream ends. With audio, presentation
            // ends only after XAudio2 drains the already submitted tail.
            if (!g_bootMovieAudioActive)
                PublishBootMovieEos();
        });
    const bf6::ui_runtime::MovieFrameStatus status =
        g_bootMovieDecoder->ReadFrame(g_bootMovieNextFrame, error);
    if (status != bf6::ui_runtime::MovieFrameStatus::Frame)
    {
        std::fprintf(stderr, "Boot movie first frame unavailable: %s\n", error.c_str());
        g_bootMovieDecoder.reset();
        g_bootMovieHasNextFrame = false;
        return false;
    }
    g_bootMovieHasNextFrame = true;

    if (g_bootMovieDecoder->HasAudio())
    {
        const bf6::ui_runtime::MovieAudioFormat format =
            g_bootMovieDecoder->AudioFormat();
        if (g_bootMovieAudioPlayer.Open(
                format.channels, format.sample_rate, 1.0f, error))
        {
            bool haveTimestamp = false;
            const uint64_t prebufferFrames = format.sample_rate / 5u;
            while (g_bootMovieAudioPlayer.BufferedFrames() < prebufferFrames)
            {
                bf6::ui_runtime::DecodedMovieAudio audio;
                const bf6::ui_runtime::MovieAudioStatus audioStatus =
                    g_bootMovieDecoder->ReadAudio(audio, error);
                if (audioStatus ==
                    bf6::ui_runtime::MovieAudioStatus::EndOfStream)
                {
                    g_bootMovieAudioStreamEos = true;
                    break;
                }
                if (audioStatus !=
                    bf6::ui_runtime::MovieAudioStatus::Sample ||
                    !g_bootMovieAudioPlayer.Submit(audio.pcm, error))
                    break;
                if (!haveTimestamp)
                {
                    haveTimestamp = true;
                    g_bootMovieAudioStartTimestamp = audio.timestamp_100ns;
                }
            }
            if (g_bootMovieAudioPlayer.SubmittedFrames() > 0 &&
                g_bootMovieAudioPlayer.Start(error))
            {
                g_bootMovieAudioActive = true;
                g_bootMovieAudioSampleRate = format.sample_rate;
                std::fprintf(stderr,
                    "Boot movie audio: PCM %u Hz %u ch, prebuffer=%llu frames\n",
                    format.sample_rate, format.channels,
                    static_cast<unsigned long long>(
                        g_bootMovieAudioPlayer.BufferedFrames()));
            }
            else
                g_bootMovieAudioPlayer.Stop();
        }
        if (!g_bootMovieAudioActive)
            std::fprintf(stderr,
                "Boot movie audio unavailable; video clock fallback: %s\n",
                error.c_str());
    }
    g_bootMovieClock = std::chrono::steady_clock::now() -
        std::chrono::nanoseconds(g_bootMovieNextFrame.timestamp_100ns * 100);
    return true;
}

static const char* BootCompletionCauseName(BootCompletionCause cause)
{
    switch (cause)
    {
    case BootCompletionCause::MovieEos: return "movie EOS";
    case BootCompletionCause::ConfirmSkip: return "ConfirmSkip";
    case BootCompletionCause::EscapeSkip: return "ESCSkip";
    case BootCompletionCause::AuthoredSkipButton: return "CL_HUD_SkipButton";
    default: return "none";
    }
}

static const BootEventCarrier* BootCarrier(
    const BootEventGraph& graph, BootCompletionCause cause)
{
    switch (cause)
    {
    case BootCompletionCause::MovieEos: return &graph.movie_eos;
    case BootCompletionCause::ConfirmSkip: return &graph.confirm_skip;
    case BootCompletionCause::EscapeSkip: return &graph.escape_skip;
    case BootCompletionCause::AuthoredSkipButton: return &graph.button_skip;
    default: return nullptr;
    }
}

static bool RequestBootCompletion(BootCompletionCause cause)
{
    BootEventGraph graph;
    {
        std::lock_guard<std::mutex> lock(g_bootEventGraphLock);
        graph = g_bootEventGraph;
    }
    const BootEventCarrier* carrier = BootCarrier(graph, cause);
    if (!graph.valid || !carrier || carrier->instance < 0 ||
        carrier->fanout.empty())
    {
        std::fprintf(stderr,
            "Boot input rejected: installed %s event carrier is unresolved\n",
            BootCompletionCauseName(cause));
        return false;
    }

    bool expected = false;
    if (!g_bootCompletionLatched.compare_exchange_strong(
            expected, true, std::memory_order_acq_rel))
        return false;

    // The installed skip fan-out includes the movie Stop input and the same
    // completion sink reached by EOS.  The decoder reset is the standalone
    // host's execution of that proven Stop boundary; the outer screen choice
    // remains the explicitly labelled offline policy below.
    if (cause != BootCompletionCause::MovieEos)
    {
        g_bootMovieAudioPlayer.Stop();
        g_bootMovieAudioActive = false;
        g_bootMovieDecoder.reset();
        g_bootMovieHasNextFrame = false;
    }
    g_bootCompletionCause.store(static_cast<int>(cause),
                                std::memory_order_release);
    g_bootMovieComplete.store(true, std::memory_order_release);
    std::fprintf(stderr,
        "Boot authored event: %s instance=%d source=%08X fanout=%zu "
        "completion=%d:%08X\n",
        carrier->name.c_str(), carrier->instance, carrier->source_event,
        carrier->fanout.size(), graph.completion_instance,
        graph.completion_event);
    return true;
}

static void PumpBootMovie()
{
    if (g_bootMoviePending.exchange(false, std::memory_order_acquire))
    {
        {
            std::lock_guard<std::mutex> lock(g_bootMovieLock);
            g_bootMovie = std::move(g_pendingBootMovie);
        }
        PrimeBootMovieDecoder();
    }
    if (!g_bootMovieDecoder) return;

    // Keep about 250 ms submitted. Read the exact PCM stream before gating
    // video so audio remains the master clock and never starves behind a slow
    // frame upload. If XAudio2 is unavailable, drain/discard in bounded batches
    // so Media Foundation can still reach the pair's authored EOS.
    if (g_bootMovieDecoder->HasAudio() && !g_bootMovieAudioStreamEos)
    {
        const uint64_t targetFrames = g_bootMovieAudioActive
            ? g_bootMovieAudioSampleRate / 4u : 0u;
        for (int guard = 0; guard < 128; ++guard)
        {
            if (g_bootMovieAudioActive &&
                g_bootMovieAudioPlayer.BufferedFrames() >= targetFrames)
                break;
            bf6::ui_runtime::DecodedMovieAudio audio;
            std::string audioError;
            const bf6::ui_runtime::MovieAudioStatus audioStatus =
                g_bootMovieDecoder->ReadAudio(audio, audioError);
            if (audioStatus == bf6::ui_runtime::MovieAudioStatus::Sample)
            {
                if (g_bootMovieAudioActive &&
                    !g_bootMovieAudioPlayer.Submit(audio.pcm, audioError))
                {
                    std::fprintf(stderr,
                        "Boot movie audio submit failed; video clock fallback: %s\n",
                        audioError.c_str());
                    g_bootMovieAudioPlayer.Stop();
                    g_bootMovieAudioActive = false;
                    g_bootMovieClock = std::chrono::steady_clock::now() -
                        std::chrono::nanoseconds(
                            g_bootMovieHasNextFrame
                                ? g_bootMovieNextFrame.timestamp_100ns * 100
                                : 0);
                }
                continue;
            }
            if (audioStatus == bf6::ui_runtime::MovieAudioStatus::Error)
                std::fprintf(stderr, "Boot movie audio decode failed: %s\n",
                             audioError.c_str());
            g_bootMovieAudioStreamEos = true;
            break;
        }
    }

    if (g_bootMoviePairDecodedEos && g_bootMovieAudioActive &&
        g_bootMovieAudioPlayer.IsDrained())
    {
        PublishBootMovieEos();
        g_bootMovieAudioPlayer.Stop();
        g_bootMovieAudioActive = false;
    }

    if (!g_bootMovieHasNextFrame) return;
    const int64_t elapsed = g_bootMovieAudioActive &&
        g_bootMovieAudioSampleRate > 0
        ? g_bootMovieAudioStartTimestamp + static_cast<int64_t>(
            g_bootMovieAudioPlayer.SamplesPlayed() * 10000000ull /
            g_bootMovieAudioSampleRate)
        : std::chrono::duration_cast<std::chrono::nanoseconds>(
            std::chrono::steady_clock::now() - g_bootMovieClock).count() / 100;
    if (elapsed < g_bootMovieNextFrame.timestamp_100ns) return;
    if (!UploadBootMovieFrame(g_bootMovieNextFrame))
    {
        std::fprintf(stderr, "Boot movie D3D upload failed\n");
        g_bootMovieAudioPlayer.Stop();
        g_bootMovieAudioActive = false;
        g_bootMovieDecoder.reset();
        g_bootMovieHasNextFrame = false;
        return;
    }

    std::string error;
    const bf6::ui_runtime::MovieFrameStatus status =
        g_bootMovieDecoder->ReadFrame(g_bootMovieNextFrame, error);
    if (status == bf6::ui_runtime::MovieFrameStatus::Frame) return;
    if (status == bf6::ui_runtime::MovieFrameStatus::EndOfStream)
    {
        // The video stream may end before the audio tail. Keep the shared
        // source reader alive until ReadAudio reaches its stream end and the
        // submitted PCM drains; the last decoded frame remains resident.
        g_bootMovieHasNextFrame = false;
        if (!g_bootMovieAudioActive &&
            (g_bootMoviePairDecodedEos || g_bootMovieAudioStreamEos))
            PublishBootMovieEos();
        return;
    }
    std::fprintf(stderr, "Boot movie decode failed: %s\n", error.c_str());
    g_bootMovieAudioPlayer.Stop();
    g_bootMovieAudioActive = false;
    g_bootMovieDecoder.reset();
    g_bootMovieHasNextFrame = false;
}

static void ReleaseStartMovieGpu()
{
    if (g_startMovieSrv) { g_startMovieSrv->Release(); g_startMovieSrv = nullptr; }
    if (g_startMovieTexture) { g_startMovieTexture->Release(); g_startMovieTexture = nullptr; }
    g_startMovieWidth = g_startMovieHeight = 0;
}

