static bool PrimeStartMovieDecoder()
{
    std::string error;
    g_startMovieDecoder =
        bf6::ui_runtime::CreateMediaFoundationMovieDecoder(error);
    if (!g_startMovieDecoder || !g_startMovieDecoder->Open(g_startMovie, error))
    {
        std::fprintf(stderr, "Start background movie decoder unavailable: %s\n",
                     error.c_str());
        g_startMovieDecoder.reset();
        g_startMovieHasNextFrame = false;
        return false;
    }
    // Current-install RimeMovieElementData instance BGVideo authors Loop=true
    // and AutoStart=true.  MovieTexture2 itself intentionally carries neither;
    // the playback policy belongs to the element that selected this stream.
    bf6::ui_runtime::MoviePlaybackPolicy policy;
    policy.looping_is_authored = true;
    policy.looping = true;
    g_startMovieDecoder->SetPlaybackPolicy(policy);
    g_startMovieDecoder->SetCompletionCallback(
        [](const bf6::ui_runtime::MovieCompletionEvent& event)
        {
            if (event.restarted)
                g_startMovieClock = std::chrono::steady_clock::now();
        });
    const bf6::ui_runtime::MovieFrameStatus status =
        g_startMovieDecoder->ReadFrame(g_startMovieNextFrame, error);
    if (status != bf6::ui_runtime::MovieFrameStatus::Frame)
    {
        std::fprintf(stderr,
                     "Start background movie first frame unavailable: %s\n",
                     error.c_str());
        g_startMovieDecoder.reset();
        g_startMovieHasNextFrame = false;
        return false;
    }
    g_startMovieHasNextFrame = true;
    g_startMovieClock = std::chrono::steady_clock::now() -
        std::chrono::nanoseconds(g_startMovieNextFrame.timestamp_100ns * 100);
    return true;
}

static void DeactivateStartMoviePlayback()
{
    // MovieTexture2 playback belongs to bootflowstartscreen. The uploaded
    // last frame may remain resident; only the active decoder and its
    // presentation clock are route-owned.
    g_startMovieDecoder.reset();
    g_startMovieHasNextFrame = false;
    g_startMovieSurfaceActive = false;
}

static void PumpStartMovie(bool active)
{
    // Do not start its presentation clock while the preceding logo parade is
    // still visible.  The raw bytes may be ready, but AutoStart belongs to the
    // moment this authored surface becomes active.
    const bool becameActive = active && !g_startMovieSurfaceActive;
    g_startMovieSurfaceActive = active;
    if (!active)
    {
        if (g_startMovieDecoder || g_startMovieHasNextFrame)
            DeactivateStartMoviePlayback();
        return;
    }
    if (
        g_startMoviePending.exchange(false, std::memory_order_acquire))
    {
        {
            std::lock_guard<std::mutex> lock(g_startMovieLock);
            g_startMovie = std::move(g_pendingStartMovie);
        }
        PrimeStartMovieDecoder();
    }
    else if (becameActive && !g_startMovieDecoder &&
             !g_startMovie.webm.empty())
        PrimeStartMovieDecoder();
    if (!g_startMovieDecoder || !g_startMovieHasNextFrame) return;

    const int64_t elapsed = std::chrono::duration_cast<std::chrono::nanoseconds>(
        std::chrono::steady_clock::now() - g_startMovieClock).count() / 100;
    if (elapsed < g_startMovieNextFrame.timestamp_100ns) return;
    if (!UploadStartMovieFrame(g_startMovieNextFrame))
    {
        std::fprintf(stderr, "Start background movie D3D upload failed\n");
        g_startMovieDecoder.reset();
        g_startMovieHasNextFrame = false;
        return;
    }

    std::string error;
    const bf6::ui_runtime::MovieFrameStatus status =
        g_startMovieDecoder->ReadFrame(g_startMovieNextFrame, error);
    if (status == bf6::ui_runtime::MovieFrameStatus::Frame) return;
    std::fprintf(stderr, "Start background movie decode failed: %s\n",
                 error.c_str());
    g_startMovieDecoder.reset();
    g_startMovieHasNextFrame = false;
}

