// A front-end VisualEnvironment stack replaces whole COMPONENTS.  The
// customization partition carries fog/exposure/grading/AO (plus two component
// types this compact ABI does not expose), while the base hangar continues to
// provide sun/sky/GI/shadows.  Zero is an authored value, so presence is tested
// only through the component mask and never by looking at the numbers.
static bf6_ve_lighting ComposeArmoryEnvironment(const bf6_ve_lighting& base,
                                                 const bf6_ve_lighting& layer)
{
    bf6_ve_lighting out = base;
    if (layer.components & BF6_VE_FOG) {
        out.fog_height_enable = layer.fog_height_enable;
        out.fog_color_enable = layer.fog_color_enable;
        out.fog_gradient_enable = layer.fog_gradient_enable;
        for (int i = 0; i < 3; ++i) out.fog_color[i] = layer.fog_color[i];
        out.fog_dist_start = layer.fog_dist_start; out.fog_dist_end = layer.fog_dist_end;
        out.fog_color_start = layer.fog_color_start; out.fog_color_end = layer.fog_color_end;
        out.fog_height_start = layer.fog_height_start; out.fog_height_end = layer.fog_height_end;
        out.fog_altitude = layer.fog_altitude; out.fog_depth = layer.fog_depth;
        out.fog_visibility_range = layer.fog_visibility_range;
        out.volumetrics_enable = layer.volumetrics_enable;
        out.sun_scatter_intensity = layer.sun_scatter_intensity;
        out.local_light_scatter_intensity = layer.local_light_scatter_intensity;
    }
    if (layer.components & BF6_VE_EXPOSURE) {
        out.auto_exposure = layer.auto_exposure; out.ev = layer.ev;
        out.ev_max = layer.ev_max; out.exposure_compensation = layer.exposure_compensation;
        for (int i = 0; i < 3; ++i) out.bloom_scale[i] = layer.bloom_scale[i];
        out.bloom_method = layer.bloom_method;
        std::memcpy(out.lens_dirt_res, layer.lens_dirt_res, sizeof(out.lens_dirt_res));
        out.lens_dirt_texture = layer.lens_dirt_texture;
    }
    if (layer.components & BF6_VE_GRADING) {
        out.grading_enable = layer.grading_enable;
        for (int i = 0; i < 3; ++i) {
            out.grade_brightness[i] = layer.grade_brightness[i];
            out.grade_contrast[i] = layer.grade_contrast[i];
            out.grade_saturation[i] = layer.grade_saturation[i];
        }
        out.grade_hue = layer.grade_hue;
        std::memcpy(out.grading_lut_res, layer.grading_lut_res, sizeof(out.grading_lut_res));
        out.grading_lut_texture = layer.grading_lut_texture;
    }
    if (layer.components & BF6_VE_WHITE_BALANCE) {
        out.white_temperature = layer.white_temperature;
        out.white_tint = layer.white_tint;
    }
    if (layer.components & BF6_VE_AO) {
        out.ao_affects_outdoor_light = layer.ao_affects_outdoor_light;
        out.ao_affects_local_light = layer.ao_affects_local_light;
        out.ssao_max_distance_inner = layer.ssao_max_distance_inner;
        out.ssao_max_distance_outer = layer.ssao_max_distance_outer;
        out.hbao_radius = layer.hbao_radius; out.hbao_contrast = layer.hbao_contrast;
        out.dynamic_ao_factor = layer.dynamic_ao_factor;
    }
    out.components |= layer.components;
    out.component_count = base.component_count + layer.component_count;
    return out;
}

// Convert a scene-world light into the local coordinates of the actor that
// hosts the weapon.  Walk transforms are x*basis0 + y*basis1 + z*basis2 +
// origin; pf_weaponcustomization's measured basis is orthonormal, so its
// inverse is the three basis dot products.  This keeps the viewer attached to
// the runtime placement graph instead of carrying a copied station offset.
static void ArmoryWorldToWeaponLocal(const float world[12],
                                      const float weapon[12], float local[12])
{
    const float* a0 = weapon + 0;
    const float* a1 = weapon + 3;
    const float* a2 = weapon + 6;
    const float* ao = weapon + 9;
    auto project = [&](const float* v, float* dst) {
        dst[0] = v[0]*a0[0] + v[1]*a0[1] + v[2]*a0[2];
        dst[1] = v[0]*a1[0] + v[1]*a1[1] + v[2]*a1[2];
        dst[2] = v[0]*a2[0] + v[1]*a2[1] + v[2]*a2[2];
    };
    project(world + 0, local + 0);
    project(world + 3, local + 3);
    project(world + 6, local + 6);
    const float delta[3] = {
        world[9] - ao[0], world[10] - ao[1], world[11] - ao[2]
    };
    project(delta, local + 9);
}

static void ArmoryLightWorldToWeaponLocal(bf6_light& light,
                                           const float weapon[12])
{
    float local[12] = {};
    ArmoryWorldToWeaponLocal(light.xform, weapon, local);
    for (int i = 0; i < 12; ++i) light.xform[i] = local[i];
}

static void ComposePlacement(const float local[12], const float parent[12],
                             float world[12])
{
    auto transformVector = [&](const float* v, float* out) {
        out[0] = v[0]*parent[0] + v[1]*parent[3] + v[2]*parent[6];
        out[1] = v[0]*parent[1] + v[1]*parent[4] + v[2]*parent[7];
        out[2] = v[0]*parent[2] + v[1]*parent[5] + v[2]*parent[8];
    };
    transformVector(local + 0, world + 0);
    transformVector(local + 3, world + 3);
    transformVector(local + 6, world + 6);
    transformVector(local + 9, world + 9);
    world[9] += parent[9]; world[10] += parent[10]; world[11] += parent[11];
}

static XMMATRIX PlacementMatrix(const float transform[12])
{
    return XMMATRIX(
        transform[0], transform[1], transform[2], 0.f,
        transform[3], transform[4], transform[5], 0.f,
        transform[6], transform[7], transform[8], 0.f,
        transform[9], transform[10], transform[11], 1.f);
}

static void ExpandPlacementBounds(const float lo[3], const float hi[3],
                                  const float transform[12], float outLo[3],
                                  float outHi[3])
{
    for (int corner = 0; corner < 8; ++corner)
    {
        const float point[3] = {
            (corner & 1) ? hi[0] : lo[0],
            (corner & 2) ? hi[1] : lo[1],
            (corner & 4) ? hi[2] : lo[2] };
        const float placed[3] = {
            point[0] * transform[0] + point[1] * transform[3] +
                point[2] * transform[6] + transform[9],
            point[0] * transform[1] + point[1] * transform[4] +
                point[2] * transform[7] + transform[10],
            point[0] * transform[2] + point[1] * transform[5] +
                point[2] * transform[8] + transform[11] };
        for (int axis = 0; axis < 3; ++axis)
        {
            outLo[axis] = (std::min)(outLo[axis], placed[axis]);
            outHi[axis] = (std::max)(outHi[axis], placed[axis]);
        }
    }
}

static bool LoadSoldierPresentationTransforms(float out[4][12],
                                               float outLinkFrame[12])
{
    static const char* kPrefab =
        "game/glacierflow/flow_mainmenu/prefabs/pf_soldiercustomization";
    static const char* kPresentationSoldier =
        "common/characters/presentationsoldier/presentationsoldier.ebx";
    static const char* kMeshTag =
        "common/characters/_shared/meshdefinitiontags/"
        "lpf_mpsoldier_meshtagging.ebx";
    char error[512] = {};
    const int count = bf6_asset_instances(
        g_bf6, kPrefab, nullptr, 0, error, (int)sizeof(error));
    if (count <= 0) return false;
    std::vector<bf6_instance> rows((size_t)count);
    if (bf6_asset_instances(g_bf6, kPrefab, rows.data(), count, error,
                            (int)sizeof(error)) != count)
        return false;

    std::vector<const bf6_instance*> actors;
    for (const bf6_instance& row : rows)
    {
        if (!row.source || !row.res_name ||
            std::strcmp(row.source, kPresentationSoldier) != 0 ||
            std::strcmp(row.res_name, kMeshTag) != 0)
            continue;
        actors.push_back(&row);
    }
    if (actors.size() != 4) return false;
    std::sort(actors.begin(), actors.end(),
        [](const bf6_instance* a, const bf6_instance* b) {
            return a->xform[9] < b->xform[9];
        });

    // The main-menu camera graph routes both LoadoutOverviewPosition and
    // LoadoutOverviewLookAt through SoldierLoadout to this child prefab.  The
    // enclosing pf_soldierloadout transform is deliberately not the camera
    // link: composing against that wrapper gives the installed actor rows but
    // moves the camera 3.06 m forward (the rejected pass-7 control). Convert
    // the linked child root through the same lowest-X actor origin used for
    // every rendered mesh and hangar placement so all consumers share a frame.
    const float prefabRoot[12] = {
        1.f, 0.f, 0.f, 0.f, 1.f, 0.f,
        0.f, 0.f, 1.f, 0.f, 0.f, 0.f };
    ArmoryWorldToWeaponLocal(prefabRoot, actors[0]->xform, outLinkFrame);

    // The signed-in retail capture establishes the actor-to-class projection:
    // the class-selection camera sees Wisp/Jazz/Know/Aver left to right while
    // the decoded prefab origins ascend as Aver/Know/Jazz/Wisp. Use the
    // lowest-X actor as the same local origin selected by WorkerLoadStudio,
    // but assign class identities in descending X while retaining each
    // actor's complete shipped rotation and translation.
    for (int classIndex = 0; classIndex < 4; ++classIndex)
        ArmoryWorldToWeaponLocal(
            actors[(size_t)(3 - classIndex)]->xform, actors[0]->xform,
            out[classIndex]);
    std::fprintf(stderr,
        "soldier presentation transforms: exact=1 actors=%zu "
        "xyz=(%.6f %.6f %.6f)/(%.6f %.6f %.6f)/"
        "(%.6f %.6f %.6f)/(%.6f %.6f %.6f)\n",
        actors.size(), out[0][9], out[0][10], out[0][11],
        out[1][9], out[1][10], out[1][11],
        out[2][9], out[2][10], out[2][11],
        out[3][9], out[3][10], out[3][11]);
    return true;
}

static void FillArmoryConstants(CB& cb, const XMMATRIX& model,
                                const XMMATRIX& view, const XMMATRIX& proj,
                                const XMVECTOR& eye, float autoFocusDistance,
                                const bf6_armory_camera_mode* activeCamera,
                                const GpuSection* section)
{
    // Studio metadata is decoded after the first weapon becomes interactive.
    // Publish and consume the light/environment set as one coherent snapshot.
    std::lock_guard<std::mutex> sceneGuard(g_sceneLock);
    XMStoreFloat4x4(&cb.mvp, XMMatrixTranspose(model * view * proj));
    XMStoreFloat4x4(&cb.model, XMMatrixTranspose(model));
    const XMMATRIX normalTransform =
        XMMatrixTranspose(XMMatrixInverse(nullptr, model));
    XMStoreFloat4x4(&cb.normalModel, XMMatrixTranspose(normalTransform));
    XMStoreFloat4(&cb.camPos, eye);
    const bool rawVehiclePresentation = g_showScenePresentation &&
        g_scenePresentationKind == ScenePresentationKind::Vehicle;
    cb.opts = XMFLOAT4(section && section->srv[1] ? 1.f : 0.f,
                       section && section->srv[2] ? 1.f : 0.f,
                       g_useUv1 ? 1.f : 0.f,
                       (g_unlit || rawVehiclePresentation) ? 1.f : 0.f);
    cb.baseColor = section ? section->base_color : XMFLOAT4(1, 1, 1, 1);
    cb.material = section ? section->material : XMFLOAT4(0.5f, 0, 0, 0);
    cb.emissiveColor = section ? section->emissive : XMFLOAT4(0, 0, 0, 0);
    cb.renderFlags = section ? section->render_flags : XMFLOAT4(0, 0, 0, 0);
    cb.shaderFlags = section ? section->shader_flags : XMFLOAT4(0, 0, 0, 0);
    cb.shaderFlags.y = XMVectorGetX(XMMatrixDeterminant(model)) < 0.f
        ? -1.f : 1.f;
    cb.shaderFlags.z = g_hangarReflectionSrv ? 1.f : 0.f;
    // The current online research corpus has a controlled magenta/green
    // failure for direct binding of these raw voxels and explicitly leaves
    // voxel order, channel semantics and HDR transfer open. Keep the exact
    // volume resident for diagnostics, but never alter production colour
    // until that consumer contract is recovered.
    const bool diagnosticRawGradingLut = g_gradingLutSrv &&
        std::getenv("BF6_DIAGNOSTIC_GRADING_LUT_RAW") != nullptr;

    float ev = g_hasArmoryEnvironment ? g_armoryEnvironment.ev : 0.f;
    // Keep exposure experiments explicit while the remaining native
    // photometric-unit conversion is being recovered. This affects captures
    // only when deliberately requested and never changes the authored EV.
    if (const char* diagnosticStops = std::getenv(
            "BF6_DIAGNOSTIC_EXPOSURE_STOPS"))
    {
        char* end = nullptr;
        const float parsed = std::strtof(diagnosticStops, &end);
        if (end && end != diagnosticStops && std::isfinite(parsed))
            ev += parsed;
    }
    const float exposureComp = g_hasArmoryEnvironment
        ? g_armoryEnvironment.exposure_compensation : 0.f;
    const bf6_armory_camera_mode* lens = activeCamera;
    const float presentationLensMode = !g_showScenePresentation ? 0.f :
        (g_scenePresentationKind == ScenePresentationKind::Soldier && lens
            ? 1.f : 2.f);
    cb.scene = XMFLOAT4((float)(std::min)(g_armoryLights.size(), (size_t)32),
                        ev, exposureComp, presentationLensMode);
    const float authoredFocus = lens ? lens->focus_distance : 1.f;
    cb.postCamera = XMFLOAT4(0.005f, 200.f,
        authoredFocus < 0.f ? autoFocusDistance : authoredFocus,
        lens ? lens->aperture : 1.f);
    cb.postLens = XMFLOAT4(
        (lens ? lens->focal_length_mm : 35.f) * 0.001f,
        (g_hasArmoryCameraSensor ? g_armoryCameraSensor.height_mm : 20.25f) * 0.001f,
        (float)g_w, (float)g_h);
    // Identity is the only truthful state before the deferred environment
    // payload arrives.  Zero-initialising these vectors turns a black HDR
    // scene into mid-grey in PostPS: zero brightness erases the scene, zero
    // contrast then pins it at the 0.18 pivot, and zero saturation preserves
    // that invented grey.  This was the full-screen grey capture, not an
    // authored Rime layer.
    cb.gradeBrightness = XMFLOAT4(
        1.f, 1.f, 1.f, diagnosticRawGradingLut ? 1.f : 0.f);
    cb.gradeContrast = XMFLOAT4(1.f, 1.f, 1.f, 0.f);
    cb.gradeSaturation = XMFLOAT4(1.f, 1.f, 1.f, 0.f);
    if (g_hasArmoryEnvironment) {
        cb.gradeBrightness = XMFLOAT4(g_armoryEnvironment.grade_brightness[0],
                                      g_armoryEnvironment.grade_brightness[1],
                                      g_armoryEnvironment.grade_brightness[2],
                                      diagnosticRawGradingLut ? 1.f : 0.f);
        cb.gradeContrast = XMFLOAT4(g_armoryEnvironment.grade_contrast[0],
                                    g_armoryEnvironment.grade_contrast[1],
                                    g_armoryEnvironment.grade_contrast[2], 0);
        cb.gradeSaturation = XMFLOAT4(g_armoryEnvironment.grade_saturation[0],
                                      g_armoryEnvironment.grade_saturation[1],
                                      g_armoryEnvironment.grade_saturation[2], 0);
        cb.giSkyBounce = XMFLOAT4(g_armoryEnvironment.gi_sky_color[0],
                                  g_armoryEnvironment.gi_sky_color[1],
                                  g_armoryEnvironment.gi_sky_color[2],
                                  g_armoryEnvironment.gi_bounce_scale);
        cb.giGround = XMFLOAT4(g_armoryEnvironment.gi_ground_color[0],
                               g_armoryEnvironment.gi_ground_color[1],
                               g_armoryEnvironment.gi_ground_color[2], 0.f);
    }
    // The compatibility BRDF does not yet reproduce Frostbite's runtime
    // photometric-unit normalization. On the soldier studio it otherwise
    // clips correctly bound camouflage to white. Keep the raw path available
    // through the diagnostic override below.
    float diagnosticDirectScale =
        g_showScenePresentation &&
        g_scenePresentationKind == ScenePresentationKind::Soldier
            ? 0.10f : 1.f;
    if (const char* raw = std::getenv(
            "BF6_DIAGNOSTIC_DIRECT_LIGHT_SCALE"))
    {
        char* end = nullptr;
        const float parsed = std::strtof(raw, &end);
        if (end && end != raw && std::isfinite(parsed) && parsed >= 0.f)
            diagnosticDirectScale = parsed;
    }
    for (size_t k = 0; k < g_armoryLights.size() && k < 32; k++) {
        const bf6_light& L = g_armoryLights[k];
        const float fx = L.xform[6], fy = L.xform[7], fz = L.xform[8];
        const float fl = std::sqrt(fx*fx + fy*fy + fz*fz);
        const float bx = fl > 0.f ? -fx/fl : 0.f;
        const float by = fl > 0.f ? -fy/fl : 0.f;
        const float bz = fl > 0.f ? -fz/fl : 0.f;
        const float outer = std::cos(XMConvertToRadians(L.outer_angle * 0.5f));
        const float inner = L.inner_angle > 0.f
            ? std::cos(XMConvertToRadians(L.inner_angle * 0.5f)) : 1.f;
        cb.lightPosType[k] = XMFLOAT4(L.xform[9], L.xform[10], L.xform[11],
                                      L.type == BF6_LIGHT_SPOT ? 1.f : 0.f);
        cb.lightDirOuter[k] = XMFLOAT4(bx, by, bz, outer);
        cb.lightColorFlux[k] = XMFLOAT4(L.color[0], L.color[1], L.color[2],
            L.intensity * L.dimmer * diagnosticDirectScale);
        const float flags = (L.affect_diffuse ? 1.f : 0.f) +
                            (L.affect_specular ? 2.f : 0.f);
        cb.lightParams[k] = XMFLOAT4(inner, L.attenuation_radius,
                                     L.shape_radius, flags);
        cb.lightExtra[k] = XMFLOAT4(L.attenuation_offset,
                                    0.f, 0.f, 0.f);
    }
}

