// Copy a placed static mesh while the libbf6 context is owned by the worker.
// Material scope belongs to the INSTANCE, so the caller must already have used
// bf6_read_mesh_scoped with that placement's bundle and variation.
static void MultiplyAffine(const float* a, const float* b, float* out)
{
    for (int row = 0; row < 4; ++row)
        for (int column = 0; column < 3; ++column) {
            float value = 0.f;
            for (int k = 0; k < 3; ++k)
                value += a[row * 3 + k] * b[k * 3 + column];
            if (row == 3) value += b[9 + column];
            out[row * 3 + column] = value;
        }
}

static bool InvertAffine(const float* source, float* out)
{
    const float a = source[0], b = source[1], c = source[2];
    const float d = source[3], e = source[4], f = source[5];
    const float g = source[6], h = source[7], i = source[8];
    const float determinant = a * (e * i - f * h) -
        b * (d * i - f * g) + c * (d * h - e * g);
    if (!std::isfinite(determinant) || std::fabs(determinant) < 1e-8f)
        return false;
    const float inverseDeterminant = 1.f / determinant;
    out[0] = (e * i - f * h) * inverseDeterminant;
    out[1] = (c * h - b * i) * inverseDeterminant;
    out[2] = (b * f - c * e) * inverseDeterminant;
    out[3] = (f * g - d * i) * inverseDeterminant;
    out[4] = (a * i - c * g) * inverseDeterminant;
    out[5] = (c * d - a * f) * inverseDeterminant;
    out[6] = (d * h - e * g) * inverseDeterminant;
    out[7] = (b * g - a * h) * inverseDeterminant;
    out[8] = (a * e - b * d) * inverseDeterminant;
    out[9] = -(source[9] * out[0] + source[10] * out[3] +
                 source[11] * out[6]);
    out[10] = -(source[9] * out[1] + source[10] * out[4] +
                  source[11] * out[7]);
    out[11] = -(source[9] * out[2] + source[10] * out[5] +
                  source[11] * out[8]);
    return true;
}

static float SoldierPointDistance(const float* a, const float* b)
{
    const float x = a[9] - b[9];
    const float y = a[10] - b[10];
    const float z = a[11] - b[11];
    return std::sqrt(x * x + y * y + z * z);
}

static bool RotateSoldierModelBasis(float* modelMatrix,
                                    FXMVECTOR oldDirection,
                                    FXMVECTOR newDirection)
{
    XMVECTOR from = XMVector3Normalize(oldDirection);
    XMVECTOR to = XMVector3Normalize(newDirection);
    float dot = XMVectorGetX(XMVector3Dot(from, to));
    if (!std::isfinite(dot)) return false;
    dot = (std::max)(-1.f, (std::min)(dot, 1.f));
    XMVECTOR axis = XMVector3Cross(from, to);
    float axisLength = XMVectorGetX(XMVector3Length(axis));
    if (axisLength < 1e-6f)
    {
        if (dot > 0.999999f) return true;
        const XMVECTOR fallback = std::fabs(XMVectorGetX(from)) < 0.8f
            ? XMVectorSet(1.f, 0.f, 0.f, 0.f)
            : XMVectorSet(0.f, 1.f, 0.f, 0.f);
        axis = XMVector3Normalize(XMVector3Cross(from, fallback));
    }
    else axis = XMVectorScale(axis, 1.f / axisLength);
    const XMMATRIX rotation = XMMatrixRotationAxis(axis, std::acos(dot));
    XMFLOAT4X4 stored;
    XMStoreFloat4x4(&stored, rotation);
    float affineRotation[12] = {
        stored._11, stored._12, stored._13,
        stored._21, stored._22, stored._23,
        stored._31, stored._32, stored._33,
        0.f, 0.f, 0.f,
    };
    float rotated[12]{};
    const float position[3] = {
        modelMatrix[9], modelMatrix[10], modelMatrix[11]
    };
    MultiplyAffine(modelMatrix, affineRotation, rotated);
    std::memcpy(modelMatrix, rotated, sizeof(rotated));
    modelMatrix[9] = position[0];
    modelMatrix[10] = position[1];
    modelMatrix[11] = position[2];
    return true;
}

static bool SolveSoldierArmIk(const bf6_skeleton* skeleton,
                              int armBone, int foreArmBone, int handBone,
                              const float target[12],
                              std::vector<bf6_bone_xform>& local,
                              std::vector<bf6_bone_xform>& model)
{
    if (!skeleton || armBone < 0 || foreArmBone < 0 || handBone < 0 ||
        skeleton->bones[foreArmBone].parent != armBone ||
        skeleton->bones[handBone].parent != foreArmBone)
        return false;
    const XMVECTOR shoulder = XMVectorSet(model[(size_t)armBone].m[9],
        model[(size_t)armBone].m[10], model[(size_t)armBone].m[11], 0.f);
    const XMVECTOR elbow = XMVectorSet(model[(size_t)foreArmBone].m[9],
        model[(size_t)foreArmBone].m[10], model[(size_t)foreArmBone].m[11], 0.f);
    const XMVECTOR wrist = XMVectorSet(model[(size_t)handBone].m[9],
        model[(size_t)handBone].m[10], model[(size_t)handBone].m[11], 0.f);
    const XMVECTOR requested = XMVectorSet(target[9], target[10], target[11], 0.f);
    const float upperLength = XMVectorGetX(XMVector3Length(
        XMVectorSubtract(elbow, shoulder)));
    const float lowerLength = XMVectorGetX(XMVector3Length(
        XMVectorSubtract(wrist, elbow)));
    XMVECTOR reach = XMVectorSubtract(requested, shoulder);
    float reachLength = XMVectorGetX(XMVector3Length(reach));
    if (upperLength < 1e-5f || lowerLength < 1e-5f || reachLength < 1e-5f)
        return false;
    const XMVECTOR direction = XMVectorScale(reach, 1.f / reachLength);
    const float minimumReach = std::fabs(upperLength - lowerLength) + 1e-5f;
    const float maximumReach = upperLength + lowerLength - 1e-5f;
    const float solvedReach = (std::max)(minimumReach,
        (std::min)(reachLength, maximumReach));
    const XMVECTOR solvedTarget = XMVectorAdd(shoulder,
        XMVectorScale(direction, solvedReach));
    XMVECTOR planeNormal = XMVector3Cross(
        XMVectorSubtract(elbow, shoulder),
        XMVectorSubtract(wrist, elbow));
    if (XMVectorGetX(XMVector3Length(planeNormal)) < 1e-5f)
        planeNormal = XMVector3Cross(direction,
            XMVectorSet(0.f, 1.f, 0.f, 0.f));
    if (XMVectorGetX(XMVector3Length(planeNormal)) < 1e-5f)
        planeNormal = XMVector3Cross(direction,
            XMVectorSet(1.f, 0.f, 0.f, 0.f));
    planeNormal = XMVector3Normalize(planeNormal);
    XMVECTOR bend = XMVector3Normalize(XMVector3Cross(planeNormal, direction));
    const float along = (upperLength * upperLength + solvedReach * solvedReach -
        lowerLength * lowerLength) / (2.f * solvedReach);
    const float perpendicular = std::sqrt((std::max)(0.f,
        upperLength * upperLength - along * along));
    const XMVECTOR elbowA = XMVectorAdd(shoulder,
        XMVectorAdd(XMVectorScale(direction, along),
                    XMVectorScale(bend, perpendicular)));
    const XMVECTOR elbowB = XMVectorAdd(shoulder,
        XMVectorAdd(XMVectorScale(direction, along),
                    XMVectorScale(bend, -perpendicular)));
    const float distanceA = XMVectorGetX(XMVector3LengthSq(
        XMVectorSubtract(elbowA, elbow)));
    const float distanceB = XMVectorGetX(XMVector3LengthSq(
        XMVectorSubtract(elbowB, elbow)));
    const XMVECTOR solvedElbow = distanceA <= distanceB ? elbowA : elbowB;

    if (!RotateSoldierModelBasis(model[(size_t)armBone].m,
            XMVectorSubtract(elbow, shoulder),
            XMVectorSubtract(solvedElbow, shoulder)))
        return false;
    for (int bone = armBone + 1; bone < skeleton->bone_count; ++bone)
    {
        const int parent = skeleton->bones[bone].parent;
        if (parent < 0 || parent >= bone) return false;
        MultiplyAffine(local[(size_t)bone].m, model[(size_t)parent].m,
                       model[(size_t)bone].m);
    }
    const XMVECTOR movedElbow = XMVectorSet(model[(size_t)foreArmBone].m[9],
        model[(size_t)foreArmBone].m[10], model[(size_t)foreArmBone].m[11], 0.f);
    const XMVECTOR movedWrist = XMVectorSet(model[(size_t)handBone].m[9],
        model[(size_t)handBone].m[10], model[(size_t)handBone].m[11], 0.f);
    if (!RotateSoldierModelBasis(model[(size_t)foreArmBone].m,
            XMVectorSubtract(movedWrist, movedElbow),
            XMVectorSubtract(solvedTarget, movedElbow)))
        return false;
    for (int bone = foreArmBone + 1; bone < skeleton->bone_count; ++bone)
    {
        const int parent = skeleton->bones[bone].parent;
        if (parent < 0 || parent >= bone) return false;
        MultiplyAffine(local[(size_t)bone].m, model[(size_t)parent].m,
                       model[(size_t)bone].m);
    }
    // The authored marker carries the wrist orientation as well as its
    // position.  Preserve a clamped position only when the marker is beyond
    // the physical reach of this outfit's unchanged limb lengths.
    std::memcpy(model[(size_t)handBone].m, target, sizeof(float) * 12);
    if (reachLength > maximumReach || reachLength < minimumReach)
    {
        XMFLOAT3 clamped;
        XMStoreFloat3(&clamped, solvedTarget);
        model[(size_t)handBone].m[9] = clamped.x;
        model[(size_t)handBone].m[10] = clamped.y;
        model[(size_t)handBone].m[11] = clamped.z;
    }
    for (int bone = handBone + 1; bone < skeleton->bone_count; ++bone)
    {
        const int parent = skeleton->bones[bone].parent;
        if (parent < 0 || parent >= bone) return false;
        MultiplyAffine(local[(size_t)bone].m, model[(size_t)parent].m,
                       model[(size_t)bone].m);
    }
    return true;
}

static const char* SoldierIdleClipPath(int selection, bool classLoadout)
{
    const char* diagnosticClip = std::getenv("BF6_DIAGNOSTIC_SOLDIER_CLIP");
    if (diagnosticClip && *diagnosticClip) return diagnosticClip;
    // The installed Class.Loadout.Node selects classloadout.cbd, whose
    // Collection.SoldierClass.EnumGS outcomes are the four
    // ui.loadout.idlecl.<class>.rc assets.  Each RC's repeated unit-weight
    // base entry is the matching idle[_cl]_<class>_02 clip; the idlebreak
    // clips are optional half-weight interruptions.  Keep those exact
    // controller families scoped to their respective detail and class-landing
    // surfaces instead of guessing from filename cousins (the similarly named
    // detail `_01` clips are not referenced by these controllers).
    static const char* classLoadoutClips[] = {
        "animations/glacier/assets/frontend/mainmenu/loadout/"
        "ui_frontend_standing_idle_cl_assault_02",
        "animations/glacier/assets/frontend/mainmenu/loadout/"
        "ui_frontend_standing_idle_cl_engineer_02",
        "animations/glacier/assets/frontend/mainmenu/loadout/"
        "ui_frontend_standing_idle_cl_support_02",
        "animations/glacier/assets/frontend/mainmenu/loadout/"
        "ui_frontend_standing_idle_cl_recon_02",
    };
    static const char* clips[] = {
        "animations/glacier/assets/frontend/mainmenu/loadout/"
        "ui_frontend_standing_idle_assault_02",
        "animations/glacier/assets/frontend/mainmenu/loadout/"
        "ui_frontend_standing_idle_engineer_02",
        "animations/glacier/assets/frontend/mainmenu/loadout/"
        "ui_frontend_standing_idle_support_02",
        "animations/glacier/assets/frontend/mainmenu/loadout/"
        "ui_frontend_standing_idle_recon_02",
    };
    const size_t index = (size_t)(std::max)(0, (std::min)(selection, 3));
    return classLoadout ? classLoadoutClips[index] : clips[index];
}

static constexpr const char* kSoldierAnimationRig =
    "animations/glacier/global/rigging/soldier_3p.rig";
static constexpr const char* kSoldierRenderSkeleton =
    "common/characters/_soldier/ske_soldier_3p";

struct SoldierAnimationSamples {
    std::vector<bf6_anim_binding> bindings;
    std::vector<float> channels;
    bf6_anim_binding_stats stats{};
    int frame_count = 0;
    int channel_count = 0;
    float fps = 0.f;
};

static bool LoadSoldierAnimationSamplesPath(const char* clipPath,
                                            SoldierAnimationSamples& out)
{
    const int count = bf6_anim_bindings(
        g_bf6, clipPath, kSoldierAnimationRig, kSoldierRenderSkeleton,
        nullptr, 0, &out.stats);
    if (count <= 0) return false;
    out.bindings.resize((size_t)count);
    if (bf6_anim_bindings(
            g_bf6, clipPath, kSoldierAnimationRig, kSoldierRenderSkeleton,
            out.bindings.data(), count, &out.stats) != count)
        return false;
    bf6_anim_clip* clip = bf6_anim_clip_open(g_bf6, clipPath);
    if (!clip || clip->key_time_count <= 0) {
        if (clip) bf6_free(g_bf6, clip);
        return false;
    }
    out.frame_count = clip->key_time_count;
    out.channel_count = clip->channel_count;
    // All four selected ClipPlayer owners author Fps=60 in the current
    // install. The reloc payload itself stores sample ordinals, not rate.
    out.fps = 60.f;
    out.channels.resize((size_t)out.frame_count * out.channel_count * 4);
    bool valid = true;
    for (int frame = 0; frame < out.frame_count; ++frame) {
        float* destination = out.channels.data() +
            (size_t)frame * out.channel_count * 4;
        if (!bf6_anim_clip_sample(g_bf6, clip, frame, destination, nullptr)) {
            valid = false;
            break;
        }
    }
    bf6_free(g_bf6, clip);
    if (!valid) out = SoldierAnimationSamples{};
    return valid;
}

static bool LoadSoldierAnimationSamples(int selection, bool classLoadout,
                                        SoldierAnimationSamples& out)
{
    return LoadSoldierAnimationSamplesPath(
        SoldierIdleClipPath(selection, classLoadout), out);
}

enum class SoldierHposeMask
{
    All,
    Weapon,
    LeftArm,
    RightArm,
};

static bool SoldierHposeChannel(const char* dofName,
                                SoldierHposeMask mask)
{
    if (!dofName || !*dofName) return false;
    const std::string name(dofName);
    const size_t suffix = name.size() >= 2 && name[name.size() - 2] == '.'
        ? name.size() - 2 : name.size();
    const std::string bone = name.substr(0, suffix);
    const bool weapon = bone.rfind("Wep", 0) == 0;
    const bool left = bone.rfind("LeftShoulder", 0) == 0 ||
        bone.rfind("LeftArm", 0) == 0 ||
        bone.rfind("LeftForeArm", 0) == 0 ||
        bone.rfind("LeftHand", 0) == 0;
    const bool right = bone.rfind("RightShoulder", 0) == 0 ||
        bone.rfind("RightArm", 0) == 0 ||
        bone.rfind("RightForeArm", 0) == 0 ||
        bone.rfind("RightHand", 0) == 0;
    switch (mask)
    {
    case SoldierHposeMask::Weapon: return weapon;
    case SoldierHposeMask::LeftArm: return left;
    case SoldierHposeMask::RightArm: return right;
    default: return weapon || left || right;
    }
}

static bool ResolveSoldierWeaponHpose(const std::string& weapon,
                                      std::string& out)
{
    out.clear();
    const size_t slash = weapon.find_last_of("/\\");
    const std::string bare = slash == std::string::npos
        ? weapon : weapon.substr(slash + 1);
    if (bare.empty()) return false;
    std::string normalized;
    for (unsigned char c : bare)
        if (std::isalnum(c)) normalized.push_back((char)std::tolower(c));
    if (normalized.empty()) return false;
    std::vector<std::string> leaves{"hposes_" + normalized};
    // The installed GripPose chooser names this rifle m2010 even though the
    // gameplay equipment/armory key is m2010esr.  Keep the observed alias
    // bounded to that exact current-install identity; broad suffix stripping
    // would silently bind unrelated future weapons.
    if (normalized == "m2010esr") leaves.push_back("hposes_m2010");
    for (const std::string& leaf : leaves)
    {
        const int count = bf6_list_ebx(g_bf6, leaf.c_str(), nullptr, 0);
        if (count <= 0) continue;
        std::vector<bf6_asset> rows((size_t)count);
        const int got = bf6_list_ebx(g_bf6, leaf.c_str(), rows.data(), count);
        for (int row = 0; row < got; ++row)
        {
            if (!rows[(size_t)row].name) continue;
            std::string path = rows[(size_t)row].name;
            std::string lower = path;
            std::transform(lower.begin(), lower.end(), lower.begin(),
                [](unsigned char c) { return (char)std::tolower(c); });
            const size_t at = lower.find_last_of("/\\");
            const std::string candidate = at == std::string::npos
                ? lower : lower.substr(at + 1);
            if (candidate == leaf &&
                lower.find("/assets/3p/weapons/") != std::string::npos)
            {
                out = path;
                return true;
            }
        }
    }
    return false;
}

static bool ApplySoldierWeaponHpose(const std::string& weapon,
                                    SoldierAnimationSamples& base,
                                    int preferredPoseIndex = 1,
                                    SoldierHposeMask mask =
                                        SoldierHposeMask::All)
{
    std::string path;
    SoldierAnimationSamples pose;
    if (!ResolveSoldierWeaponHpose(weapon, path) ||
        !LoadSoldierAnimationSamplesPath(path.c_str(), pose) ||
        pose.frame_count <= 1 || pose.channels.empty())
        return false;
    int poseIndex = preferredPoseIndex;
    if (const char* diagnostic =
            std::getenv("BF6_DIAGNOSTIC_HPOSE_INDEX"))
        poseIndex = std::atoi(diagnostic);
    poseIndex = (std::max)(0, (std::min)(poseIndex,
                                        pose.frame_count - 1));
    std::map<std::pair<std::string, int>, const bf6_anim_binding*> poseByDof;
    for (const bf6_anim_binding& binding : pose.bindings)
        poseByDof.emplace(std::make_pair(std::string(binding.dof_name),
                                         binding.component), &binding);
    int overlaid = 0;
    for (const bf6_anim_binding& destinationBinding : base.bindings)
    {
        if (!SoldierHposeChannel(destinationBinding.dof_name, mask) ||
            destinationBinding.component == BF6_ANIM_DOF_SCALAR)
            continue;
        const auto source = poseByDof.find(std::make_pair(
            std::string(destinationBinding.dof_name),
            destinationBinding.component));
        if (source == poseByDof.end()) continue;
        const bf6_anim_binding& sourceBinding = *source->second;
        if (destinationBinding.channel < 0 ||
            destinationBinding.channel >= base.channel_count ||
            sourceBinding.channel < 0 ||
            sourceBinding.channel >= pose.channel_count)
            continue;
        const float* value = pose.channels.data() +
            ((size_t)poseIndex * pose.channel_count +
             (size_t)sourceBinding.channel) * 4;
        for (int frame = 0; frame < base.frame_count; ++frame)
            std::memcpy(base.channels.data() +
                ((size_t)frame * base.channel_count +
                 (size_t)destinationBinding.channel) * 4,
                value, sizeof(float) * 4);
        ++overlaid;
    }
    std::fprintf(stderr,
        "soldier H-pose overlay: weapon=%s path=%s index=%d mask=%d "
        "channels=%d\n",
        weapon.c_str(), path.c_str(), poseIndex, (int)mask, overlaid);
    return overlaid > 0;
}

static bool BuildSoldierAnimationSkinFrames(
    const SoldierAnimationSamples& source, const char* renderbonesPath,
    int expectedBoneCount, std::vector<bf6_bone_xform>& frames,
    int& boneCount, int& rigBoneCount,
    std::vector<bf6_bone_xform>* weaponAlignFrames = nullptr,
    std::vector<bf6_bone_xform>* rigSkinFrames = nullptr)
{
    bf6_skeleton* skeleton = bf6_skeleton_compose(
        g_bf6, kSoldierRenderSkeleton,
        renderbonesPath && *renderbonesPath ? renderbonesPath : nullptr);
    if (!skeleton || (expectedBoneCount > 0 &&
        skeleton->bone_count != expectedBoneCount)) {
        if (skeleton) bf6_free(g_bf6, skeleton);
        return false;
    }
    boneCount = skeleton->bone_count;
    rigBoneCount = skeleton->rig_bone_count;
    int weaponAlignBone = -1;
    int weaponRootBone = -1, weapon2AlignBone = -1, weapon2RootBone = -1;
    int leftArmBone = -1, leftForeArmBone = -1;
    int rightArmBone = -1, rightForeArmBone = -1;
    int leftHandBone = -1, rightHandBone = -1;
    int weaponLeftIkBone = -1, weaponRightIkBone = -1;
    if (weaponAlignFrames)
    {
        for (int bone = 0; bone < skeleton->rig_bone_count; ++bone)
            if (skeleton->bones[bone].name)
            {
                const char* name = skeleton->bones[bone].name;
                if (std::strcmp(name, "Wep_Align") == 0) weaponAlignBone = bone;
                else if (std::strcmp(name, "Wep_Root") == 0) weaponRootBone = bone;
                else if (std::strcmp(name, "Wep2_Align") == 0) weapon2AlignBone = bone;
                else if (std::strcmp(name, "Wep2_Root") == 0) weapon2RootBone = bone;
                else if (std::strcmp(name, "LeftArm") == 0) leftArmBone = bone;
                else if (std::strcmp(name, "LeftForeArm") == 0) leftForeArmBone = bone;
                else if (std::strcmp(name, "LeftHand") == 0) leftHandBone = bone;
                else if (std::strcmp(name, "RightArm") == 0) rightArmBone = bone;
                else if (std::strcmp(name, "RightForeArm") == 0) rightForeArmBone = bone;
                else if (std::strcmp(name, "RightHand") == 0) rightHandBone = bone;
                else if (std::strcmp(name, "Wep_IK_LeftHand") == 0) weaponLeftIkBone = bone;
                else if (std::strcmp(name, "Wep_IK_RightHand") == 0) weaponRightIkBone = bone;
            }
        if (weaponAlignBone < 0) {
            bf6_free(g_bf6, skeleton);
            return false;
        }
        weaponAlignFrames->resize((size_t)source.frame_count);
    }
    frames.resize((size_t)source.frame_count * boneCount);
    if (rigSkinFrames)
        rigSkinFrames->resize((size_t)source.frame_count *
                              (size_t)rigBoneCount);
    std::vector<bf6_bone_xform> local((size_t)boneCount);
    std::vector<bf6_bone_xform> model((size_t)boneCount);
    bool valid = true;
    for (int frame = 0; frame < source.frame_count && valid; ++frame)
    {
        for (int bone = 0; bone < boneCount; ++bone)
            std::memcpy(local[(size_t)bone].m, skeleton->bones[bone].local,
                        sizeof(float) * 12);
        const float* channels = source.channels.data() +
            (size_t)frame * source.channel_count * 4;
        int applied = 0;
        for (const bf6_anim_binding& binding : source.bindings)
        {
            if (binding.bone < 0 || binding.bone >= boneCount) continue;
            const float* value = channels + (size_t)binding.channel * 4;
            float* destination = local[(size_t)binding.bone].m;
            if (binding.component == BF6_ANIM_DOF_QUATERNION)
            {
                const XMMATRIX rotation = XMMatrixRotationQuaternion(
                    XMQuaternionNormalize(XMVectorSet(
                        value[0], value[1], value[2], value[3])));
                XMFLOAT4X4 stored;
                XMStoreFloat4x4(&stored, rotation);
                for (int row = 0; row < 3; ++row)
                    for (int column = 0; column < 3; ++column)
                        destination[row * 3 + column] =
                            (&stored._11)[row * 4 + column];
                ++applied;
            }
            else if (binding.component == BF6_ANIM_DOF_VECTOR3)
            {
                destination[9] = value[0];
                destination[10] = value[1];
                destination[11] = value[2];
                ++applied;
            }
        }
        valid = applied == source.stats.quaternion_bones +
            source.stats.vector_bones;
        for (int bone = 0; bone < boneCount && valid; ++bone)
        {
            const int parent = skeleton->bones[bone].parent;
            if (parent < 0)
                std::memcpy(model[(size_t)bone].m, local[(size_t)bone].m,
                            sizeof(float) * 12);
            else if (parent < bone)
                MultiplyAffine(local[(size_t)bone].m,
                               model[(size_t)parent].m,
                               model[(size_t)bone].m);
            else valid = false;
        }
        if (valid && weaponAlignFrames)
        {
            // Glacier's Wep_Align branch carries weapon-space hand targets;
            // the runtime IK pass moves that branch so Wep_IK_RightHand lands
            // on the animated RightHand.  A raw skeleton composition omits
            // that pass and leaves a rifle above the actor.  Reconstruct the
            // same rigid constraint: ikRelative * weaponAlign =
            // rightHandModel.
            // The raw path remains an explicit diagnostic control.
            float solvedWeaponAlign[12]{};
            float inverseRawWeaponAlign[12]{};
            float rightIkRelative[12]{};
            float inverseRightIkRelative[12]{};
            const bool authoredArmTargets = std::getenv(
                "BF6_DIAGNOSTIC_AUTHORED_HPOSE_WRITERS") != nullptr;
            const bool haveInverseRawWeaponAlign = InvertAffine(
                model[(size_t)weaponAlignBone].m, inverseRawWeaponAlign);
            const bool solveWeaponAlign =
                !std::getenv("BF6_DIAGNOSTIC_RAW_WEAPON_ALIGN") &&
                !authoredArmTargets && rightHandBone >= 0 &&
                weaponRightIkBone >= 0 && haveInverseRawWeaponAlign;
            bool haveRightIkRelative = false;
            if (haveInverseRawWeaponAlign && weaponRightIkBone >= 0)
            {
                // IK targets are not guaranteed to be direct children of
                // Wep_Align.  The detail base happens to make the old
                // local-only shortcut look plausible, but the authored
                // step-up clip inserts Wep_Root in the chain and visibly
                // launches the rifle away from the hands.  Remove the raw
                // Wep_Align model transform to obtain the complete descendant
                // chain relative to that anchor.
                MultiplyAffine(model[(size_t)weaponRightIkBone].m,
                               inverseRawWeaponAlign, rightIkRelative);
                haveRightIkRelative = InvertAffine(
                    rightIkRelative, inverseRightIkRelative);
            }
            if (solveWeaponAlign && haveRightIkRelative)
                MultiplyAffine(inverseRightIkRelative,
                               model[(size_t)rightHandBone].m,
                               solvedWeaponAlign);
            else
                std::memcpy(solvedWeaponAlign,
                            model[(size_t)weaponAlignBone].m,
                            sizeof(solvedWeaponAlign));
            float leftResidualBefore = -1.f;
            float leftResidualAfter = -1.f;
            bool solvedLeftArm = false, solvedRightArm = false;
            if (haveInverseRawWeaponAlign &&
                leftHandBone >= 0 && weaponLeftIkBone >= 0)
            {
                float leftIkRelative[12]{};
                float solvedLeftIk[12]{};
                MultiplyAffine(model[(size_t)weaponLeftIkBone].m,
                               inverseRawWeaponAlign, leftIkRelative);
                MultiplyAffine(leftIkRelative,
                               solvedWeaponAlign, solvedLeftIk);
                leftResidualBefore = SoldierPointDistance(
                    solvedLeftIk, model[(size_t)leftHandBone].m);
                if (!std::getenv("BF6_DIAGNOSTIC_RAW_LEFT_HAND_IK"))
                    solvedLeftArm = SolveSoldierArmIk(skeleton,
                        leftArmBone, leftForeArmBone, leftHandBone,
                        solvedLeftIk, local, model);
                leftResidualAfter = SoldierPointDistance(
                    solvedLeftIk, model[(size_t)leftHandBone].m);
            }
            if (authoredArmTargets && haveRightIkRelative &&
                rightArmBone >= 0 && rightForeArmBone >= 0 &&
                rightHandBone >= 0)
            {
                float solvedRightIk[12]{};
                MultiplyAffine(rightIkRelative,
                               solvedWeaponAlign, solvedRightIk);
                solvedRightArm = SolveSoldierArmIk(skeleton,
                    rightArmBone, rightForeArmBone, rightHandBone,
                    solvedRightIk, local, model);
            }
            std::memcpy((*weaponAlignFrames)[(size_t)frame].m,
                        solvedWeaponAlign, sizeof(solvedWeaponAlign));
            if (frame == 0)
            {
                auto printBone = [&](const char* label, int bone) {
                    if (bone < 0) return;
                    const float* value = model[(size_t)bone].m;
                    std::fprintf(stderr, "soldier animation anchor %s=(%.6f %.6f %.6f)\n",
                        label, value[9], value[10], value[11]);
                };
                printBone("Wep_Root", weaponRootBone);
                printBone("Wep_Align", weaponAlignBone);
                printBone("Wep2_Root", weapon2RootBone);
                printBone("Wep2_Align", weapon2AlignBone);
                printBone("LeftHand", leftHandBone);
                printBone("RightHand", rightHandBone);
                printBone("Wep_IK_LeftHand", weaponLeftIkBone);
                printBone("Wep_IK_RightHand", weaponRightIkBone);
                if (leftResidualBefore >= 0.f)
                    std::fprintf(stderr,
                        "soldier weapon IK solve: align=(%.6f %.6f %.6f) "
                        "left-residual=%.6f -> %.6f solved=%d\n",
                        solvedWeaponAlign[9], solvedWeaponAlign[10],
                        solvedWeaponAlign[11], leftResidualBefore,
                        leftResidualAfter, solvedLeftArm ? 1 : 0);
                if (authoredArmTargets)
                    std::fprintf(stderr,
                        "soldier authored right-arm IK solved=%d\n",
                        solvedRightArm ? 1 : 0);
            }
        }
        bf6_bone_xform* skin = frames.data() + (size_t)frame * boneCount;
        for (int bone = 0; bone < boneCount && valid; ++bone)
            MultiplyAffine(skeleton->bones[bone].inverse,
                           model[(size_t)bone].m, skin[bone].m);
        if (valid && rigSkinFrames)
            std::memcpy(rigSkinFrames->data() +
                            (size_t)frame * rigBoneCount,
                        skin, (size_t)rigBoneCount *
                            sizeof(bf6_bone_xform));
    }
    bf6_free(g_bf6, skeleton);
    if (!valid) {
        frames.clear();
        if (weaponAlignFrames) weaponAlignFrames->clear();
        if (rigSkinFrames) rigSkinFrames->clear();
    }
    return valid;
}

static bool BindRigidPartToSoldierWeapon(
    CpuPart& part, const std::vector<bf6_bone_xform>& weaponAlignFrames,
    float fps)
{
    if (part.sections.empty() || weaponAlignFrames.empty() || fps <= 0.f)
        return false;
    const float* matrix = weaponAlignFrames.front().m;
    for (int axis = 0; axis < 3; ++axis) {
        part.lo[axis] = FLT_MAX;
        part.hi[axis] = -FLT_MAX;
    }
    for (CpuSection& section : part.sections)
    {
        section.bind_verts = section.verts;
        for (size_t vertex = 0; vertex < section.verts.size(); ++vertex)
        {
            const Vtx& source = section.bind_verts[vertex];
            Vtx& out = section.verts[vertex];
            for (int column = 0; column < 3; ++column)
            {
                out.p[column] = source.p[0] * matrix[column] +
                    source.p[1] * matrix[3 + column] +
                    source.p[2] * matrix[6 + column] + matrix[9 + column];
                out.n[column] = source.n[0] * matrix[column] +
                    source.n[1] * matrix[3 + column] +
                    source.n[2] * matrix[6 + column];
                out.tangent[column] =
                    source.tangent[0] * matrix[column] +
                    source.tangent[1] * matrix[3 + column] +
                    source.tangent[2] * matrix[6 + column];
                part.lo[column] = (std::min)(part.lo[column], out.p[column]);
                part.hi[column] = (std::max)(part.hi[column], out.p[column]);
            }
        }
    }
    part.animation_skin_frames = weaponAlignFrames;
    part.animation_frame_count = (int)weaponAlignFrames.size();
    part.animation_bone_count = 1;
    part.animation_rig_bone_count = 0;
    part.animation_fps = fps;
    part.animation_rigid = true;
    part.name = "soldier-weapon:" + part.name;
    return true;
}

static bool BuildIntegratedWeaponSkinFrames(
    const std::vector<bf6_bone_xform>& staticWeaponSkin,
    const std::vector<bf6_bone_xform>& soldierRigSkinFrames,
    int frameCount, int soldierRigBoneCount,
    std::vector<bf6_bone_xform>& out)
{
    if (staticWeaponSkin.empty() || frameCount <= 0 ||
        soldierRigBoneCount <= 0 ||
        soldierRigSkinFrames.size() <
            (size_t)frameCount * (size_t)soldierRigBoneCount)
        return false;
    const int weaponBoneCount = bf6_weapon_bones(g_bf6, nullptr, 0);
    if (weaponBoneCount <= 0 ||
        weaponBoneCount != (int)staticWeaponSkin.size())
        return false;
    std::vector<bf6_weapon_bone_info> weaponBones(
        (size_t)weaponBoneCount);
    if (bf6_weapon_bones(g_bf6, weaponBones.data(), weaponBoneCount) !=
            weaponBoneCount)
        return false;
    bf6_skeleton* soldier = bf6_skeleton_compose(
        g_bf6, kSoldierRenderSkeleton, nullptr);
    if (!soldier || soldier->rig_bone_count != soldierRigBoneCount)
    {
        if (soldier) bf6_free(g_bf6, soldier);
        return false;
    }
    std::vector<int> weaponToSoldier((size_t)weaponBoneCount, -1);
    int mapped = 0;
    for (int weaponBone = 0; weaponBone < weaponBoneCount; ++weaponBone)
        for (int soldierBone = 0; soldierBone < soldier->rig_bone_count;
             ++soldierBone)
            if (soldier->bones[soldierBone].name &&
                std::strcmp(weaponBones[(size_t)weaponBone].name,
                            soldier->bones[soldierBone].name) == 0)
            {
                weaponToSoldier[(size_t)weaponBone] = soldierBone;
                ++mapped;
                break;
            }
    bf6_free(g_bf6, soldier);
    // The shared weapon skeleton is a strict named subset of the 3P soldier
    // rig. Fail closed if an update changes that contract; partially mapping
    // the palette detaches exactly the moving pieces this path exists to fix.
    if (mapped != weaponBoneCount) return false;
    out.resize((size_t)frameCount * (size_t)weaponBoneCount);
    for (int frame = 0; frame < frameCount; ++frame)
    {
        const bf6_bone_xform* soldierSkin = soldierRigSkinFrames.data() +
            (size_t)frame * soldierRigBoneCount;
        bf6_bone_xform* weaponSkin = out.data() +
            (size_t)frame * weaponBoneCount;
        for (int weaponBone = 0; weaponBone < weaponBoneCount; ++weaponBone)
            MultiplyAffine(staticWeaponSkin[(size_t)weaponBone].m,
                soldierSkin[weaponToSoldier[(size_t)weaponBone]].m,
                weaponSkin[weaponBone].m);
    }
    std::fprintf(stderr,
        "soldier weapon integrated palette: bones=%d/%d frames=%d\n",
        mapped, weaponBoneCount, frameCount);
    return true;
}

static bool SkinWeaponPartAtFrame(CpuPart& part,
                                  const bf6_bone_xform* skin,
                                  int boneCount)
{
    if (!skin || boneCount <= 0 || part.sections.empty()) return false;
    for (int axis = 0; axis < 3; ++axis)
    {
        part.lo[axis] = FLT_MAX;
        part.hi[axis] = -FLT_MAX;
    }
    for (CpuSection& section : part.sections)
    {
        if (section.bind_verts.empty() || section.skin_influences <= 0 ||
            section.skin_bones.size() != section.skin_weights.size() ||
            section.skin_bones.size() != section.bind_verts.size() *
                (size_t)section.skin_influences)
            return false;
        section.verts.resize(section.bind_verts.size());
        for (size_t vertex = 0; vertex < section.bind_verts.size(); ++vertex)
        {
            const Vtx& source = section.bind_verts[vertex];
            Vtx& destination = section.verts[vertex];
            destination = source;
            destination.p[0] = destination.p[1] = destination.p[2] = 0.f;
            destination.n[0] = destination.n[1] = destination.n[2] = 0.f;
            destination.tangent[0] = destination.tangent[1] =
                destination.tangent[2] = 0.f;
            float accepted = 0.f;
            for (int lane = 0; lane < section.skin_influences; ++lane)
            {
                const size_t influence = vertex *
                    (size_t)section.skin_influences + (size_t)lane;
                const float weight = section.skin_weights[influence];
                const int bone = (int)section.skin_bones[influence];
                if (weight <= 0.f || bone < 0 || bone >= boneCount) continue;
                const float* matrix = skin[bone].m;
                for (int column = 0; column < 3; ++column)
                {
                    destination.p[column] += weight *
                        (source.p[0] * matrix[column] +
                         source.p[1] * matrix[3 + column] +
                         source.p[2] * matrix[6 + column] +
                         matrix[9 + column]);
                    destination.n[column] += weight *
                        (source.n[0] * matrix[column] +
                         source.n[1] * matrix[3 + column] +
                         source.n[2] * matrix[6 + column]);
                    destination.tangent[column] += weight *
                        (source.tangent[0] * matrix[column] +
                         source.tangent[1] * matrix[3 + column] +
                         source.tangent[2] * matrix[6 + column]);
                }
                accepted += weight;
            }
            if (accepted <= 1e-8f) return false;
            const float reciprocal = 1.f / accepted;
            for (int column = 0; column < 3; ++column)
            {
                destination.p[column] *= reciprocal;
                destination.n[column] *= reciprocal;
                destination.tangent[column] *= reciprocal;
            }
            if (part.animation_post_transform_active)
            {
                const float* matrix = part.animation_post_transform;
                const float p[3] = { destination.p[0], destination.p[1],
                                     destination.p[2] };
                const float n[3] = { destination.n[0], destination.n[1],
                                     destination.n[2] };
                const float t[3] = { destination.tangent[0],
                    destination.tangent[1], destination.tangent[2] };
                for (int column = 0; column < 3; ++column)
                {
                    destination.p[column] = p[0] * matrix[column] +
                        p[1] * matrix[3 + column] +
                        p[2] * matrix[6 + column] + matrix[9 + column];
                    destination.n[column] = n[0] * matrix[column] +
                        n[1] * matrix[3 + column] +
                        n[2] * matrix[6 + column];
                    destination.tangent[column] = t[0] * matrix[column] +
                        t[1] * matrix[3 + column] +
                        t[2] * matrix[6 + column];
                }
            }
            for (int axis = 0; axis < 3; ++axis)
            {
                part.lo[axis] = (std::min)(part.lo[axis],
                                           destination.p[axis]);
                part.hi[axis] = (std::max)(part.hi[axis],
                                           destination.p[axis]);
            }
        }
    }
    return true;
}

static bool BindSkinnedPartToSoldierWeapon(
    CpuPart& part, const std::vector<bf6_bone_xform>& weaponSkinFrames,
    int frameCount, int boneCount, float fps)
{
    if (frameCount <= 0 || boneCount <= 0 || fps <= 0.f ||
        weaponSkinFrames.size() < (size_t)frameCount * (size_t)boneCount ||
        !SkinWeaponPartAtFrame(part, weaponSkinFrames.data(), boneCount))
        return false;
    part.animation_skin_frames = weaponSkinFrames;
    part.animation_frame_count = frameCount;
    part.animation_bone_count = boneCount;
    part.animation_rig_bone_count = 0;
    part.animation_fps = fps;
    part.animation_rigid = false;
    part.name = "soldier-weapon-skinned:" + part.name;
    return true;
}

static bool BuildSoldierIdleSkin(int selection, bool classLoadout,
                                 const char* renderbonesPath,
                                 int expectedBoneCount,
                                 std::vector<bf6_bone_xform>& skin,
                                 int& boundChannels, int& boneChannels,
                                 int& rigBoneCount)
{
    const char* poseMode = std::getenv("BF6_DIAGNOSTIC_SOLDIER_POSE");
    const bool deltaAfterBind = poseMode && std::strcmp(poseMode, "after") == 0;
    const bool deltaBeforeBind = poseMode && std::strcmp(poseMode, "before") == 0;
    const bool deltaRestFirst = poseMode &&
        std::strcmp(poseMode, "rest-first") == 0;
    const bool deltaRestLast = poseMode &&
        std::strcmp(poseMode, "rest-last") == 0;
    const bool rotationRestFirst = poseMode &&
        std::strcmp(poseMode, "rotation-rest-first") == 0;
    const bool rotationRestLast = poseMode &&
        std::strcmp(poseMode, "rotation-rest-last") == 0;
    const bool rotationAfterBind = poseMode &&
        std::strcmp(poseMode, "rotation-after") == 0;
    const bool rotationBeforeBind = poseMode &&
        std::strcmp(poseMode, "rotation-before") == 0;
    // VBR animated scalars are zero-centred residual-domain coefficients, but
    // the reconstructed quaternion/vector channels are absolute local DOFs.
    // With that decoder correction the direct local path is the shipped
    // standing pose, so it is now the production default. Environment modes
    // remain available only as explicit negative/diagnostic controls.
    const bool absoluteLocal = !poseMode ||
        std::strcmp(poseMode, "absolute") == 0;
    const bool absoluteLocalRotation = poseMode &&
        std::strcmp(poseMode, "absolute-rotation") == 0;
    const bool absoluteChildren = poseMode &&
        std::strcmp(poseMode, "absolute-children") == 0;
    const bool modelQuaternion = poseMode && std::strcmp(poseMode, "model") == 0;
    const bool modelRotationBindTranslation = poseMode &&
        std::strcmp(poseMode, "model-rotation") == 0;
    const bool modelDeltaAfterBind = poseMode &&
        std::strcmp(poseMode, "model-delta-after") == 0;
    const bool modelDeltaBeforeBind = poseMode &&
        std::strcmp(poseMode, "model-delta-before") == 0;
    const bool modelSpaceRotation = modelQuaternion ||
        modelRotationBindTranslation || modelDeltaAfterBind ||
        modelDeltaBeforeBind;
    if (!deltaAfterBind && !deltaBeforeBind && !deltaRestFirst &&
        !deltaRestLast && !rotationRestFirst && !rotationRestLast &&
        !rotationAfterBind &&
        !rotationBeforeBind && !absoluteLocal && !absoluteLocalRotation &&
        !absoluteChildren &&
        !modelSpaceRotation)
        return false;
    /* PresentationSoldier imports this Glacier rig directly.  The older
     * Kingston rig happens to resolve the same 505 symbolic keys, but its
     * defaults and storage layout belong to a different actor. */
    const char* kRig = kSoldierAnimationRig;
    const char* kSkeleton = kSoldierRenderSkeleton;
    const char* clipPath = SoldierIdleClipPath(selection, classLoadout);
    bf6_anim_binding_stats bindingStats{};
    const int count = bf6_anim_bindings(g_bf6, clipPath, kRig, kSkeleton,
                                         nullptr, 0, &bindingStats);
    if (count <= 0) return false;
    std::vector<bf6_anim_binding> bindings((size_t)count);
    if (bf6_anim_bindings(g_bf6, clipPath, kRig, kSkeleton, bindings.data(),
                          count, &bindingStats) != count) return false;
    bf6_anim_clip* clip = bf6_anim_clip_open(g_bf6, clipPath);
    /* Character renderbones are mesh-specific.  Build the same composed
     * skeleton each mesh actually indexes; a single plain 291-bone soldier
     * rig leaves flagged vertex influences unresolved as soon as it moves. */
    bf6_skeleton* skeleton = bf6_skeleton_compose(
        g_bf6, kSkeleton, renderbonesPath && *renderbonesPath
            ? renderbonesPath : nullptr);
    if (!clip || !skeleton || clip->channel_count != count ||
        (expectedBoneCount > 0 && skeleton->bone_count != expectedBoneCount)) {
        if (clip) bf6_free(g_bf6, clip);
        if (skeleton) bf6_free(g_bf6, skeleton);
        return false;
    }
    std::vector<float> channels((size_t)clip->channel_count * 4);
    /* Frame zero is an authored sample, not an invented stance. The runtime
     * animation clock can advance this same path once GPU skinning is live. */
    if (!bf6_anim_clip_sample(g_bf6, clip, 0, channels.data(), nullptr)) {
        bf6_free(g_bf6, clip); bf6_free(g_bf6, skeleton); return false;
    }
    std::vector<bf6_bone_xform> local((size_t)skeleton->bone_count);
    std::vector<bf6_bone_xform> model((size_t)skeleton->bone_count);
    std::vector<XMFLOAT4X4> sampledModelRotation((size_t)skeleton->bone_count);
    std::vector<unsigned char> hasModelRotation((size_t)skeleton->bone_count, 0);
    for (int bone = 0; bone < skeleton->bone_count; ++bone)
        std::memcpy(local[(size_t)bone].m, skeleton->bones[bone].local,
                    sizeof(local[(size_t)bone].m));
    int applied = 0;
    int skippedRootChannels = 0;
    bool valid = true;
    for (const bf6_anim_binding& binding : bindings)
    {
        if (binding.bone < 0 || binding.bone >= skeleton->bone_count) continue;
        // A reloc clip's Hips transform is consumed by Frostbite's trajectory
        // and procedural-rig stages before it reaches the render skeleton.
        // Keep a diagnostic that freezes only that root while allowing the
        // directly named child DOFs to pose. This is intentionally not a
        // production shortcut until its silhouette and bone-space invariants
        // agree independently.
        if (absoluteChildren && skeleton->bones[binding.bone].name &&
            std::strcmp(skeleton->bones[binding.bone].name, "Hips") == 0 &&
            (binding.component == BF6_ANIM_DOF_QUATERNION ||
             binding.component == BF6_ANIM_DOF_VECTOR3))
        {
            ++skippedRootChannels;
            continue;
        }
        const float* value = channels.data() + (size_t)binding.channel * 4;
        float* destination = local[(size_t)binding.bone].m;
        if (binding.component == BF6_ANIM_DOF_QUATERNION)
        {
            // Frostbite stores transform axes as DirectX row-vector rows.
            // Reconstructing that matrix directly makes the RigAsset lanes
            // match the SkeletonAsset local basis unchanged on 137/145 bones;
            // the older column-matrix extractor introduced a conjugate and
            // made signs=7 appear correct. Keep the authored (x,y,z,w) here.
            const XMVECTOR sampledQuaternion = XMQuaternionNormalize(XMVectorSet(
                value[0], value[1], value[2], value[3]));
            const XMMATRIX animation = XMMatrixRotationQuaternion(sampledQuaternion);
            if (modelSpaceRotation)
            {
                XMMATRIX modelAnimation = animation;
                if (modelDeltaAfterBind || modelDeltaBeforeBind)
                {
                    if (!binding.has_default_value) { valid = false; break; }
                    const float* authoredModel =
                        skeleton->bones[binding.bone].model;
                    const XMMATRIX bindModel(
                        authoredModel[0], authoredModel[1], authoredModel[2], 0.f,
                        authoredModel[3], authoredModel[4], authoredModel[5], 0.f,
                        authoredModel[6], authoredModel[7], authoredModel[8], 0.f,
                        0.f, 0.f, 0.f, 1.f);
                    const XMMATRIX rest = XMMatrixRotationQuaternion(XMVectorSet(
                        binding.default_value[0], binding.default_value[1],
                        binding.default_value[2], binding.default_value[3]));
                    const XMMATRIX inverseRest = XMMatrixInverse(nullptr, rest);
                    modelAnimation = modelDeltaAfterBind
                        ? XMMatrixMultiply(
                            XMMatrixMultiply(bindModel, inverseRest), animation)
                        : XMMatrixMultiply(
                            XMMatrixMultiply(animation, inverseRest), bindModel);
                }
                XMStoreFloat4x4(&sampledModelRotation[(size_t)binding.bone],
                                modelAnimation);
                hasModelRotation[(size_t)binding.bone] = 1;
                ++applied;
                continue;
            }
            XMMATRIX calibrated = animation;
            if (!absoluteLocal && !absoluteLocalRotation && !absoluteChildren) {
                if (!binding.has_default_value) { valid = false; break; }
                const XMMATRIX bind(
                    destination[0], destination[1], destination[2], 0.f,
                    destination[3], destination[4], destination[5], 0.f,
                    destination[6], destination[7], destination[8], 0.f,
                    0.f, 0.f, 0.f, 1.f);
                const XMMATRIX rest = XMMatrixRotationQuaternion(XMVectorSet(
                    binding.default_value[0], binding.default_value[1],
                    binding.default_value[2], binding.default_value[3]));
                const XMMATRIX inverseRest = XMMatrixInverse(nullptr, rest);
                // Retain the two old diagnostics beside the direct local-pose
                // interpretation supplied by the independent reader.
                if (deltaAfterBind || rotationAfterBind)
                    calibrated = XMMatrixMultiply(
                        XMMatrixMultiply(bind, inverseRest), animation);
                else if (deltaBeforeBind || rotationBeforeBind)
                    calibrated = XMMatrixMultiply(
                        XMMatrixMultiply(animation, inverseRest), bind);
                else if (deltaRestFirst || rotationRestFirst)
                    calibrated = XMMatrixMultiply(
                        XMMatrixMultiply(inverseRest, animation), bind);
                else if (deltaRestLast || rotationRestLast)
                    calibrated = XMMatrixMultiply(
                        XMMatrixMultiply(bind, animation), inverseRest);
            }
            XMFLOAT4X4 rotation;
            XMStoreFloat4x4(&rotation, calibrated);
            for (int row = 0; row < 3; ++row)
                for (int column = 0; column < 3; ++column)
                    destination[row * 3 + column] = (&rotation._11)[row * 4 + column];
            ++applied;
        }
        else if (binding.component == BF6_ANIM_DOF_VECTOR3)
        {
            if (rotationAfterBind || rotationBeforeBind ||
                rotationRestFirst || rotationRestLast ||
                modelRotationBindTranslation ||
                absoluteLocalRotation) continue;
            if (absoluteLocal || absoluteChildren || modelQuaternion) {
                destination[9] = value[0];
                destination[10] = value[1];
                destination[11] = value[2];
            } else {
                if (!binding.has_default_value) { valid = false; break; }
                destination[9] += value[0] - binding.default_value[0];
                destination[10] += value[1] - binding.default_value[1];
                destination[11] += value[2] - binding.default_value[2];
            }
            ++applied;
        }
    }
    const int expectedApplied = bindingStats.quaternion_bones +
        ((rotationAfterBind || rotationBeforeBind ||
          rotationRestFirst || rotationRestLast ||
          modelRotationBindTranslation || absoluteLocalRotation) ? 0 :
         bindingStats.vector_bones);
    valid = valid && applied == expectedApplied - skippedRootChannels;
    for (int bone = 0; bone < skeleton->bone_count && valid; ++bone)
    {
        const int parent = skeleton->bones[bone].parent;
        if (!modelSpaceRotation)
        {
            if (parent < 0) std::memcpy(model[(size_t)bone].m,
                                        local[(size_t)bone].m, sizeof(float) * 12);
            else if (parent < bone)
                MultiplyAffine(local[(size_t)bone].m, model[(size_t)parent].m,
                               model[(size_t)bone].m);
            else valid = false;
        }
        else
        {
            if (parent >= bone) { valid = false; break; }
            float* destination = model[(size_t)bone].m;
            if (hasModelRotation[(size_t)bone])
            {
                const XMFLOAT4X4& rotation = sampledModelRotation[(size_t)bone];
                for (int row = 0; row < 3; ++row)
                {
                    const float* bindRow = skeleton->bones[bone].model + row * 3;
                    const float bindScale = std::sqrt(bindRow[0] * bindRow[0] +
                        bindRow[1] * bindRow[1] + bindRow[2] * bindRow[2]);
                    for (int column = 0; column < 3; ++column)
                        destination[row * 3 + column] =
                            (&rotation._11)[row * 4 + column] * bindScale;
                }
            }
            else if (parent < 0)
            {
                for (int row = 0; row < 3; ++row)
                    for (int column = 0; column < 3; ++column)
                        destination[row * 3 + column] =
                            local[(size_t)bone].m[row * 3 + column];
            }
            else
            {
                float localRotation[12]{};
                std::memcpy(localRotation, local[(size_t)bone].m,
                            sizeof(float) * 9);
                float composed[12]{};
                MultiplyAffine(localRotation, model[(size_t)parent].m,
                               composed);
                std::memcpy(destination, composed, sizeof(float) * 9);
            }
            const float* translation = local[(size_t)bone].m + 9;
            if (parent < 0)
                std::memcpy(destination + 9, translation, sizeof(float) * 3);
            else
                for (int column = 0; column < 3; ++column)
                    destination[9 + column] =
                        translation[0] * model[(size_t)parent].m[column] +
                        translation[1] * model[(size_t)parent].m[3 + column] +
                        translation[2] * model[(size_t)parent].m[6 + column] +
                        model[(size_t)parent].m[9 + column];
        }
        for (float component : model[(size_t)bone].m)
            valid = valid && std::isfinite(component);
    }
    skin.resize((size_t)skeleton->bone_count);
    const char* basisMode = std::getenv("BF6_DIAGNOSTIC_SOLDIER_BASIS");
    XMMATRIX poseBasis = XMMatrixIdentity();
    bool hasPoseBasis = false;
    if (basisMode && std::strcmp(basisMode, "z90") == 0) {
        poseBasis = XMMatrixRotationZ(XM_PIDIV2);
        hasPoseBasis = true;
    } else if (basisMode && std::strcmp(basisMode, "z-90") == 0) {
        poseBasis = XMMatrixRotationZ(-XM_PIDIV2);
        hasPoseBasis = true;
    } else if (basisMode && std::strcmp(basisMode, "x90") == 0) {
        poseBasis = XMMatrixRotationX(XM_PIDIV2);
        hasPoseBasis = true;
    } else if (basisMode && std::strcmp(basisMode, "x-90") == 0) {
        poseBasis = XMMatrixRotationX(-XM_PIDIV2);
        hasPoseBasis = true;
    }
    if (hasPoseBasis)
    {
        for (int bone = 0; bone < skeleton->rig_bone_count; ++bone)
            if (skeleton->bones[bone].name &&
                std::strcmp(skeleton->bones[bone].name, "Hips") == 0)
            {
                const float* hips = skeleton->bones[bone].model + 9;
                poseBasis = XMMatrixMultiply(
                    XMMatrixMultiply(
                        XMMatrixTranslation(-hips[0], -hips[1], -hips[2]),
                        poseBasis),
                    XMMatrixTranslation(hips[0], hips[1], hips[2]));
                break;
            }
    }
    XMFLOAT4X4 storedPoseBasis;
    XMStoreFloat4x4(&storedPoseBasis, poseBasis);
    const float poseBasisAffine[12] = {
        storedPoseBasis._11, storedPoseBasis._12, storedPoseBasis._13,
        storedPoseBasis._21, storedPoseBasis._22, storedPoseBasis._23,
        storedPoseBasis._31, storedPoseBasis._32, storedPoseBasis._33,
        storedPoseBasis._41, storedPoseBasis._42, storedPoseBasis._43 };
    for (int bone = 0; bone < skeleton->bone_count && valid; ++bone)
    {
        float basisModel[12]{};
        const float* posedModel = model[(size_t)bone].m;
        if (hasPoseBasis) {
            MultiplyAffine(posedModel, poseBasisAffine, basisModel);
            posedModel = basisModel;
        }
        MultiplyAffine(skeleton->bones[bone].inverse, posedModel,
                       skin[(size_t)bone].m);
    }
    boundChannels = bindingStats.resolved_storage;
    boneChannels = applied;
    rigBoneCount = skeleton->rig_bone_count;
    if (modelSpaceRotation)
        std::fprintf(stderr,
            "soldier model-pose diagnostic: mode=%s applied=%d\n",
            modelDeltaAfterBind ? "delta-after" :
            (modelDeltaBeforeBind ? "delta-before" :
             (modelRotationBindTranslation ? "rotation" : "all")), applied);
    bf6_free(g_bf6, clip);
    bf6_free(g_bf6, skeleton);
    if (!valid) skin.clear();
    return valid;
}

static bool CopyStaticMeshToCpu(const char* name, const bf6_mesh* m, CpuPart& out,
                                const std::vector<bf6_bone_xform>* skin = nullptr,
                                int skinRigBoneCount = 0)
{
    if (!m) return false;
    out = CpuPart{};
    out.name = name ? name : "";
    // Frame the geometry that is actually emitted. Frostbite's authored AABB
    // can describe the pre-palette/static resource domain rather than the
    // decoded vertex stream used by this presentation path; using it cropped
    // soldier feet and vehicle tracks even though those vertices were present.
    for (int k = 0; k < 3; ++k) {
        out.lo[k] = FLT_MAX;
        out.hi[k] = -FLT_MAX;
    }
    float sourceLo[3] = { FLT_MAX, FLT_MAX, FLT_MAX };
    float sourceHi[3] = { -FLT_MAX, -FLT_MAX, -FLT_MAX };
    for (int si = 0; si < m->section_count; ++si)
    {
        const bf6_section& s = m->sections[si];
        if (s.vertex_count <= 0 || s.index_count <= 0) continue;
        CpuSection cs;
        cs.verts.resize((size_t)s.vertex_count);
        const bool preserveSkin = skin && !skin->empty() && s.skin_bones &&
            s.skin_weights && s.skin_influences > 0;
        if (preserveSkin)
        {
            const size_t influenceCount = (size_t)s.vertex_count *
                (size_t)s.skin_influences;
            cs.bind_verts.resize((size_t)s.vertex_count);
            cs.skin_bones.assign(s.skin_bones,
                                 s.skin_bones + influenceCount);
            cs.skin_weights.assign(s.skin_weights,
                                   s.skin_weights + influenceCount);
            cs.skin_influences = s.skin_influences;
        }
        for (int v = 0; v < s.vertex_count; ++v)
        {
            Vtx& o = cs.verts[(size_t)v];
            const float* sourcePosition = s.positions + v * 3;
            for (int k = 0; k < 3; ++k) {
                sourceLo[k] = (std::min)(sourceLo[k], sourcePosition[k]);
                sourceHi[k] = (std::max)(sourceHi[k], sourcePosition[k]);
            }
            const float* sourceNormal = s.normals ? s.normals + v * 3 : nullptr;
            const float* sourceTangent = s.tangents ? s.tangents + v * 4 : nullptr;
            bool skinned = false;
            if (preserveSkin)
            {
                o.p[0] = o.p[1] = o.p[2] = 0.f;
                o.n[0] = o.n[1] = o.n[2] = 0.f;
                o.tangent[0] = o.tangent[1] = o.tangent[2] = 0.f;
                float accepted = 0.f;
                for (int lane = 0; lane < s.skin_influences; ++lane)
                {
                    const size_t influence = (size_t)v * s.skin_influences + lane;
                    const float weight = s.skin_weights[influence];
                    const uint16_t rawBone = s.skin_bones[influence];
                    const int bone = (rawBone & 0x8000u)
                        ? skinRigBoneCount + (int)((rawBone & 0x7FFFu) >> 1)
                        : (int)rawBone;
                    if (weight <= 0.f || bone < 0 || bone >= (int)skin->size()) continue;
                    const float* matrix = (*skin)[(size_t)bone].m;
                    for (int column = 0; column < 3; ++column)
                    {
                        o.p[column] += weight * (sourcePosition[0] * matrix[column] +
                            sourcePosition[1] * matrix[3 + column] +
                            sourcePosition[2] * matrix[6 + column] + matrix[9 + column]);
                        if (sourceNormal) o.n[column] += weight *
                            (sourceNormal[0] * matrix[column] +
                             sourceNormal[1] * matrix[3 + column] +
                             sourceNormal[2] * matrix[6 + column]);
                        if (sourceTangent) o.tangent[column] += weight *
                            (sourceTangent[0] * matrix[column] +
                             sourceTangent[1] * matrix[3 + column] +
                             sourceTangent[2] * matrix[6 + column]);
                    }
                    accepted += weight;
                }
                if (accepted > 1e-8f) {
                    const float reciprocal = 1.f / accepted;
                    for (int column = 0; column < 3; ++column) {
                        o.p[column] *= reciprocal; o.n[column] *= reciprocal;
                        o.tangent[column] *= reciprocal;
                    }
                    skinned = true;
                }
            }
            if (!skinned) {
                o.p[0] = sourcePosition[0]; o.p[1] = sourcePosition[1];
                o.p[2] = sourcePosition[2];
                if (sourceNormal) { o.n[0] = sourceNormal[0]; o.n[1] = sourceNormal[1]; o.n[2] = sourceNormal[2]; }
                else { o.n[0] = 0.f; o.n[1] = 1.f; o.n[2] = 0.f; }
                if (sourceTangent) for (int k = 0; k < 4; ++k) o.tangent[k] = sourceTangent[k];
                else { o.tangent[0]=1.f; o.tangent[1]=o.tangent[2]=0.f; o.tangent[3]=1.f; }
            } else if (sourceTangent) o.tangent[3] = sourceTangent[3];
            for (int k = 0; k < 3; ++k) {
                out.lo[k] = (std::min)(out.lo[k], o.p[k]);
                out.hi[k] = (std::max)(out.hi[k], o.p[k]);
            }
            if (s.uv0) { o.t[0]=s.uv0[v*2]; o.t[1]=s.uv0[v*2+1]; }
            else o.t[0]=o.t[1]=0.f;
            if (s.uv1) { o.t1[0]=s.uv1[v*2]; o.t1[1]=s.uv1[v*2+1]; }
            else { o.t1[0]=o.t[0]; o.t1[1]=o.t[1]; }
            if (preserveSkin)
            {
                Vtx& bind = cs.bind_verts[(size_t)v];
                bind = o;
                for (int k = 0; k < 3; ++k) {
                    bind.p[k] = sourcePosition[k];
                    bind.n[k] = sourceNormal ? sourceNormal[k] :
                        (k == 1 ? 1.f : 0.f);
                    bind.tangent[k] = sourceTangent ? sourceTangent[k] :
                        (k == 0 ? 1.f : 0.f);
                }
                bind.tangent[3] = sourceTangent ? sourceTangent[3] : 1.f;
            }
        }
        cs.idx.assign(s.indices, s.indices + s.index_count);
        if (s.material >= 0 && s.material < m->material_count)
        {
            const bf6_material_desc& md = m->materials[s.material];
            for (int k = 0; k < 4; ++k) cs.base_color[k] = md.base_color[k];
            cs.roughness = md.roughness;
            cs.metallic = md.metallic;
            cs.normal_is_nsm = md.normal_is_nsm;
            cs.alpha_test = md.alpha_test;
            cs.alpha_from_albedo = md.alpha_from_albedo;
            cs.translucent = md.translucent;
            for (int k = 0; k < 3; ++k) cs.emissive[k] = md.emissive[k];
            for (int b = 0; b < md.texture_count; ++b)
            {
                const bf6_tex_binding& tb = md.textures[b];
                int slot = -1;
                if (tb.slot == BF6_TEX_ALBEDO) slot = 0;
                else if (tb.slot == BF6_TEX_NORMAL) slot = 1;
                else if (tb.slot == BF6_TEX_WO || tb.slot == BF6_TEX_MRO) slot = 2;
                else if (tb.slot == BF6_TEX_MASK) slot = 3;
                if (slot >= 0 && tb.texture >= 0 && cs.tex[slot] < 0) cs.tex[slot] = tb.texture;
            }
            for (int b = 0; b < md.shader_texture_count; ++b)
            {
                const bf6_shader_tex_binding& tb = md.shader_textures[b];
                int slot = -1;
                if (tb.name32 == 0x0370914Eu) slot = 4;      // iris colour
                else if (tb.name32 == 0x1419F025u) slot = 5; // sclera colour
                else if (tb.name32 == 0x71828BD1u) slot = 6; // iris normal
                else if (tb.name32 == 0xEC2DE079u) slot = 7; // sclera normal
                else if (tb.name32 == 0xE15F84CEu) slot = 8; // eye/iris mask
                if (slot >= 0 && tb.texture >= 0) cs.tex[slot] = tb.texture;
            }
            // Character ghillie/cloth permutations do not publish their
            // colour/normal pair through the generic material slots.  Their
            // resolved shader record does, however, identify both sheets by
            // stable name32 and by exact current-install asset path. Prefer
            // the dedicated ghillie pair, then the underlying outfit pair,
            // only when the ordinary material resolver supplied no surface.
            // This is intentionally narrower than adding either identity to
            // libbf6's global albedo chain: both records coexist on the same
            // character shader and are not generic environmental materials.
            if (cs.tex[0] < 0)
            {
                for (int priority = 0; priority < 2 && cs.tex[0] < 0;
                     ++priority)
                    for (int b = 0; b < md.shader_texture_count; ++b)
                    {
                        const bf6_shader_tex_binding& tb =
                            md.shader_textures[b];
                        const uint32_t wanted = priority == 0
                            ? 0x20B5AC7Eu  // character ghillie _cs
                            : 0x20B3071Fu; // underlying outfit _cs
                        if (tb.name32 == wanted && tb.texture >= 0)
                        { cs.tex[0] = tb.texture; break; }
                    }
            }
            if (cs.tex[1] < 0)
            {
                for (int priority = 0; priority < 2 && cs.tex[1] < 0;
                     ++priority)
                    for (int b = 0; b < md.shader_texture_count; ++b)
                    {
                        const bf6_shader_tex_binding& tb =
                            md.shader_textures[b];
                        const uint32_t wanted = priority == 0
                            ? 0x376AEB8Eu  // character ghillie _nx
                            : 0x3713D44Fu; // underlying outfit _nx
                        if (tb.name32 == wanted && tb.texture >= 0)
                        { cs.tex[1] = tb.texture; break; }
                    }
            }
            cs.shader_family = cs.tex[4] >= 0 && cs.tex[5] >= 0 &&
                cs.tex[6] >= 0 && cs.tex[7] >= 0 && cs.tex[8] >= 0 ? 1 : 0;
        }
        out.sections.push_back(std::move(cs));
    }
    if (out.sections.empty()) return false;
    if (skin && !skin->empty())
        std::fprintf(stderr,
            "soldier posed vertex bounds: %s source=(%.4f %.4f %.4f).."
            "(%.4f %.4f %.4f) posed=(%.4f %.4f %.4f)..(%.4f %.4f %.4f)\n",
            name ? name : "", sourceLo[0], sourceLo[1], sourceLo[2],
            sourceHi[0], sourceHi[1], sourceHi[2], out.lo[0], out.lo[1],
            out.lo[2], out.hi[0], out.hi[1], out.hi[2]);
    // Keep the ABI's authored bounds only as a defensive fallback for an
    // invalid/non-finite resource; normal resources are framed from vertices.
    for (int k = 0; k < 3; ++k) {
        if (!std::isfinite(out.lo[k]) || !std::isfinite(out.hi[k]) ||
            out.lo[k] > out.hi[k]) {
            out.lo[k] = m->aabb_min[k];
            out.hi[k] = m->aabb_max[k];
        }
    }
    return true;
}

static std::shared_ptr<CpuScenePresentationPayload>
WorkerLoadScenePresentation(const ScenePresentationRequest& request)
{
    const auto started = std::chrono::steady_clock::now();
    auto payload = std::make_shared<CpuScenePresentationPayload>();
    payload->request = request;

    struct MeshSpec {
        std::string name;
        std::string bundle;
        std::string variation;
        int soldier_selection = -1;
        float transform[12] = {
            1.f, 0.f, 0.f, 0.f, 1.f, 0.f,
            0.f, 0.f, 1.f, 0.f, 0.f, 0.f };
    };
    std::vector<MeshSpec> meshSpecs;
    std::string vehicleBundle;
    std::string vehicleVariation;
    float soldierTransforms[4][12] = {};
    for (int classIndex = 0; classIndex < 4; ++classIndex)
        soldierTransforms[classIndex][0] =
            soldierTransforms[classIndex][4] =
            soldierTransforms[classIndex][8] = 1.f;
    if (request.kind == ScenePresentationKind::Soldier)
    {
        const bool haveSoldierTransforms =
            LoadSoldierPresentationTransforms(
                soldierTransforms, payload->loadout_link_frame);
        payload->has_loadout_link_frame = haveSoldierTransforms;
        struct SoldierSpec {
            const char* token;
            const char* label;
            const char* set_id;
            const char* outfit_bundle;
            const char* face_bundle;
        };
        // The installed presentation provider and the signed-in reference
        // agree on WISP/JAZZ/KNOW/AVER in class order. Keep the character
        // identity separate from the class clip selection, but preserve this
        // exact current-account projection rather than reclassifying tokens
        // from one silhouette.
        static const SoldierSpec soldiers[] = {
            {"cha0001wisp", "WISP - ASSAULT",
             "set_001", "win32/pf_cha0001wisp_set_001_wk73bk_bundle_3p",
             "pf_cha0001wisp_face_001_hzauxf_bundle_3p"},
            {"cha0004jazz", "JAZZ - ENGINEER",
             "set_007", "win32/pf_cha0004jazz_set_007_12l1ldc_bundle_3p_highdef",
             "pf_cha0004jazz_face_001_upfeyb_bundle_3p"},
            {"cha0002know", "KNOW - SUPPORT",
             "set_010", "win32/pf_cha0002know_set_010_6qvs6o_bundle_3p",
             "pf_cha0002know_face_001_1cufypf_bundle_3p"},
            {"cha0003aver", "AVER - RECON",
             "set_010", "win32/pf_cha0003aver_set_010_pju6ls_bundle_3p",
             "pf_cha0003aver_face_001_16psp9v_bundle_3p"},
        };
        auto appendSoldier = [&](int classIndex)
        {
            const SoldierSpec& soldier = soldiers[(size_t)classIndex];
            float transform[12] = {
                1.f, 0.f, 0.f, 0.f, 1.f, 0.f,
                0.f, 0.f, 1.f, 0.f, 0.f, 0.f };
            if (haveSoldierTransforms)
                std::copy(soldierTransforms[classIndex],
                          soldierTransforms[classIndex] + 12, transform);
            else if (g_hasLoadoutClassCamera)
            {
                // Fail-soft compatibility for an install whose presentation
                // prefab is absent: the camera graph still supplies a bounded
                // approximation. Current retail takes the exact prefab path.
                transform[9] =
                    g_loadoutClassCamera.look_at_offset[classIndex][0][0];
                transform[11] =
                    g_loadoutClassCamera.look_at_offset[classIndex][0][2];
            }
            const std::string token = soldier.token;
            const std::string setRoot = "common/characters/mp/main/" + token +
                "/set/set_001/" + token + "_set_001";
            const std::string setVariantRoot =
                "common/characters/mp/main/" + token + "/set/" +
                soldier.set_id + "/" + token + "_" + soldier.set_id;
            std::vector<std::string> outfitMembers;
            if (token == "cha0003aver")
                outfitMembers = {"", "cloth", "headgear", "headgear_cloth"};
            else
                outfitMembers = {"", "backpack", "headgear"};
            for (const std::string& member : outfitMembers)
            {
                const std::string suffix = member.empty() ? "" : "_" + member;
                const std::string variation = std::string(soldier.set_id) ==
                        "set_001"
                    ? std::string() : setVariantRoot + suffix;
                MeshSpec spec{setRoot + suffix + "_mesh",
                              soldier.outfit_bundle, variation, classIndex};
                std::copy(transform, transform + 12, spec.transform);
                meshSpecs.push_back(std::move(spec));
            }
            const std::string faceRoot =
                "common/characters/mp/main/" + token + "/face/_base/" +
                token + "_face_";
            const std::string faceVariantRoot =
                "common/characters/mp/main/" + token + "/face/face_001/" +
                token + "_face_001_";
            MeshSpec face{faceRoot + "base_standard_mesh",
                          soldier.face_bundle,
                          faceVariantRoot + "base_standard", classIndex};
            std::copy(transform, transform + 12, face.transform);
            meshSpecs.push_back(std::move(face));
            MeshSpec parts{faceRoot + "parts_standard_mesh",
                           soldier.face_bundle, {}, classIndex};
            std::copy(transform, transform + 12, parts.transform);
            meshSpecs.push_back(std::move(parts));
        };
        if (request.class_loadout)
        {
            payload->label = "CLASS LOADOUT LINEUP";
            for (int classIndex = 0; classIndex < 4; ++classIndex)
                appendSoldier(classIndex);
        }
        else
        {
            const int classIndex = (std::max)(0, (std::min)(
                request.selection, 3));
            payload->label = soldiers[(size_t)classIndex].label;
            appendSoldier(classIndex);
        }
    }
    else if (request.kind == ScenePresentationKind::Vehicle)
    {
        const VehicleSpec& vehicle = kVehicleShowcases[(size_t)(std::max)(
            0, (std::min)(request.selection,
                (int)std::size(kVehicleShowcases) - 1))];
        payload->label = vehicle.label;
        vehicleBundle = vehicle.bundle;
        vehicleVariation = vehicle.variation;
        meshSpecs.push_back({"common/hardware/vehicles/tank/" +
            std::string(vehicle.token) + "/art/ob_veh_tank_" +
            vehicle.token + "_base_mesh", vehicleBundle, vehicleVariation});
    }

    // The current-install VBR encoder subtracts its predictor before range
    // quantization. Once animated residuals are decoded around zero, the
    // symbolic DOFs are the actor's absolute local pose and pass the bind-pose
    // and silhouette controls. Explicit environment modes remain available
    // for the rejected composition-order diagnostics.
    const char* diagnosticPose = std::getenv("BF6_DIAGNOSTIC_SOLDIER_POSE");
    std::array<SoldierAnimationSamples, 4> soldierAnimations;
    std::array<bool, 4> haveSoldierAnimations{};
    if (request.kind == ScenePresentationKind::Soldier && !diagnosticPose)
    {
        const int first = request.class_loadout ? 0 : (std::max)(0,
            (std::min)(request.selection, 3));
        const int last = request.class_loadout ? 3 : first;
        for (int classIndex = first; classIndex <= last; ++classIndex)
        {
            haveSoldierAnimations[(size_t)classIndex] =
                LoadSoldierAnimationSamples(classIndex,
                    request.class_loadout, soldierAnimations[(size_t)classIndex]);
            if (haveSoldierAnimations[(size_t)classIndex] &&
                !std::getenv("BF6_DIAGNOSTIC_SOLDIER_CLIP"))
            {
                const std::string& weapon = request.class_loadout
                    ? g_loadoutEquipped[(size_t)classIndex]
                        [(size_t)LoadoutSlot::Primary]
                    : request.weapon;
                if (!weapon.empty())
                {
                    // The class clip can drive three independent samples of
                    // the same weapon pose bank. Support is the one landing
                    // silhouette whose authored split is required here:
                    // WepFwd=4 places the M250 and WepMidRelaxed=8 places both
                    // arms. Applying the arm writers to Assault/Engineer puts
                    // their hands at the face because those branches depend on
                    // a later IK-weight stage we have not reproduced. Use the
                    // bank's named retail-equivalent complete pose for those
                    // two (LeftSide and Mid), and the authored complete
                    // WepRightHand pose for Recon's upright rifle.
                    SoldierAnimationSamples& animation =
                        soldierAnimations[(size_t)classIndex];
                    if (request.class_loadout)
                    {
                        if (std::getenv(
                                "BF6_DIAGNOSTIC_AUTHORED_HPOSE_WRITERS"))
                        {
                            static constexpr int kMainWriter[4] =
                                {11, 10, 4, 10};
                            static constexpr int kLeftWriter[4] =
                                {4, 4, 8, 8};
                            static constexpr int kRightWriter[4] =
                                {4, 3, 8, 8};
                            ApplySoldierWeaponHpose(weapon, animation,
                                kMainWriter[classIndex],
                                SoldierHposeMask::Weapon);
                            ApplySoldierWeaponHpose(weapon, animation,
                                kLeftWriter[classIndex],
                                SoldierHposeMask::LeftArm);
                            ApplySoldierWeaponHpose(weapon, animation,
                                kRightWriter[classIndex],
                                SoldierHposeMask::RightArm);
                        }
                        else if (classIndex == 2)
                        {
                            ApplySoldierWeaponHpose(weapon, animation, 4,
                                SoldierHposeMask::Weapon);
                            ApplySoldierWeaponHpose(weapon, animation, 8,
                                SoldierHposeMask::LeftArm);
                            ApplySoldierWeaponHpose(weapon, animation, 8,
                                SoldierHposeMask::RightArm);
                        }
                        else
                        {
                            static constexpr int kLandingCompleteHpose[4] =
                                {6, 7, 0, 10};
                            ApplySoldierWeaponHpose(weapon, animation,
                                kLandingCompleteHpose[classIndex]);
                        }
                    }
                    else
                    {
                        ApplySoldierWeaponHpose(weapon, animation, 1);
                    }
                }
            }
        }
    }
    std::array<std::vector<bf6_bone_xform>, 4>
        soldierWeaponAlignFrames;
    std::array<std::vector<bf6_bone_xform>, 4>
        soldierRigSkinFrames;
    std::array<float, 4> soldierPoseMinY{{
        FLT_MAX, FLT_MAX, FLT_MAX, FLT_MAX}};
    std::vector<int> wantedTextures;
    for (const MeshSpec& spec : meshSpecs)
    {
        if (g_quit) return payload;
        payload->fake_control_matches +=
            (std::max)(0, bf6_list_res(g_bf6,
                ("__bf6_control__/" + spec.name).c_str(), nullptr, 0));
        // Front-end actors are part of the armory mount. Resolve their FILE
        // GUIDs through the bounded armory partition index already warmed at
        // startup; the generic global index scans every mounted partition and
        // added ~9.7 seconds to the first actor after Home was route-deferred.
        bf6_mesh* mesh = bf6_read_armory_mesh_scoped(
            g_bf6, spec.name.c_str(), 0, spec.bundle.c_str(),
            spec.variation.empty() ? nullptr : spec.variation.c_str());
        if (!mesh) continue;
        std::vector<bf6_bone_xform> soldierSkin;
        std::vector<bf6_bone_xform> soldierSkinFrames;
        int soldierRigBones = 0;
        int soldierBoneCount = 0;
        const int soldierSelection = spec.soldier_selection >= 0
            ? spec.soldier_selection : request.selection;
        SoldierAnimationSamples& soldierAnimation = soldierAnimations[(size_t)
            (std::max)(0, (std::min)(soldierSelection, 3))];
        const bool haveSoldierAnimation = request.kind ==
            ScenePresentationKind::Soldier &&
            haveSoldierAnimations[(size_t)(std::max)(0,
                (std::min)(soldierSelection, 3))];
        std::vector<bf6_bone_xform>& selectedWeaponAlignFrames =
            soldierWeaponAlignFrames[(size_t)(std::max)(0,
                (std::min)(soldierSelection, 3))];
        std::vector<bf6_bone_xform>& selectedRigSkinFrames =
            soldierRigSkinFrames[(size_t)(std::max)(0,
                (std::min)(soldierSelection, 3))];
        if (request.kind == ScenePresentationKind::Soldier)
        {
            std::string renderbones = spec.name;
            static const std::string meshSuffix = "_mesh";
            if (renderbones.size() >= meshSuffix.size() &&
                renderbones.compare(renderbones.size() - meshSuffix.size(),
                                    meshSuffix.size(), meshSuffix) == 0)
                renderbones.replace(renderbones.size() - meshSuffix.size(),
                                    meshSuffix.size(), "_renderbonesdata");
            else renderbones.clear();
            int partBoundChannels = 0, partBoneChannels = 0;
            bool posed = false;
            if (haveSoldierAnimation)
            {
                posed = BuildSoldierAnimationSkinFrames(
                    soldierAnimation, renderbones.c_str(), mesh->bone_count,
                    soldierSkinFrames, soldierBoneCount, soldierRigBones,
                    selectedWeaponAlignFrames.empty()
                        ? &selectedWeaponAlignFrames : nullptr,
                    selectedRigSkinFrames.empty()
                        ? &selectedRigSkinFrames : nullptr);
                if (posed && !soldierSkinFrames.empty())
                    soldierSkin.assign(
                        soldierSkinFrames.begin(),
                        soldierSkinFrames.begin() + soldierBoneCount);
                partBoundChannels = soldierAnimation.stats.resolved_storage;
                partBoneChannels = soldierAnimation.stats.quaternion_bones +
                    soldierAnimation.stats.vector_bones;
            }
            else
            {
                posed = BuildSoldierIdleSkin(
                    soldierSelection, request.class_loadout,
                    renderbones.c_str(), mesh->bone_count,
                    soldierSkin, partBoundChannels, partBoneChannels,
                    soldierRigBones);
                soldierBoneCount = (int)soldierSkin.size();
            }
            payload->animation_pose_ready =
                (payload->animation_pose_ready || posed) ? 1 : 0;
            payload->animation_bound_channels = (std::max)(
                payload->animation_bound_channels, partBoundChannels);
            payload->animation_bone_channels = (std::max)(
                payload->animation_bone_channels, partBoneChannels);
        }
        CpuPart part;
        if (CopyStaticMeshToCpu(spec.name.c_str(), mesh, part,
                soldierSkin.empty() ? nullptr : &soldierSkin,
                soldierRigBones))
        {
            if (request.kind == ScenePresentationKind::Soldier &&
                soldierSelection >= 0 && soldierSelection < 4)
                soldierPoseMinY[(size_t)soldierSelection] = (std::min)(
                    soldierPoseMinY[(size_t)soldierSelection], part.lo[1]);
            std::copy(spec.transform, spec.transform + 12,
                      part.presentation_transform);
            if (!soldierSkinFrames.empty())
            {
                part.animation_skin_frames = std::move(soldierSkinFrames);
                part.animation_frame_count = soldierAnimation.frame_count;
                part.animation_bone_count = soldierBoneCount;
                part.animation_rig_bone_count = soldierRigBones;
                part.animation_fps = soldierAnimation.fps;
            }
            ++payload->exact_meshes;
            for (const CpuSection& section : part.sections)
            {
                if (section.tex[0] >= 0) ++payload->textured_sections;
                if (section.alpha_test) ++payload->alpha_test_sections;
                if (section.alpha_test && section.tex[3] >= 0)
                    ++payload->alpha_mask_sections;
                if (section.translucent) ++payload->translucent_sections;
                if (section.shader_family == 1) ++payload->eye_shader_sections;
                for (int slot = 0; slot < 9; ++slot)
                    if (section.tex[slot] >= 0 &&
                        std::find(wantedTextures.begin(), wantedTextures.end(),
                                  section.tex[slot]) == wantedTextures.end())
                        wantedTextures.push_back(section.tex[slot]);
            }
            payload->parts.push_back(std::move(part));
        }
        bf6_free(g_bf6, mesh);
    }

    if (request.kind == ScenePresentationKind::Soldier)
    {
        // Glacier consumes the clip's locomotion/root displacement before
        // presenting a stationary menu actor.  Without that contact stage,
        // the four otherwise-correct class clips leave their soles at four
        // different heights.  Ground each assembled outfit as one actor; do
        // not normalize individual pieces, which would split the face,
        // headgear and backpack away from the body.
        const int first = request.class_loadout ? 0 : (std::max)(0,
            (std::min)(request.selection, 3));
        const int last = request.class_loadout ? 3 : first;
        for (int soldier = first; soldier <= last; ++soldier)
        {
            const float floorOffset = soldierPoseMinY[(size_t)soldier];
            if (!std::isfinite(floorOffset) || floorOffset == FLT_MAX)
                continue;
            for (CpuPart& part : payload->parts)
                if (std::memcmp(part.presentation_transform,
                                soldierTransforms[soldier],
                                sizeof(soldierTransforms[soldier])) == 0)
                {
                    part.presentation_transform[10] -= floorOffset;
                    part.presentation_ground_offset = floorOffset;
                }
            soldierTransforms[soldier][10] -= floorOffset;
            std::fprintf(stderr,
                "soldier presentation grounding: class=%d sole=%.6f\n",
                soldier, floorOffset);
        }
    }

    for (int textureId : wantedTextures)
    {
        if (g_quit) return payload;
        const bf6_texture* texture =
            bf6_texture_at_max_dim(g_bf6, textureId, 1024);
        if (!texture || !texture->data || texture->data_len <= 0) continue;
        CpuTex copied;
        copied.id = textureId;
        copied.w = texture->width;
        copied.h = texture->height;
        copied.mips = texture->mip_count;
        copied.fmt = static_cast<int>(texture->format);
        copied.srgb = texture->srgb;
        copied.borrowed_data = texture->data;
        copied.borrowed_len = static_cast<size_t>(texture->data_len);
        payload->textures.push_back(std::move(copied));
    }
    if (request.kind == ScenePresentationKind::Soldier)
    {
        const int first = request.class_loadout ? 0 : (std::max)(0,
            (std::min)(request.selection, 3));
        const int last = request.class_loadout ? 3 : first;
        for (int soldier = first; soldier <= last; ++soldier)
        {
            SoldierAnimationSamples& animation =
                soldierAnimations[(size_t)soldier];
            std::vector<bf6_bone_xform>& alignFrames =
                soldierWeaponAlignFrames[(size_t)soldier];
            std::vector<bf6_bone_xform>& rigSkinFrames =
                soldierRigSkinFrames[(size_t)soldier];
            const std::string weapon = request.class_loadout
                ? g_loadoutEquipped[(size_t)soldier]
                    [(size_t)LoadoutSlot::Primary]
                : request.weapon;
            if (!haveSoldierAnimations[(size_t)soldier] || weapon.empty() ||
                alignFrames.size() != (size_t)animation.frame_count)
                continue;

            // Weapon meshes are already assembled in the shared Wep_Align
            // coordinate system. Follow the class clip's reconstructed IK
            // constraint, then apply the exact actor placement from the
            // presentation prefab.
            WeaponRequest weaponRequest;
            weaponRequest.weapon = weapon;
            weaponRequest.factory = true;
            std::vector<CpuPart> weaponParts;
            std::vector<CpuTex> weaponTextures;
            std::vector<bf6_bone_xform> staticWeaponSkin;
            WorkerLoadWeapon(weaponRequest, weaponParts, weaponTextures,
                             nullptr, &staticWeaponSkin);
            const int rigBoneCount = animation.frame_count > 0 &&
                    rigSkinFrames.size() %
                        (size_t)animation.frame_count == 0
                ? (int)(rigSkinFrames.size() /
                    (size_t)animation.frame_count) : 0;
            std::vector<bf6_bone_xform> integratedWeaponSkinFrames;
            // The soldier clip's Wep_* branch is not the final render palette:
            // Frostbite applies a later procedural weapon/hand stage.  Directly
            // grafting those matrices onto the configured 66-bone weapon pose
            // visibly separates the receiver's mechanical clusters.  Retain
            // that exact-name experiment as an explicit diagnostic, but keep
            // production on the correctly assembled palette followed by the
            // reconstructed rigid Wep_Align constraint.
            const bool tryIntegratedWeaponSkin =
                std::getenv("BF6_DIAGNOSTIC_INTEGRATED_WEAPON_SKIN") != nullptr;
            const bool haveIntegratedWeaponSkin = tryIntegratedWeaponSkin &&
                BuildIntegratedWeaponSkinFrames(staticWeaponSkin,
                    rigSkinFrames, animation.frame_count, rigBoneCount,
                    integratedWeaponSkinFrames);
            for (CpuPart& weaponPart : weaponParts)
            {
                const bool bound = haveIntegratedWeaponSkin &&
                    BindSkinnedPartToSoldierWeapon(weaponPart,
                        integratedWeaponSkinFrames, animation.frame_count,
                        (int)staticWeaponSkin.size(), animation.fps);
                if (!bound && !BindRigidPartToSoldierWeapon(
                        weaponPart, alignFrames, animation.fps))
                    continue;
                std::copy(soldierTransforms[soldier],
                          soldierTransforms[soldier] + 12,
                          weaponPart.presentation_transform);
                weaponPart.presentation_ground_offset =
                    soldierPoseMinY[(size_t)soldier];
                for (const CpuSection& section : weaponPart.sections)
                {
                    if (section.tex[0] >= 0) ++payload->textured_sections;
                    if (section.alpha_test) ++payload->alpha_test_sections;
                    if (section.alpha_test && section.tex[3] >= 0)
                        ++payload->alpha_mask_sections;
                    if (section.translucent)
                        ++payload->translucent_sections;
                }
                ++payload->attached_weapon_parts;
                payload->parts.push_back(std::move(weaponPart));
            }
            for (CpuTex& texture : weaponTextures)
                payload->textures.push_back(std::move(texture));
        }
    }
    payload->load_ms = std::chrono::duration<double, std::milli>(
        std::chrono::steady_clock::now() - started).count();
    return payload;
}

static void WorkerLoadNearbyHangar(const std::vector<bf6_instance>& placements,
                                   const float actor[12], int studioFlavor)
{
    struct Candidate { float d2; const bf6_instance* p; };
    std::vector<Candidate> candidates;
    int alternateLayerControl = 0;
    static const char* kBaseLayer =
        "game/glacierflow/flow_mainmenu/content_hangar.ebx";
    static const char* kLightingLayer =
        "game/glacierflow/flow_mainmenu/content_hangar_lighting.ebx";
    const bool soldierStudio = studioFlavor == 2;
    const bool vehicleStudio = studioFlavor == 3;
    static const char* kVehicleLayer =
        "game/glacierflow/flow_mainmenu/content_hangar_vehicle.ebx";
    for (const bf6_instance& p : placements)
    {
        if (!p.res_name || !p.source) continue;
        const std::string source = p.source;
        const std::string res = p.res_name;
        // flow_mainmenu contains multiple mutually exclusive content layers
        // whose names all begin with content_hangar (loadouts, lobby states,
        // etc.).  The weapon camera lives in the base layer; its fixture layer
        // is additive.  A substring match mixed those states and put loadout
        // lockers into the customization frame.
        if (vehicleStudio && source != kBaseLayer &&
            source != kLightingLayer && source != kVehicleLayer) {
            if (source.find("game/glacierflow/flow_mainmenu/content_hangar") !=
                    std::string::npos)
                ++alternateLayerControl;
            continue;
        }
        if (!soldierStudio && !vehicleStudio &&
            source != kBaseLayer && source != kLightingLayer) {
            if (source.find("game/glacierflow/flow_mainmenu/content_hangar") != std::string::npos)
                ++alternateLayerControl;
            continue;
        }
        if (res.find("common/environment/") == std::string::npos &&
            res.find("common/lighting/") == std::string::npos)
            continue;
        // Decals need their own projected-material pass. Feeding them to the
        // opaque mesh shader is confidently wrong, so leave them out until
        // that pass exists.
        if (res.find("/decals/") != std::string::npos || res.find("/de_") != std::string::npos)
            continue;
        const float dx = p.xform[9] - actor[9];
        const float dy = p.xform[10] - actor[10];
        const float dz = p.xform[11] - actor[11];
        const float d2 = dx*dx + dy*dy + dz*dz;
        if (d2 <= 30.f * 30.f) candidates.push_back({d2, &p});
    }
    std::sort(candidates.begin(), candidates.end(),
        [](const Candidate& a, const Candidate& b) { return a.d2 < b.d2; });

    std::vector<CpuPlacedPart> parts;
    std::vector<int> wantTextures;
    int attempted = 0;
    for (const Candidate& c : candidates)
    {
        // The 30 m graph-derived radius is the bound. A second 256-mesh cap
        // truncated this installed scene at 18.25 m (256 of 350 readable
        // candidates), dropping the far half of the authored hangar that the
        // class camera sees. Consume the complete local radius; this remains a
        // one-time asynchronous read bounded independently of level size.
        const bf6_instance& p = *c.p;
        ++attempted;
        // Loose placements name a prop EBX, whose geometry is the sibling
        // `_mesh` resource. StaticModelGroup members already name MeshAsset
        // EBXs and therefore already end in `_mesh`; appending a second suffix
        // dropped the entire authored hangar shell after its walk was fixed.
        std::string meshRes = p.res_name;
        if (meshRes.size() > 4 && meshRes.compare(meshRes.size() - 4, 4, ".ebx") == 0)
            meshRes.resize(meshRes.size() - 4);
        if (meshRes.size() < 5 ||
            meshRes.compare(meshRes.size() - 5, 5, "_mesh") != 0)
            meshRes += "_mesh";
        bf6_mesh* m = bf6_read_mesh_scoped(g_bf6, meshRes.c_str(), 0,
                                           p.placing_bundle, p.variation);
        if (!m) continue;
        CpuPlacedPart placed;
        if (CopyStaticMeshToCpu(meshRes.c_str(), m, placed.part))
        {
            ArmoryWorldToWeaponLocal(p.xform, actor, placed.local_xform);
            for (const CpuSection& s : placed.part.sections)
                for (int k = 0; k < 4; ++k)
                    if (s.tex[k] >= 0 && std::find(wantTextures.begin(), wantTextures.end(), s.tex[k]) == wantTextures.end())
                        wantTextures.push_back(s.tex[k]);
            parts.push_back(std::move(placed));
        }
        bf6_free(g_bf6, m);
    }

    std::vector<CpuTex> textures;
    for (int id : wantTextures)
    {
        const bf6_texture* t = bf6_texture_at_max_dim(g_bf6, id, 512);
        if (!t || !t->data || t->data_len <= 0) continue;
        CpuTex ct;
        ct.id=id; ct.w=t->width; ct.h=t->height; ct.mips=t->mip_count;
        ct.fmt=(int)t->format; ct.srgb=t->srgb;
        ct.borrowed_data=t->data; ct.borrowed_len=(size_t)t->data_len;
        textures.push_back(std::move(ct));
    }
    // Seven reflection-volume captures ship with this hangar. The 256px
    // capture is the highest-resolution local volume used by the presentation
    // station; unlike ordinary material textures it is six sequential faces.
    // Copy it because the worker publishes the payload after releasing the
    // non-thread-safe libbf6 context lock.
    CpuTex reflection;
    bool hasReflection = false;
    static const char* kPresentationReflection =
        "game/glacierflow/flow_mainmenu/reflectionvolumetexture/"
        "content_hangar_reflectionvolumes/"
        "f84912ce-67f6-415a-b431-4f53ef20a810-tex";
    static const char* kVehicleReflection =
        "game/glacierflow/flow_mainmenu/reflectionvolumetexture/"
        "content_hangar_vehicle/"
        "73efb08f-d820-4a64-a503-4f822de30bed-tex";
    const int reflectionId = bf6_texture_id_by_name(
        g_bf6, vehicleStudio ? kVehicleReflection : kPresentationReflection);
    const bf6_texture* reflectionTexture = reflectionId >= 0
        ? bf6_texture_at(g_bf6, reflectionId) : nullptr;
    if (reflectionTexture && reflectionTexture->data &&
        reflectionTexture->format == BF6_FMT_RGBA16F &&
        reflectionTexture->mip_count == 1 &&
        reflectionTexture->data_len ==
            reflectionTexture->width * reflectionTexture->height * 8 * 6)
    {
        reflection.id = reflectionId;
        reflection.w = reflectionTexture->width;
        reflection.h = reflectionTexture->height;
        reflection.mips = 1;
        reflection.fmt = static_cast<int>(reflectionTexture->format);
        reflection.srgb = reflectionTexture->srgb;
        reflection.slices = 6;
        reflection.cube = true;
        reflection.data.assign(
            reflectionTexture->data,
            reflectionTexture->data + reflectionTexture->data_len);
        hasReflection = true;
    }
    const size_t publishedParts = parts.size();
    const size_t publishedTextures = textures.size();
    {
        std::lock_guard<std::mutex> k(g_hangarLock);
        g_pendingHangarParts = std::move(parts);
        g_pendingHangarTextures = std::move(textures);
        g_pendingHangarReflection = std::move(reflection);
        g_pendingHangarHasReflection = hasReflection;
        g_pendingHangarFlavor.store(studioFlavor, std::memory_order_relaxed);
        g_hangarPending.store(true, std::memory_order_release);
    }
    std::fprintf(stderr,
        "%s hangar nearby: candidates=%zu attempted=%d meshes=%zu textures=%zu reflection=%d alternate_layer_control=%d\n",
        vehicleStudio ? "vehicle" : (soldierStudio ? "soldier" : "weapon"),
        candidates.size(), attempted, publishedParts, publishedTextures,
        hasReflection ? 1 : 0, alternateLayerControl);
}

// BC5 is two independent BC4 blocks. Decode the stored R/G fields and bake
// the hardware-icon composite once per page: white RGB, derived coverage in A.
// This keeps ImGui on its normal shader and avoids callback render-state churn.
static void DecodeBc4(const uint8_t* b, uint8_t out[16])
{
    uint8_t p[8] = { b[0], b[1] };
    if (p[0] > p[1])
        for (int i = 1; i <= 6; i++) p[i + 1] = (uint8_t)(((7 - i) * p[0] + i * p[1]) / 7);
    else
    {
        for (int i = 1; i <= 4; i++) p[i + 1] = (uint8_t)(((5 - i) * p[0] + i * p[1]) / 5);
        p[6] = 0; p[7] = 255;
    }
    uint64_t bits = 0;
    for (int i = 0; i < 6; i++) bits |= (uint64_t)b[2 + i] << (8 * i);
    for (int i = 0; i < 16; i++) out[i] = p[(bits >> (3 * i)) & 7];
}

static bool CompositeIconPage(CpuTex& t)
{
    if (t.fmt != BF6_FMT_BC5 || t.w <= 0 || t.h <= 0 || t.data.empty()) return false;
    const int bw = (t.w + 3) / 4, bh = (t.h + 3) / 4;
    if ((size_t)bw * (size_t)bh * 16 > t.data.size()) return false;
    std::vector<uint8_t> rgba((size_t)t.w * (size_t)t.h * 4, 255);
    for (int by = 0; by < bh; by++) for (int bx = 0; bx < bw; bx++)
    {
        const uint8_t* block = t.data.data() + ((size_t)by * bw + bx) * 16;
        uint8_t rr[16], gg[16]; DecodeBc4(block, rr); DecodeBc4(block + 8, gg);
        for (int py = 0; py < 4; py++) for (int px = 0; px < 4; px++)
        {
            const int x = bx * 4 + px, y = by * 4 + py;
            if (x >= t.w || y >= t.h) continue;
            const int q = py * 4 + px;
            float z = ((float)rr[q] - 217.f) / 16.f;
            z = (std::max)(0.f, (std::min)(z, 1.f));
            // NumPy's float32 -> uint8 conversion in the Python oracle
            // truncates toward zero.  The value is clamped non-negative, so
            // an ordinary cast is the exact conversion (lroundf was +1 on
            // 720 M4A1 pixels and +2 after two-layer alpha composition).
            const int line = (int)((z * z * (3.f - 2.f * z)) * 255.f);
            const int fill = gg[q] > 127 ? 60 : 0;
            uint8_t* d = rgba.data() + ((size_t)y * t.w + x) * 4;
            d[0] = d[1] = d[2] = 255; d[3] = (uint8_t)(std::max)(line, fill);
        }
    }
    t.data = std::move(rgba);
    t.fmt = BF6_FMT_RGBA8; t.srgb = 0; t.mips = 1;
    return true;
}

// Upload from a payload the worker already copied. No libbf6 call, so this is
// safe to run on the render thread while the worker is reading the next
// weapon.
static ID3D11ShaderResourceView* UploadCpuTex(const CpuTex& ct)
{
    const uint8_t* bytes = ct.borrowed_data ? ct.borrowed_data : ct.data.data();
    const size_t byteCount = ct.borrowed_data ? ct.borrowed_len : ct.data.size();
    if (ct.volume)
    {
        if (!g_dev || !bytes || ct.w <= 0 || ct.h <= 0 || ct.depth <= 0 ||
            ct.mips != 1 || ct.fmt != BF6_FMT_RGB10A2)
            return nullptr;
        const size_t rowBytes = static_cast<size_t>(ct.w) * 4;
        const size_t sliceBytes = rowBytes * static_cast<size_t>(ct.h);
        if (byteCount < sliceBytes * static_cast<size_t>(ct.depth))
            return nullptr;
        D3D11_TEXTURE3D_DESC description{};
        description.Width = static_cast<UINT>(ct.w);
        description.Height = static_cast<UINT>(ct.h);
        description.Depth = static_cast<UINT>(ct.depth);
        description.MipLevels = 1;
        description.Format = DXGI_FORMAT_R10G10B10A2_UNORM;
        description.Usage = D3D11_USAGE_IMMUTABLE;
        description.BindFlags = D3D11_BIND_SHADER_RESOURCE;
        D3D11_SUBRESOURCE_DATA initial{};
        initial.pSysMem = bytes;
        initial.SysMemPitch = static_cast<UINT>(rowBytes);
        initial.SysMemSlicePitch = static_cast<UINT>(sliceBytes);
        ID3D11Texture3D* texture = nullptr;
        if (FAILED(g_dev->CreateTexture3D(
                &description, &initial, &texture)) || !texture)
            return nullptr;
        ID3D11ShaderResourceView* view = nullptr;
        g_dev->CreateShaderResourceView(texture, nullptr, &view);
        texture->Release();
        return view;
    }
    if (ct.cube)
    {
        if (!g_dev || !bytes || ct.slices != 6 || ct.mips != 1 ||
            ct.w <= 0 || ct.h <= 0 || ct.fmt != BF6_FMT_RGBA16F)
            return nullptr;
        const size_t faceBytes = static_cast<size_t>(ct.w) * ct.h * 8;
        if (byteCount < faceBytes * 6) return nullptr;
        D3D11_TEXTURE2D_DESC description{};
        description.Width = static_cast<UINT>(ct.w);
        description.Height = static_cast<UINT>(ct.h);
        int generatedMipCount = 1;
        for (int edge = (std::max)(ct.w, ct.h); edge > 1; edge >>= 1)
            ++generatedMipCount;
        description.MipLevels = 0;
        description.ArraySize = 6;
        description.Format = DXGI_FORMAT_R16G16B16A16_FLOAT;
        description.SampleDesc.Count = 1;
        description.Usage = D3D11_USAGE_DEFAULT;
        description.BindFlags = D3D11_BIND_SHADER_RESOURCE |
                                D3D11_BIND_RENDER_TARGET;
        description.MiscFlags = D3D11_RESOURCE_MISC_TEXTURECUBE |
                                D3D11_RESOURCE_MISC_GENERATE_MIPS;
        ID3D11Texture2D* texture = nullptr;
        if (FAILED(g_dev->CreateTexture2D(
                &description, nullptr, &texture)) || !texture)
            return nullptr;
        for (int face = 0; face < 6; ++face)
            g_ctx->UpdateSubresource(
                texture,
                D3D11CalcSubresource(0, face, generatedMipCount),
                nullptr, bytes + faceBytes * face,
                static_cast<UINT>(ct.w * 8),
                static_cast<UINT>(faceBytes));
        D3D11_SHADER_RESOURCE_VIEW_DESC viewDescription{};
        viewDescription.Format = description.Format;
        viewDescription.ViewDimension = D3D11_SRV_DIMENSION_TEXTURECUBE;
        viewDescription.TextureCube.MipLevels = static_cast<UINT>(-1);
        ID3D11ShaderResourceView* view = nullptr;
        g_dev->CreateShaderResourceView(
            texture, &viewDescription, &view);
        if (view) g_ctx->GenerateMips(view);
        texture->Release();
        return view;
    }
    bf6_texture t{};
    t.width = ct.w; t.height = ct.h; t.mip_count = ct.mips;
    t.format = (bf6_fmt)ct.fmt; t.srgb = ct.srgb;
    t.data = bytes; t.data_len = (int32_t)byteCount;
    return UploadTextureUncached(&t);
}

static GpuMesh UploadCpuPart(CpuPart&& cp)
{
    GpuMesh gm;
    gm.name = cp.name;
    gm.lo = XMFLOAT3(cp.lo[0], cp.lo[1], cp.lo[2]);
    gm.hi = XMFLOAT3(cp.hi[0], cp.hi[1], cp.hi[2]);
    for (CpuSection& cs : cp.sections)
    {
        if (cs.verts.empty() || cs.idx.empty()) continue;
        GpuSection g;
        g.index_count = (UINT)cs.idx.size();
        D3D11_BUFFER_DESC bd{};
        bd.ByteWidth = (UINT)(cs.verts.size() * sizeof(Vtx));
        bd.Usage = cs.bind_verts.empty()
            ? D3D11_USAGE_IMMUTABLE : D3D11_USAGE_DYNAMIC;
        bd.BindFlags = D3D11_BIND_VERTEX_BUFFER;
        bd.CPUAccessFlags = cs.bind_verts.empty()
            ? 0 : D3D11_CPU_ACCESS_WRITE;
        D3D11_SUBRESOURCE_DATA sr{}; sr.pSysMem = cs.verts.data();
        if (FAILED(g_dev->CreateBuffer(&bd, &sr, &g.vb))) continue;
        bd.ByteWidth = (UINT)(cs.idx.size() * sizeof(uint32_t));
        bd.Usage = D3D11_USAGE_IMMUTABLE;
        bd.BindFlags = D3D11_BIND_INDEX_BUFFER;
        bd.CPUAccessFlags = 0;
        sr.pSysMem = cs.idx.data();
        if (FAILED(g_dev->CreateBuffer(&bd, &sr, &g.ib))) { g.vb->Release(); continue; }
        for (int ti = 0; ti < 9; ++ti) {
            if (cs.tex[ti] < 0) continue;
            auto found = g_texCache.find(cs.tex[ti]);
            if (found != g_texCache.end()) g.srv[ti] = found->second;
        }
        g.base_color = XMFLOAT4(cs.base_color[0], cs.base_color[1],
                                cs.base_color[2], cs.base_color[3]);
        g.material = XMFLOAT4(cs.roughness, cs.metallic,
                              cs.normal_is_nsm ? 1.f : 0.f,
                              g.srv[0] ? 1.f : 0.f);
        g.emissive = XMFLOAT4(cs.emissive[0], cs.emissive[1],
                              cs.emissive[2], 0.f);
        g.render_flags = XMFLOAT4(cs.alpha_test ? 1.f : 0.f,
                                  cs.alpha_from_albedo ? 1.f : 0.f,
                                  g.srv[3] ? 1.f : 0.f,
                                  cs.translucent ? 1.f : 0.f);
        g.shader_flags = XMFLOAT4(cs.shader_family == 1 ? 1.f : 0.f,
                                  0.f, 0.f, 0.f);
        g.bind_verts = std::move(cs.bind_verts);
        g.animated_verts.resize(g.bind_verts.size());
        g.skin_bones = std::move(cs.skin_bones);
        g.skin_weights = std::move(cs.skin_weights);
        g.skin_influences = cs.skin_influences;
        gm.verts += (long long)cs.verts.size();
        gm.tris += (long long)(cs.idx.size() / 3);
        gm.sections.push_back(std::move(g));
    }
    gm.animation_skin_frames = std::move(cp.animation_skin_frames);
    gm.animation_frame_count = cp.animation_frame_count;
    gm.animation_bone_count = cp.animation_bone_count;
    gm.animation_rig_bone_count = cp.animation_rig_bone_count;
    gm.animation_fps = cp.animation_fps;
    gm.animation_rigid = cp.animation_rigid;
    gm.animation_post_transform_active =
        cp.animation_post_transform_active;
    std::copy(cp.animation_post_transform,
              cp.animation_post_transform + 12,
              gm.animation_post_transform);
    std::copy(cp.presentation_transform, cp.presentation_transform + 12,
              gm.presentation_transform);
    gm.presentation_ground_offset = cp.presentation_ground_offset;
    return gm;
}

static void UpdateSoldierAnimationBuffers()
{
    if (!g_showScenePresentation ||
        g_scenePresentationKind != ScenePresentationKind::Soldier ||
        g_parts.empty())
        return;
    const char* fixedFrame = std::getenv("BF6_DIAGNOSTIC_SOLDIER_FRAME");
    const double elapsed = (std::max)(0.0,
        ImGui::GetTime() - g_sceneAnimationStart);
    // The four class clips have different authored lengths. Track a common
    // 60 Hz presentation tick, then wrap each mesh by its own clip instead of
    // dropping every shorter actor once the longest clip passes its end.
    const int animationTick = fixedFrame && fixedFrame[0]
        ? (std::max)(0, std::atoi(fixedFrame))
        : (int)(elapsed * 60.0);
    if (animationTick == g_sceneAnimationFrame) return;

    for (GpuMesh& mesh : g_parts)
    {
        if (mesh.animation_frame_count <= 0 || mesh.animation_fps <= 0.f ||
            mesh.animation_bone_count <= 0 ||
            mesh.animation_skin_frames.size() <
                (size_t)mesh.animation_frame_count *
                (size_t)mesh.animation_bone_count)
            continue;
        const int frame = fixedFrame && fixedFrame[0]
            ? (std::min)(animationTick, mesh.animation_frame_count - 1)
            : (int)(elapsed * mesh.animation_fps) % mesh.animation_frame_count;
        const bf6_bone_xform* skin = mesh.animation_skin_frames.data() +
            (size_t)frame * mesh.animation_bone_count;
        for (GpuSection& section : mesh.sections)
        {
            if (!section.vb || section.bind_verts.empty())
                continue;
            if (!mesh.animation_rigid &&
                (section.skin_influences <= 0 ||
                 section.skin_bones.size() != section.skin_weights.size() ||
                 section.skin_bones.size() != section.bind_verts.size() *
                    (size_t)section.skin_influences))
                continue;
            section.animated_verts.resize(section.bind_verts.size());
            for (size_t vertex = 0; vertex < section.bind_verts.size(); ++vertex)
            {
                const Vtx& source = section.bind_verts[vertex];
                Vtx& out = section.animated_verts[vertex];
                out = source;
                if (mesh.animation_rigid)
                {
                    const float* matrix = skin[0].m;
                    for (int column = 0; column < 3; ++column)
                    {
                        out.p[column] = source.p[0] * matrix[column] +
                            source.p[1] * matrix[3 + column] +
                            source.p[2] * matrix[6 + column] +
                            matrix[9 + column];
                        out.n[column] = source.n[0] * matrix[column] +
                            source.n[1] * matrix[3 + column] +
                            source.n[2] * matrix[6 + column];
                        out.tangent[column] =
                            source.tangent[0] * matrix[column] +
                            source.tangent[1] * matrix[3 + column] +
                            source.tangent[2] * matrix[6 + column];
                    }
                    continue;
                }
                out.p[0] = out.p[1] = out.p[2] = 0.f;
                out.n[0] = out.n[1] = out.n[2] = 0.f;
                out.tangent[0] = out.tangent[1] = out.tangent[2] = 0.f;
                float accepted = 0.f;
                for (int lane = 0; lane < section.skin_influences; ++lane)
                {
                    const size_t influence = vertex *
                        (size_t)section.skin_influences + (size_t)lane;
                    const float weight = section.skin_weights[influence];
                    const uint16_t rawBone = section.skin_bones[influence];
                    const int bone = (rawBone & 0x8000u)
                        ? mesh.animation_rig_bone_count +
                            (int)((rawBone & 0x7fffu) >> 1)
                        : (int)rawBone;
                    if (weight <= 0.f || bone < 0 ||
                        bone >= mesh.animation_bone_count)
                        continue;
                    const float* matrix = skin[bone].m;
                    for (int column = 0; column < 3; ++column)
                    {
                        out.p[column] += weight *
                            (source.p[0] * matrix[column] +
                             source.p[1] * matrix[3 + column] +
                             source.p[2] * matrix[6 + column] +
                             matrix[9 + column]);
                        out.n[column] += weight *
                            (source.n[0] * matrix[column] +
                             source.n[1] * matrix[3 + column] +
                             source.n[2] * matrix[6 + column]);
                        out.tangent[column] += weight *
                            (source.tangent[0] * matrix[column] +
                             source.tangent[1] * matrix[3 + column] +
                             source.tangent[2] * matrix[6 + column]);
                    }
                    accepted += weight;
                }
                if (accepted > 1e-8f)
                {
                    const float reciprocal = 1.f / accepted;
                    for (int column = 0; column < 3; ++column) {
                        out.p[column] *= reciprocal;
                        out.n[column] *= reciprocal;
                        out.tangent[column] *= reciprocal;
                    }
                }
                else out = source;
                if (mesh.animation_post_transform_active)
                {
                    const float* matrix = mesh.animation_post_transform;
                    const float p[3] = { out.p[0], out.p[1], out.p[2] };
                    const float n[3] = { out.n[0], out.n[1], out.n[2] };
                    const float t[3] = {
                        out.tangent[0], out.tangent[1], out.tangent[2] };
                    for (int column = 0; column < 3; ++column)
                    {
                        out.p[column] = p[0] * matrix[column] +
                            p[1] * matrix[3 + column] +
                            p[2] * matrix[6 + column] + matrix[9 + column];
                        out.n[column] = n[0] * matrix[column] +
                            n[1] * matrix[3 + column] +
                            n[2] * matrix[6 + column];
                        out.tangent[column] = t[0] * matrix[column] +
                            t[1] * matrix[3 + column] +
                            t[2] * matrix[6 + column];
                    }
                }
            }
            D3D11_MAPPED_SUBRESOURCE mapped{};
            if (SUCCEEDED(g_ctx->Map(section.vb, 0,
                    D3D11_MAP_WRITE_DISCARD, 0, &mapped)))
            {
                std::memcpy(mapped.pData, section.animated_verts.data(),
                    section.animated_verts.size() * sizeof(Vtx));
                g_ctx->Unmap(section.vb, 0);
            }
        }
    }
    g_sceneAnimationFrame = animationTick;
}

static std::mutex              g_jobLock;
static std::condition_variable g_jobCv;
static std::deque<WeaponRequest> g_jobQueue;    // newest configured weapon wins
static std::deque<std::pair<std::string, std::string>> g_iconQueue; // bare, class
static std::deque<ScenePresentationRequest> g_scenePresentationQueue;
enum class StudioFlavor : int {
    None = 0, Weapon = 1, Soldier = 2, Vehicle = 3
};
static std::atomic<int> g_studioMetadataRequested{
    static_cast<int>(StudioFlavor::None)};
static std::atomic<int> g_studioMetadataLoaded{
    static_cast<int>(StudioFlavor::None)};
static std::shared_ptr<CpuWeaponPayload> g_jobResult;
static std::shared_ptr<CpuPackagePayload> g_packageResult;
static std::shared_ptr<CpuScenePresentationPayload> g_scenePresentationResult;
static std::vector<CpuIconSet> g_iconResults;
static std::string             g_jobResultFor;
static std::string             g_scenePresentationRequestedKey;
static std::string             g_scenePresentationLoadedKey;
static bool                    g_jobHasResult = false;
static bool                    g_jobBusy = false;

static void RequestStudioMetadata(StudioFlavor flavor)
{
    if (flavor == StudioFlavor::None ||
        g_studioMetadataLoaded.load(std::memory_order_acquire) ==
            static_cast<int>(flavor))
        return;
    g_studioMetadataRequested.store(
        static_cast<int>(flavor), std::memory_order_release);
    g_jobCv.notify_one();
}

// Worker-owned, demand-filled payload cache.  The previous implementation
// decoded all 185 roster entries before readiness, including 76 entries with
// no geometry.  That consumed 47.5 seconds and about 3 GiB merely to turn a
// normal 0.1-0.9 second selection into a cache hit.
static std::map<std::string, std::shared_ptr<CpuWeaponPayload>> g_cpuWeaponCache;
static std::deque<std::string> g_cpuWeaponLru;
static const size_t kCpuWeaponCacheMax = 32;
// Immutable after the roster is published.  Kept separate from g_armory so
// the worker never races the render thread while the latter applies results.
static std::map<std::string, std::vector<std::string>> g_costEbxByWeapon;
// Exact root-level customization stubs retained from the one complete EBX
// name-table walk that already builds g_armory. Model selection can then read
// the selected stub directly instead of repeating that multi-second global
// enumeration on every cold card selection.
static std::map<std::string, std::vector<std::string>>
    g_modelDefinitionStubsByArmoryKey;
static bf6_weapon_base_stats g_currentStats{};
static bool g_hasCurrentStats = false;
static armory_ui::WeaponInfo g_currentUi;
// The selected payload may legitimately contain presentation text/icon data
// but no standalone mesh (several gadget equipment rows do).  Keep completion
// separate from g_assembled so route readiness does not wait forever for art
// the installed record never supplied.
static std::string g_loadedWeaponPayloadKey;
static std::vector<armory_ui::PackageRow> g_currentPackages;
// Runtime selection for the package presenter.  The package catalogue remains
// sourced from bf6_weapon_packages; this only records which authored row the
// user selected while navigating the live menu.
static std::string g_selectedPackageKey;
// One-shot route captures enter Customize/SlotPicker without clicking the
// preceding package card.  Seed that missing transition from the exact
// installed selected package once its asynchronous rows arrive.  Interactive
// navigation already performs this transition in ActivateFrontendFocus.
static bool g_seedCapturedPackageState = false;

static void SetCurrentPackages(const std::vector<armory_ui::PackageRow>& packages)
{
    g_currentPackages = packages;
    const auto selected = std::find_if(
        g_currentPackages.begin(), g_currentPackages.end(),
        [](const armory_ui::PackageRow& package) {
            return package.key == g_selectedPackageKey;
        });
    if (selected == g_currentPackages.end())
    {
        const auto factory = std::find_if(
            g_currentPackages.begin(), g_currentPackages.end(),
            [](const armory_ui::PackageRow& package) {
                return package.ordinal == 0;
            });
        g_selectedPackageKey = factory != g_currentPackages.end()
            ? factory->key
            : (g_currentPackages.empty() ? std::string()
                                         : g_currentPackages.front().key);
    }
    if (g_seedCapturedPackageState)
    {
        const auto package = std::find_if(
            g_currentPackages.begin(), g_currentPackages.end(),
            [](const armory_ui::PackageRow& candidate) {
                return candidate.key == g_selectedPackageKey;
            });
        if (package != g_currentPackages.end() &&
            package->has_gameplay_config)
        {
            g_ui.factory_package = package->ordinal == 0;
            g_ui.fitted.by_slot.clear();
            for (const auto& fit : package->fits)
                if (!fit.second.empty())
                    g_ui.fitted.by_slot[fit.first] = fit.second;
            g_seedCapturedPackageState = false;
            std::fprintf(stderr,
                "capture package state: %s fits=%zu point-cost=%d\n",
                package->key.c_str(), g_ui.fitted.by_slot.size(),
                armory_ui::spent(g_armory, g_ui));
        }
    }
}

static void RequestWeapon(const std::string& bare, const armory_ui::Fitted* fitted = nullptr)
{
    WeaponRequest request; request.weapon = bare;
    request.factory = fitted == nullptr;
    if (fitted)
        for (const auto& fit : fitted->by_slot)
            if (!fit.second.empty()) request.fits.push_back(fit);
    std::lock_guard<std::mutex> k(g_jobLock);
    g_jobQueue.clear();               // only the newest request matters
    g_jobQueue.push_back(std::move(request));
    g_jobCv.notify_one();
}

static void RequestWeaponPackage(const std::string& weapon,
                                 const armory_ui::PackageRow& package)
{
    if (!package.has_gameplay_config) return;
    WeaponRequest request;
    request.weapon = weapon;
    request.package_key = package.unlock_asset;
    request.package_skin = package.skin;
    request.factory = false;
    request.fits = package.fits;
    std::lock_guard<std::mutex> k(g_jobLock);
    g_jobQueue.clear();
    g_jobQueue.push_back(std::move(request));
    g_jobCv.notify_one();
}

static void RequestScenePresentation(ScenePresentationKind kind, int selection)
{
    ScenePresentationRequest request;
    request.kind = kind;
    request.selection = selection;
    request.class_loadout = kind == ScenePresentationKind::Soldier &&
        g_loadoutRoutePage == LoadoutRoutePage::ClassSelect;
    if (kind == ScenePresentationKind::Soldier && !request.class_loadout)
        request.weapon = g_loadoutEquipped[(size_t)(std::max)(0, (std::min)(
            selection, 3))][(size_t)LoadoutSlot::Primary];
    const std::string key = request.key();
    std::lock_guard<std::mutex> lock(g_jobLock);
    if (key == g_scenePresentationRequestedKey) return;
    g_scenePresentationRequestedKey = key;
    g_scenePresentationQueue.clear();
    g_scenePresentationQueue.push_back(std::move(request));
    g_jobCv.notify_one();
}

static std::string AlnumLower(const std::string& s);

static const IconSet* IconsFor(const std::string& bare, const std::string& cls)
{
    auto it = g_icons.find(bare);
    if (it != g_icons.end()) return &it->second;
    IconSet pending; pending.cls = cls; pending.loading = true;
    auto ins = g_icons.emplace(bare, std::move(pending));
    {
        std::lock_guard<std::mutex> k(g_jobLock);
        g_iconQueue.emplace_back(bare, cls);
    }
    g_jobCv.notify_one();
    return &ins.first->second;
}

static bool DrawExactComposedEquipmentIcon(
    ImDrawList* drawList, const std::string& key,
    float x, float y, float width, float height, ImU32 tint)
{
    if (!drawList || key.empty()) return false;
    const size_t slash = key.find_last_of('/');
    if (slash == std::string::npos || slash + 1 >= key.size()) return false;
    const std::string cls = key.substr(0, slash);
    const std::string bare = key.substr(slash + 1);
    const IconSet* set = IconsFor(bare, cls);
    if (!set || set->sprites.size() != 1 || set->pages.empty()) return false;
    const IconSprite& sprite = set->sprites.front();
    if (!sprite.placed || sprite.page < 0 ||
        sprite.page >= static_cast<int>(set->pages.size()) ||
        sprite.name.find("_archetype_icon") == std::string::npos)
        return false;
    ID3D11ShaderResourceView* page = set->pages[(size_t)sprite.page];
    if (!page) return false;
    const float scale = (std::min)(
        width / (std::max)(sprite.size[0], 1.f),
        height / (std::max)(sprite.size[1], 1.f));
    const float drawWidth = sprite.size[0] * scale;
    const float drawHeight = sprite.size[1] * scale;
    const float dx = x + (width - drawWidth) * .5f;
    const float dy = y + (height - drawHeight) * .5f;
    drawList->AddImage((ImTextureID)page, ImVec2(dx, dy),
        ImVec2(dx + drawWidth, dy + drawHeight),
        ImVec2(sprite.uv[0], sprite.uv[1]),
        ImVec2(sprite.uv[2], sprite.uv[3]), tint);
    return true;
}

static bool DrawAtlasEquipmentIcon(
    ImDrawList* drawList, const VehicleArchetypeIcon& icon,
    float x, float y, float width, float height, ImU32 tint)
{
    if (!drawList || icon.texture_id < 0) return false;
    const auto texture = g_texCache.find(icon.texture_id);
    if (texture == g_texCache.end() || !texture->second) return false;
    const float canvasWidth = (std::max)(icon.canvas[0], 1.f);
    const float canvasHeight = (std::max)(icon.canvas[1], 1.f);
    const float scale = (std::min)(width / canvasWidth, height / canvasHeight);
    const float originX = x + (width - canvasWidth * scale) * .5f;
    const float originY = y + (height - canvasHeight * scale) * .5f;
    const float left = originX + icon.placement[0] * scale;
    const float top = originY + icon.placement[1] * scale;
    drawList->AddImage((ImTextureID)texture->second,
        ImVec2(left, top),
        ImVec2(left + icon.size[0] * scale,
               top + icon.size[1] * scale),
        ImVec2(icon.uv[0], icon.uv[1]),
        ImVec2(icon.uv[2], icon.uv[3]), tint);
    return true;
}

// The slot is part of the key because the catalogue is keyed by slot too - the
// same display name can appear in more than one slot, and the atlas differs.
static const IconSet* IconsForAttachment(const std::string& slot,
                                         const std::string& token)
{
    return IconsFor("__attachment__" + slot + "_" + AlnumLower(token), token);
}

// The camera FRAMES A TARGET rather than jumping to it. The armory never cuts:
// selecting a slot glides the camera onto that part and back out again, which
// is most of why it reads as one continuous scene. Target is a centre plus a
// distance; the live camera eases toward it.
static XMFLOAT3 g_focus   = XMFLOAT3(0, 0, 0);   // where we are looking
static XMFLOAT3 g_focusTo = XMFLOAT3(0, 0, 0);   // where we want to look
static float    g_distTo  = 1.0f;

// Frame the whole assembled weapon: the union of every loaded part.
static void FocusWholeWeapon()
{
    if (g_mesh.hi.x <= g_mesh.lo.x) return;
    g_focusTo = XMFLOAT3((g_mesh.lo.x + g_mesh.hi.x) * 0.5f,
                         (g_mesh.lo.y + g_mesh.hi.y) * 0.5f,
                         (g_mesh.lo.z + g_mesh.hi.z) * 0.5f);
    const float sx = g_mesh.hi.x - g_mesh.lo.x;
    const float sy = g_mesh.hi.y - g_mesh.lo.y;
    const float sz = g_mesh.hi.z - g_mesh.lo.z;
    g_distTo = sqrtf(sx * sx + sy * sy + sz * sz) * 1.75f;
}

// Frame the part that lives in one slot.
//
// The game anchors its per-slot cameras to the slot's own mount BONE
// (Wep_Scope_ATT, Wep_Muzzle_ATT, Wep_MGZ_ATT...). Those bones are decoded but
// not yet exposed across the ABI, so this frames the loaded PART whose mesh
// name matches the slot instead. Same intent, and it uses the part's own
// measured bounds rather than an invented offset - but it is an approximation
// of the authored framing, not the authored framing.
static bool FocusSlot(const std::string& slotCode)
{
    struct Map { const char* code; const char* words; };
    static const Map kMap[] = {
        { "scp", "sight|scope|optic|reflex|holo" }, { "sca", "sight|offset|canted" },
        { "mzl", "muzzle|suppressor|flashhider|brake|comp" },
        { "brl", "barrel" },  { "mag", "magazine|mag|drum" },
        { "btm", "grip|foregrip|bipod|handstop|vertical" },
        { "top", "toprail|rail" }, { "lft", "left|panel" }, { "rgt", "right|light|laser" },
        { "erg", "trigger|stock|ergonomic|buffer" }, { "amo", "magazine|mag" },
    };
    const char* words = nullptr;
    for (const Map& m : kMap) if (slotCode == m.code) { words = m.words; break; }
    if (!words) return false;

    // Split the alternatives and take the first loaded part that matches.
    std::string w(words);
    size_t a = 0;
    while (a <= w.size())
    {
        const size_t b = w.find('|', a);
        const std::string tok = w.substr(a, (b == std::string::npos ? w.size() : b) - a);
        a = (b == std::string::npos) ? w.size() + 1 : b + 1;
        if (tok.empty()) continue;
        for (const GpuMesh& m : g_parts)
        {
            if (m.name.find(tok) == std::string::npos) continue;
            if (m.hi.x <= m.lo.x) continue;
            g_focusTo = XMFLOAT3((m.lo.x + m.hi.x) * 0.5f,
                                 (m.lo.y + m.hi.y) * 0.5f,
                                 (m.lo.z + m.hi.z) * 0.5f);
            const float sx = m.hi.x - m.lo.x, sy = m.hi.y - m.lo.y, sz = m.hi.z - m.lo.z;
            // Keep a floor under it: a tiny part would otherwise pull the
            // camera inside its own geometry.
            g_distTo = (std::max)(sqrtf(sx * sx + sy * sy + sz * sz) * 2.1f, 0.09f);
            return true;
        }
    }
    return false;
}

static std::vector<rime::Screen> g_screens;
// The mounted front-end Rime catalogue and lazy screen payloads are produced
// by the existing libbf6 worker.  No second context or staged screen data is
// used.  Once loaded, the document transfers to the render thread because its
// runtime tick/apply path performs no libbf6 reads.
struct RuntimeUiScreenPayload {
    bf6_ui::ScreenIdentity identity;
    std::shared_ptr<bf6_ui::DirectInstallScreenDocument> document;
    bf6_ui::DirectScreenLoadReport report;
    std::vector<CpuTex> textures;
    uint64_t request_sequence = 0;
    int route_depth = 0;
};
enum class RuntimeUiRouteOperation { Push, Replace, Pop };
struct RuntimeUiRouteRequest {
    RuntimeUiRouteOperation operation = RuntimeUiRouteOperation::Push;
    std::string path;
    uint64_t sequence = 0;
};
static std::mutex g_runtimeUiLock;
static std::vector<bf6_ui::ScreenIdentity> g_runtimeUiCatalogue;
static std::shared_ptr<RuntimeUiScreenPayload> g_runtimeUiPendingScreen;
static std::shared_ptr<bf6_ui::DirectInstallScreenDocument>
    g_runtimeUiActiveDocument;
static std::string g_runtimeUiActivePath;
static uint64_t g_runtimeUiLatestRequest = 0;
static bool g_runtimeUiActiveNeedsApply = false;
static bool g_runtimeUiActiveAnimating = false;
static std::atomic<bool> g_runtimeUiCatalogueReady{false};
static std::atomic<bool> g_runtimeUiScreenPending{false};
static std::atomic<bool> g_runtimeUiNavigationPending{false};
static std::atomic<int> g_runtimeUiRouteDepth{0};
static std::deque<RuntimeUiRouteRequest> g_runtimeUiRequests;
static int g_runtimeUiCatalogueIndex = 0;

static void RequestRuntimeUiScreen(
    const std::string& exactPath,
    RuntimeUiRouteOperation operation = RuntimeUiRouteOperation::Push)
{
    if (exactPath.empty() && operation != RuntimeUiRouteOperation::Pop) return;
    RuntimeUiRouteRequest request;
    request.operation = operation;
    request.path = exactPath;
    {
        std::lock_guard<std::mutex> lock(g_runtimeUiLock);
        request.sequence = ++g_runtimeUiLatestRequest;
    }
    {
        std::lock_guard<std::mutex> lock(g_jobLock);
        g_runtimeUiRequests.clear();
        g_runtimeUiRequests.push_back(std::move(request));
    }
    g_runtimeUiNavigationPending.store(true, std::memory_order_release);
    g_jobCv.notify_one();
}

static bool RequestRuntimeUiBack()
{
    if (!g_runtimeUiCatalogueReady.load(std::memory_order_acquire))
        return false;
    if (g_runtimeUiNavigationPending.load(std::memory_order_acquire))
        return true; // consume Back while a prior transition is transactional
    if (g_runtimeUiRouteDepth.load(std::memory_order_acquire) <= 1)
        return false;
    RequestRuntimeUiScreen({}, RuntimeUiRouteOperation::Pop);
    return true;
}

static bool StepRuntimeUiCatalogue(int delta)
{
    std::string path;
    {
        std::lock_guard<std::mutex> lock(g_runtimeUiLock);
        const int count = static_cast<int>(g_runtimeUiCatalogue.size());
        if (count <= 0) return false;
        g_runtimeUiCatalogueIndex =
            (g_runtimeUiCatalogueIndex + delta % count + count) % count;
        path = g_runtimeUiCatalogue[static_cast<size_t>(
            g_runtimeUiCatalogueIndex)].path;
    }
    RequestRuntimeUiScreen(path, RuntimeUiRouteOperation::Replace);
    return true;
}

