static int MainHeaderPointCostScope(const rime::Screen& screen)
{
    static const std::string kPointCost =
        "common/ui/weapons/widgets/weaponpointcost";
    auto normalized = [](std::string value) {
        for (char& ch : value)
            if (ch >= 'A' && ch <= 'Z') ch = (char)(ch + 32);
        if (value.size() > 4 &&
            value.compare(value.size() - 4, 4, ".ebx") == 0)
            value.resize(value.size() - 4);
        return value;
    };
    int selected = -1;
    std::set<int> candidates;
    for (const rime::Screen::InterfaceTextGraph& graph :
         screen.interface_text_graphs)
    {
        if (normalized(graph.partition) != kPointCost || graph.scope < 0 ||
            (size_t)graph.scope >= screen.elements.size())
            continue;
        candidates.insert(graph.scope);
        int ancestor = graph.scope;
        std::set<int> seen;
        while (ancestor >= 0 &&
               (size_t)ancestor < screen.elements.size() &&
               seen.insert(ancestor).second)
        {
            const rime::Element& element =
                screen.elements[(size_t)ancestor];
            if (element.partition == rime_list::kGridInfoPartition &&
                element.name == "Package Info")
            {
                if (selected >= 0 && selected != graph.scope) return -1;
                selected = graph.scope;
                break;
            }
            ancestor = element.parent;
        }
    }
    if (selected >= 0) return selected;
    return candidates.size() == 1 ? *candidates.begin() : -1;
}

static int RimeScreenForPage(armory_ui::Page page)
{
    const char* wanted = nullptr;
    switch (page)
    {
    case armory_ui::Page::Weapons:
        wanted = "common/ui/weapons/screens/menuweaponscreen";
        break;
    case armory_ui::Page::Packages:
        wanted = "common/ui/weapons/screens/menuweaponpackagesscreen";
        break;
    case armory_ui::Page::Customize:
        wanted = "common/ui/weaponcustomization/screens/weaponattachmentcategoryscreen";
        break;
    case armory_ui::Page::SlotPicker:
        wanted = "common/ui/weapons/screens/weaponattachmentselectionscreen";
        break;
    }
    if (!wanted) return -1;
    for (size_t i = 0; i < g_screens.size(); ++i)
        if (g_screens[i].partition == wanted) return (int)i;
    return -1;
}

static bool SelectFrontendPartition(const char* partition);

static bool SelectArmoryPage(armory_ui::Page page)
{
    const char* partition = nullptr;
    switch (page)
    {
    case armory_ui::Page::Weapons:
        partition = "common/ui/weapons/screens/menuweaponscreen"; break;
    case armory_ui::Page::Packages:
        partition = "common/ui/weapons/screens/menuweaponpackagesscreen"; break;
    case armory_ui::Page::Customize:
        partition = "common/ui/weaponcustomization/screens/weaponattachmentcategoryscreen"; break;
    case armory_ui::Page::SlotPicker:
        partition = "common/ui/weapons/screens/weaponattachmentselectionscreen"; break;
    }
    if (!partition || RimeScreenForPage(page) < 0) return false;
    g_ui.page = page;
    return SelectFrontendPartition(partition);
}

static bool NavigateArmoryBack()
{
    if (!g_showArmory) return false;
    if (g_ui.page == armory_ui::Page::SlotPicker)
    {
        if (!SelectArmoryPage(armory_ui::Page::Customize)) return false;
        FocusWholeWeapon();
        return true;
    }
    if (g_ui.page == armory_ui::Page::Customize)
    {
        if (!SelectArmoryPage(armory_ui::Page::Packages)) return false;
        FocusWholeWeapon();
        return true;
    }
    if (g_ui.page == armory_ui::Page::Packages)
    {
        if (!SelectArmoryPage(armory_ui::Page::Weapons)) return false;
        FocusWholeWeapon();
        return true;
    }
    if (g_ui.page == armory_ui::Page::Weapons &&
        g_loadoutInventoryActive)
    {
        g_loadoutInventoryActive = false;
        if (!SelectFrontendPartition(
                "common/ui/loadout/menu/screens/menuloadoutoverviewscreen"))
            return false;
        g_loadoutRoutePage = LoadoutRoutePage::Overview;
        std::fprintf(stderr,
            "Loadout inventory back -> menuloadoutoverviewscreen "
            "[retained slot provider state]\n");
        return true;
    }
    // Weapons is entered from the exact installed Home LOADOUTS tab in the
    // standalone flow, so its parent is now the installed Home root rather
    // than the old BootFlow fallback.
    return false;
}

static int RimeScreenByPartition(const char* wanted)
{
    if (!wanted || !*wanted) return -1;
    for (size_t i = 0; i < g_screens.size(); ++i)
        if (g_screens[i].partition == wanted) return (int)i;
    return -1;
}

static void SyncFrontendScreenSelection()
{
    if (g_screens.empty()) return;
    g_screenIdx = (std::max)(0, (std::min)(g_screenIdx, (int)g_screens.size() - 1));
    const std::string& partition = g_screens[(size_t)g_screenIdx].partition;
    const bool selectedArmory =
        partition == "common/ui/weapons/screens/menuweaponscreen" ||
        partition == "common/ui/weapons/screens/menuweaponpackagesscreen" ||
        partition == "common/ui/weaponcustomization/screens/weaponattachmentcategoryscreen" ||
        partition == "common/ui/weapons/screens/weaponattachmentselectionscreen";
    g_showArmory = selectedArmory;
    if (partition.find("weaponattachmentcategoryscreen") != std::string::npos)
        g_ui.page = armory_ui::Page::Customize;
    else if (partition.find("weaponattachmentselectionscreen") != std::string::npos)
        g_ui.page = armory_ui::Page::SlotPicker;
    else if (partition.find("menuweaponpackagesscreen") != std::string::npos)
        g_ui.page = armory_ui::Page::Packages;
    else if (selectedArmory)
        g_ui.page = armory_ui::Page::Weapons;

    if (partition ==
            "common/ui/loadout/menu/screens/menuloadoutclassselectscreen")
        g_loadoutRoutePage = LoadoutRoutePage::ClassSelect;
    else if (partition ==
            "common/ui/loadout/menu/screens/menuloadoutoverviewscreen")
        g_loadoutRoutePage = LoadoutRoutePage::Overview;
    else if (partition ==
            "common/ui/loadout/menu/screens/menuloadoutscreen")
        g_loadoutRoutePage = LoadoutRoutePage::Equipment;
    else if (partition ==
            "common/ui/loadout/menu/screens/menuloadoutfieldupgradesscreen")
        g_loadoutRoutePage = LoadoutRoutePage::FieldUpgrades;
    else if (partition ==
            "common/ui/soldier/shared/screens/menucharacterselect_view")
        g_loadoutRoutePage = LoadoutRoutePage::Appearance;
    else if (partition ==
            "common/ui/soldier/shared/screens/menucharactercustomization_view")
        g_loadoutRoutePage = LoadoutRoutePage::CharacterCustomization;
    else if (partition ==
            "common/ui/vehicles/shared/screens/menuvehicle_archetypescreen")
        g_loadoutRoutePage = LoadoutRoutePage::Vehicles;
    else if (partition ==
            "common/ui/vehicles/shared/screens/menuvehicle_loadoutscreen")
        g_loadoutRoutePage = LoadoutRoutePage::VehicleLoadout;
    else if (partition ==
            "common/ui/vehicles/shared/screens/menuvehicle_cosmeticselection")
        g_loadoutRoutePage = LoadoutRoutePage::VehicleCosmetics;
    else if (partition == "common/ui/home/screens/home_screen" ||
             partition == kDisplaySettingsScreen ||
             partition.find("game/glacierflow/flow_mainmenu/ui/screens/"
                            "bootflow") == 0)
    {
        /* This enum selects host-side provider presentation only; the
         * ScreenRouter stack owns navigation. Unknown popup/overlay routes do
         * not erase the underlying loadout presentation state. */
        g_loadoutRoutePage = LoadoutRoutePage::None;
        g_loadoutInventoryActive = false;
    }
}

static bool SelectFrontendPartition(const char* partition)
{
    if (!partition || !*partition) return false;
    const bool catalogueReady =
        g_runtimeUiCatalogueReady.load(std::memory_order_acquire);
    bool installedRuntimeScreen = false;
    if (catalogueReady)
    {
        std::lock_guard<std::mutex> lock(g_runtimeUiLock);
        installedRuntimeScreen = std::any_of(
            g_runtimeUiCatalogue.begin(), g_runtimeUiCatalogue.end(),
            [partition](const bf6_ui::ScreenIdentity& identity) {
                return identity.path == partition;
            });
    }

    const int screen = RimeScreenByPartition(partition);
    if (screen < 0)
    {
        if (!catalogueReady || !installedRuntimeScreen) return false;
        RequestRuntimeUiScreen(partition);
        return true;
    }
    if (catalogueReady && installedRuntimeScreen)
    {
        RequestRuntimeUiScreen(partition, RuntimeUiRouteOperation::Push);
        return true;
    }
    g_screenIdx = screen;
    SyncFrontendScreenSelection();
    g_rimeBuiltFor = -1;

    // Startup roots may already be present in g_screens, but that decoded
    // tree has no retained executable graph.  Once current-install discovery
    // is ready, request the corresponding document even for those roots.
    if (g_runtimeUiActivePath != partition)
    {
        g_runtimeUiActiveDocument.reset();
        g_runtimeUiActivePath.clear();
        g_runtimeUiActiveNeedsApply = false;
        g_runtimeUiActiveAnimating = false;
    }
    if (installedRuntimeScreen) RequestRuntimeUiScreen(partition);
    return true;
}

