struct StartPromptPatternRead {
    std::string pattern;
    int candidates = 0;
    int fake_partition_control = 0;
};

/* The start action's visible caption is a CheckedLocalizedString source in
 * the installed bootflow_startbutton graph, not RawText on Prompt Label.
 * Select the sole localized pattern that declares the SingleKeyIcon format
 * argument.  The physical icon itself is resolved independently from the
 * current PC input map, so the ordinary formatter can omit that argument and
 * retain the authored trailing caption. */
static StartPromptPatternRead ReadStartPromptPattern(bf6_ctx* context)
{
    StartPromptPatternRead result;
    if (!context) return result;
    static constexpr const char* kPartition =
        "common/ui/bootflow/widgets/bootflow_startbutton";
    const int count = bf6_rime_string_arguments(context, kPartition,
                                                 nullptr, 0);
    if (count > 0)
    {
        std::vector<bf6_rime_string_argument> arguments(
            static_cast<size_t>(count));
        if (bf6_rime_string_arguments(context, kPartition,
                                      arguments.data(), count) == count)
        {
            std::set<int32_t> instances;
            for (const bf6_rime_string_argument& argument : arguments)
                instances.insert(argument.instance);
            for (int32_t instance : instances)
            {
                const uint32_t sid = bf6_rime_string_entity(
                    context, kPartition, instance);
                const char* localized = sid
                    ? bf6_localized_string(context, sid) : nullptr;
                if (!localized ||
                    std::strstr(localized, ":input:SingleKeyIcon}") == nullptr)
                    continue;
                ++result.candidates;
                result.pattern = localized;
            }
        }
    }
    if (result.candidates != 1) result.pattern.clear();
    result.fake_partition_control = bf6_rime_string_arguments(
        context, "common/ui/__control__/not_a_real_startbutton", nullptr, 0);
    return result;
}

// Resolve the paint state selected by the installed start screen's host.
//
// The EBX tree owns the 240x48 boxes and shape geometry.  CB_ColorLogic owns
// the colours: the Options branch selects FE-Neutral for both layers and the
// install's Alpha50/Alpha25 values for Base/Primary.  Those outputs used to be
// discarded because the retained tree correctly marked them runtime-bound,
// leaving only the prompt label.  The start host also gives its sole action
// keyboard focus, selecting the PC focus-border branch.  Keep this gated to
// the exact installed prefab chain; the fabricated root name passed by the
// caller is the adjacent negative control.
static StartButtonPaintSelection SelectStartButtonPaint(
    std::vector<rime::Element>& elements, const char* owner_name,
    bool select_focus = true, bool allow_start_icon = true)
{
    StartButtonPaintSelection result;
    if (!owner_name || !*owner_name) return result;

    static constexpr const char* kFillPartition =
        "common/ui/componentlibrary/shared/visual/cb_fillvisual";
    static constexpr const char* kFocusPartition =
        "common/ui/componentlibrary/components/borders/cl_border_focus";
    static constexpr const char* kPromptPartition =
        "common/ui/componentlibrary/shared/inputaction/cb_fe_inputactionlabel_base";

    for (size_t owner = 0; owner < elements.size(); ++owner)
    {
        // Expanded widget instances retain the authored root name, while the
        // partition/reference fields belong to the containing screen after
        // flattening. Matching the latter silently selected no subtree. The
        // flattened tree's parent links, rather than depth transitions, are
        // authoritative for subtree membership.
        if (elements[owner].name != owner_name)
            continue;
        auto beneathOwner = [&](size_t index) {
            int parent = elements[index].parent;
            for (int guard = 0;
                 parent >= 0 && parent < static_cast<int>(elements.size()) &&
                 guard < 64;
                 ++guard)
            {
                if (parent == static_cast<int>(owner)) return true;
                parent = elements[static_cast<size_t>(parent)].parent;
            }
            return false;
        };

        // Do not depend on the armory palette bootstrap: the boot-flow graph
        // carries the same current-install values in resolved sibling rows.
        // BorderGlow is FE-Neutral/Alpha25 and BlendBlackFill is Alpha50.
        // Requiring both is fail-closed and keeps this paint path raw-data
        // driven even when the unrelated armory palette is unavailable.
        uint32_t neutralRgb = 0;
        float alpha25 = 0.f;
        float alpha50 = 0.f;
        bool haveNeutral = false;
        bool haveAlpha25 = false;
        bool haveAlpha50 = false;
        for (size_t probe = owner + 1; probe < elements.size(); ++probe)
        {
            if (!beneathOwner(probe)) continue;
            const rime::Element& source = elements[probe];
            if (source.partition == kFocusPartition &&
                source.name == "PCBorder" &&
                source.color_source == BF6_RIME_COLOR_PALETTE)
            {
                neutralRgb = source.color_rgb;
                haveNeutral = true;
            }
            else if (source.partition == kFocusPartition &&
                     source.name == "BorderGlow" && source.alpha > 0.f)
            {
                alpha25 = source.alpha;
                haveAlpha25 = true;
            }
            else if (source.name == "BlendBlackFill" && source.alpha > 0.f)
            {
                alpha50 = source.alpha;
                haveAlpha50 = true;
            }
        }
        const bool havePaint = haveNeutral && haveAlpha25 && haveAlpha50;

        for (size_t index = owner + 1; index < elements.size(); ++index)
        {
            if (!beneathOwner(index)) continue;
            rime::Element& element = elements[index];
            auto directParentNamed = [&](const char* name) {
                return element.parent >= 0 &&
                    element.parent < static_cast<int>(elements.size()) &&
                    elements[static_cast<size_t>(element.parent)].name == name;
            };
            const bool commitSpaceIcon = allow_start_icon &&
                g_startUsesSpace.load(std::memory_order_acquire) &&
                g_startSpaceTextureId.load(std::memory_order_acquire) !=
                    kMissingStartSpaceTexture;

            if (element.name == "CLB_FillVisual" && havePaint)
            {
                element.solved = true;
                element.visible = true;
                element.runtime_visibility_unresolved = false;
                ++result.fill_containers;
            }
            else if (element.partition == kFillPartition &&
                (element.name == "BaseFill" || element.name == "PrimaryFill") &&
                havePaint)
            {
                element.solved = true;
                element.visible = true;
                element.color_rgb = neutralRgb;
                element.color_name = "FE-Neutral";
                element.color_source = BF6_RIME_COLOR_PALETTE;
                element.runtime_color_unresolved = false;
                element.runtime_visibility_unresolved = false;
                element.runtime_alpha_unresolved = false;
                if (element.name == "BaseFill")
                {
                    element.alpha = alpha50;
                    ++result.base_fills;
                }
                else
                {
                    element.alpha = alpha25;
                    ++result.primary_fills;
                }
            }
            else if (select_focus &&
                     element.partition == kFocusPartition &&
                     element.name == "PCBorder")
            {
                element.solved = true;
                element.visible = true;
                element.alpha = 1.f;
                element.runtime_state = 2;
                element.runtime_visibility_unresolved = false;
                element.runtime_alpha_unresolved = false;
                ++result.pc_focus_borders;
            }
            else if (element.name == "CL_Border_Button_Thin" && havePaint)
            {
                element.solved = true;
                element.visible = true;
                element.runtime_visibility_unresolved = false;
            }
            else if (element.name == "RimeBorder" &&
                     directParentNamed("CL_Border_Button_Thin") && havePaint)
            {
                element.solved = true;
                element.visible = true;
                element.alpha = 1.f;
                element.color_rgb = neutralRgb;
                element.color_name = "FE-Neutral";
                element.color_source = BF6_RIME_COLOR_PALETTE;
                element.runtime_color_unresolved = false;
                element.runtime_visibility_unresolved = false;
                element.runtime_alpha_unresolved = false;
                ++result.idle_borders;
            }
            else if (commitSpaceIcon &&
                     ((element.name == "[Container] TextIcon" &&
                       directParentNamed("PrimaryIcon")) ||
                      element.name == "CL_HUD_VectorShape_PlusShape" ||
                      element.name == "SecondaryIcon"))
            {
                // CB_FE_InputIcon_Combo carries text, primary, plus, and
                // secondary branches. SingleKeyIcon selects only the primary
                // image branch; leaving the alternative text-icon branch
                // active paints its 256x256 backing shape over the button.
                element.solved = false;
                element.visible = false;
                element.runtime_visibility_unresolved = false;
            }
            else if (commitSpaceIcon &&
                     (element.name == "CL_FE_InputActionIcon" ||
                      element.name == "CB_FE_InputIcon_Combo" ||
                      (element.name == "RimeStackContainer" &&
                       directParentNamed("CB_FE_InputIcon_Combo")) ||
                      element.name == "PrimaryIcon"))
            {
                element.solved = true;
                element.visible = true;
                element.runtime_visibility_unresolved = false;
            }
            else if (commitSpaceIcon &&
                     element.name == "[SVG] IconTexture" &&
                     directParentNamed("PrimaryIcon"))
            {
                element.solved = true;
                element.visible = true;
                element.alpha = 1.f;
                element.color_rgb = neutralRgb;
                element.color_name = "FE-Neutral";
                element.color_source = BF6_RIME_COLOR_PALETTE;
                element.texture_id =
                    g_startSpaceTextureId.load(std::memory_order_relaxed);
                element.image_asset = kStartSpaceIconPath;
                element.runtime_color_unresolved = false;
                element.runtime_visibility_unresolved = false;
                element.runtime_alpha_unresolved = false;
                ++result.input_icons;
            }
            else if (element.partition == kPromptPartition &&
                     element.name == "DebugFill")
            {
                element.visible = false;
                element.runtime_visibility_unresolved = false;
                ++result.hidden_debug_fills;
            }
            else if (element.partition == kPromptPartition &&
                     element.name == "Prompt Label")
            {
                // The parent graph owns this localized pattern; the expanded
                // child label has no RawText of its own.  Its missing dynamic
                // format argument intentionally collapses to empty while the
                // exact SVG branch above owns the physical Space icon.
                if (element.text.empty() && !g_startPromptPattern.empty())
                    element.text = g_startPromptPattern;
                ++result.prompt_labels;
            }
        }
    }
    return result;
}

static StartIdleVisualSelection SelectStartIdleVisual(
    std::vector<rime::Element>& elements, const char* variant_name)
{
    StartIdleVisualSelection result;
    if (!variant_name || !*variant_name) return result;
    static constexpr const char* kStartButtonPartition =
        "common/ui/bootflow/widgets/bootflow_startbutton";
    for (size_t root = 0; root < elements.size(); ++root)
    {
        rime::Element& variant = elements[root];
        if (variant.partition != kStartButtonPartition ||
            variant.name != variant_name)
            continue;
        ++result.containers;
        variant.visible = false;
        variant.runtime_visibility_unresolved = false;
        ++result.hidden_rows;
        for (size_t child = root + 1; child < elements.size(); ++child)
        {
            int parent = elements[child].parent;
            bool beneath = false;
            for (int guard = 0;
                 parent >= 0 && parent < static_cast<int>(elements.size()) &&
                 guard < 64;
                 ++guard)
            {
                if (parent == static_cast<int>(root)) {
                    beneath = true;
                    break;
                }
                parent = elements[static_cast<size_t>(parent)].parent;
            }
            if (!beneath) continue;
            elements[child].visible = false;
            elements[child].runtime_visibility_unresolved = false;
            ++result.hidden_rows;
        }
    }
    return result;
}

struct StartCopyrightSelection {
    int candidates = 0;
    int applied = 0;
};

/* Commit the presented value of the installed start screen's first copyright
 * line.  The raw document deliberately authors this label at Alpha=0.  Its
 * ScreenEnabled event drives CompareBool instance 25, whose OnTrue selects
 * the InterfaceDescriptor's authored float 1 on SelectFloat instance 20 and
 * resets FloatInterpolator instance 32; that interpolator's Out is wired to
 * this label's Alpha.  The standalone host has already reached that presented
 * state when it publishes the document, but it does not yet dispatch generic
 * SelectFloat/FloatInterpolator events.  Keep the bridge fail-closed to the
 * exact installed partition, label name, StringId, and direct parent. */
static StartCopyrightSelection SelectStartPresentedCopyright(
    rime::Screen& screen, const char* string_id, bool commit)
{
    StartCopyrightSelection result;
    static constexpr const char* kStart =
        "game/glacierflow/flow_mainmenu/ui/screens/bootflowstartscreen";
    if (screen.partition != kStart || !string_id || !*string_id)
        return result;

    for (size_t index = 0; index < screen.elements.size(); ++index)
    {
        rime::Element& element = screen.elements[index];
        if (element.partition != kStart || element.kind != rime::Kind::Label ||
            element.name != "CopyrightText" ||
            element.text_string_id != string_id || element.text.empty() ||
            element.parent < 0 ||
            element.parent >= static_cast<int>(screen.elements.size()) ||
            screen.elements[static_cast<size_t>(element.parent)].name !=
                "CopyrightText")
            continue;
        ++result.candidates;
        if (commit)
        {
            element.alpha = 1.f;
            element.runtime_alpha_unresolved = false;
            ++result.applied;
        }
    }
    return result;
}

struct AuthoredTimelineApplyReport {
    int tracks = 0;
    int keys = 0;
    int alpha_targets = 0;
    int applied = 0;
    int ambiguous = 0;
    int mutated_target_matches = 0;
};

/* The standalone start host has completed its local boot/mount work when it
 * publishes this screen.  In the installed graph that ready event plays a
 * TimelineEntity whose FloatTrack ends at Alpha=1.  Consume the exact track
 * and property wire instead of forcing the widget (or its children) visible.
 *
 * This is intentionally narrow until the event dispatcher can activate an
 * arbitrary timeline. Applying every timeline just because it exists would
 * make unopened/hovered/closing states play at once. */
static AuthoredTimelineApplyReport ApplyReadyStartTimeline(
    bf6_ctx* context, rime::Screen& screen)
{
    AuthoredTimelineApplyReport report;
    static constexpr const char* kStart =
        "game/glacierflow/flow_mainmenu/ui/screens/bootflowstartscreen";
    if (!context || screen.partition != kStart) return report;

    const int count = bf6_rime_float_tracks(
        context, screen.partition.c_str(), nullptr, 0);
    if (count <= 0) return report;
    std::vector<bf6_rime_float_track> tracks((size_t)count);
    if (bf6_rime_float_tracks(context, screen.partition.c_str(),
                              tracks.data(), count) != count)
        return report;
    report.tracks = count;
    const uint32_t alpha = rime::property_hash("Alpha");
    for (const bf6_rime_float_track& track : tracks)
    {
        if (track.target_field != alpha) continue;
        ++report.alpha_targets;
        std::vector<bf6_rime_float_key> keys((size_t)track.key_count);
        const int key_count = bf6_rime_float_track_keys(
            context, screen.partition.c_str(), track.track_instance,
            keys.data(), track.key_count);
        if (key_count <= 0 || key_count != track.key_count) continue;
        report.keys += key_count;
        int exact = 0;
        for (rime::Element& element : screen.elements)
            if (element.partition == screen.partition &&
                element.instance == track.target_instance)
            {
                element.alpha = keys.back().value;
                element.runtime_alpha_unresolved = false;
                ++exact;
            }
        report.applied += exact;
        report.ambiguous += exact > 1;
        for (const rime::Element& element : screen.elements)
            report.mutated_target_matches +=
                element.partition == screen.partition &&
                element.instance == (track.target_instance ^ 0x40000000);
    }
    return report;
}

static bool NavigateStandaloneBack()
{
    if (RequestRuntimeUiBack())
    {
        PlayMenuSound(MenuSound::Back);
        std::fprintf(stderr, "Rime router Back -> pop [offline policy]\n");
        return true;
    }
    if (NavigateArmoryBack()) {
        PlayMenuSound(MenuSound::Back);
        return true;
    }
    const bool displayScreen = g_screenIdx >= 0 &&
        g_screenIdx < static_cast<int>(g_screens.size()) &&
        g_screens[static_cast<size_t>(g_screenIdx)].partition ==
            kDisplaySettingsScreen;
    if (displayScreen)
    {
        const bool selected = SelectFrontendPartition(
            "common/ui/home/screens/home_screen");
        if (selected)
        {
            PlayMenuSound(MenuSound::Back);
            std::fprintf(stderr,
                "Display settings back -> home_screen "
                "[optionsmenu_screenshub offline provider policy]\n");
        }
        return selected;
    }
    if (g_loadoutRoutePage != LoadoutRoutePage::None)
    {
        if (g_loadoutRoutePage == LoadoutRoutePage::CharacterSelect)
        {
            g_loadoutRoutePage = LoadoutRoutePage::Appearance;
            PlayMenuSound(MenuSound::Back);
            return true;
        }
        if (g_loadoutRoutePage == LoadoutRoutePage::VehicleSkinPicker)
        {
            g_loadoutRoutePage = LoadoutRoutePage::VehicleCosmetics;
            PlayMenuSound(MenuSound::Back);
            return true;
        }
        const LoadoutRoutePage leavingRoute = g_loadoutRoutePage;
        const char* parent = nullptr;
        if (g_loadoutRoutePage == LoadoutRoutePage::FieldUpgrades)
            parent = "common/ui/loadout/menu/screens/menuloadoutoverviewscreen";
        else if (g_loadoutRoutePage == LoadoutRoutePage::VehicleLoadout)
            parent = "common/ui/vehicles/shared/screens/"
                     "menuvehicle_archetypescreen";
        else if (g_loadoutRoutePage == LoadoutRoutePage::VehicleCosmetics)
            parent = "common/ui/vehicles/shared/screens/"
                     "menuvehicle_loadoutscreen";
        else if (g_loadoutRoutePage == LoadoutRoutePage::Appearance)
            parent = "common/ui/loadout/menu/screens/menuloadoutclassselectscreen";
        else if (g_loadoutRoutePage ==
                 LoadoutRoutePage::CharacterCustomization)
            parent = "common/ui/soldier/shared/screens/menucharacterselect_view";
        else if (g_loadoutRoutePage == LoadoutRoutePage::Vehicles)
            parent = "common/ui/loadout/menu/screens/menuloadoutclassselectscreen";
        else if (g_loadoutRoutePage == LoadoutRoutePage::Equipment)
            parent = "common/ui/loadout/menu/screens/menuloadoutoverviewscreen";
        else if (g_loadoutRoutePage == LoadoutRoutePage::Overview)
            parent = "common/ui/loadout/menu/screens/menuloadoutclassselectscreen";
        else
            parent = "common/ui/home/screens/home_screen";
        const bool selected = SelectFrontendPartition(parent);
        if (selected)
        {
            if (leavingRoute == LoadoutRoutePage::CharacterCustomization)
                g_loadoutRoutePage = LoadoutRoutePage::CharacterSelect;
            g_loadoutInventoryActive = false;
            PlayMenuSound(MenuSound::Back);
            std::fprintf(stderr, "Loadout route back -> %s\n", parent);
        }
        return selected;
    }
    const bool homeScreen = g_screenIdx >= 0 &&
        g_screenIdx < static_cast<int>(g_screens.size()) &&
        g_screens[static_cast<size_t>(g_screenIdx)].partition ==
            "common/ui/home/screens/home_screen";
    if (homeScreen)
    {
        const bool selected = SelectFrontendPartition(
            "game/glacierflow/flow_mainmenu/ui/screens/bootflowstartscreen");
        if (selected)
        {
            PlayMenuSound(MenuSound::Back);
            std::fprintf(stderr,
                "Home back -> bootflowstartscreen "
                "[offline provider policy]\n");
        }
        return selected;
    }
    if (!g_showArmory) return false;
    const bool selected = SelectFrontendPartition(
        "common/ui/home/screens/home_screen");
    if (selected)
    {
        PlayMenuSound(MenuSound::Back);
        std::fprintf(stderr,
            "Weapons back -> home_screen "
            "[installed LOADOUTS parent route; offline provider policy]\n");
    }
    return selected;
}

static const std::string* CurrentFrontendPartition()
{
    if (g_screenIdx < 0 || g_screenIdx >= (int)g_screens.size())
        return nullptr;
    return &g_screens[(size_t)g_screenIdx].partition;
}

